(() => {
    if (!window.Jodit) {
        return;
    }
    const options = {
        width: "100%",
        height: "100%",
        showWordsCounter: false,
        showCharsCounter: false,
        showPlaceholder: false,
        askBeforePasteHTML: false,
        toolbarAdaptive: false,
        addNewLineOnDBLClick: false,
        hidePoweredByJodit: true,
        extraPlugins: [ "emm", "emoji", "table-props" ],
        cleanHTML: {
            timeout: 500,
            removeEmptyTags: false,
            fillEmptyParagraph: false,
            replaceNBSP: false,
            removeEmptyElements: false,
            removeEmptyAttributes: false,
            removeOnError: false,
            replaceOldTags: false
        },
        link: {
            processPastedLink: false
        },
        colors: {
            full: [ "#000000", "#993300", "#333300", "#003300", "#003366", "#000080", "#333399", "#333333", "#800000", "#FF6600", "#808000", "#808080", "#008080", "#0000FF", "#666699", "#808080", "#FF0000", "#FF9900", "#99CC00", "#339966", "#33CCCC", "#3366FF", "#800080", "#999999", "#FF00FF", "#FFCC00", "#FFFF00", "#00FF00", "#00FFFF", "#00CCFF", "#993366", "#C0C0C0", "#FF99CC", "#FFCC99", "#FFFF99", "#CCFFCC", "#CCFFFF", "#99CCFF", "#CC99FF", "#FFFFFF" ]
        },
        colorPickerDefaultTab: "color",
        wrapNodes: {
            emptyBlockAfterInit: false
        },
        enter: "br",
        enterBlock: "div",
        iframe: true,
        iframeSandbox: "allow-forms allow-same-origin",
        iframeDefaultSrc: "<html><head><title></title></head><body></body></html>",
        iframeStyle: "",
        iframeTitle: "",
        iframeCSSLinks: [ AGN.url("/assets/jodit.css") ],
        controls: {
            font: {
                list: {
                    "Comic Sans MS,cursive": "Comic Sans MS"
                }
            }
        }
    };
    _.merge(Jodit.defaultOptions, options);
    Jodit.defaultOptions.controls.font.list = Object.fromEntries(Object.entries(Jodit.defaultOptions.controls.font.list).sort(([, valueA], [, valueB]) => valueA.localeCompare(valueB)));
    function extendLinkPlugin() {
        const originalFormTemplate = Jodit.defaultOptions.link.formTemplate;
        const formTemplateFn = editor => {
            const html = originalFormTemplate(editor);
            $(html.container).prepend(`\n        <div class="jodit-ui-block jodit-ui-block_align_left">\n          <div class="jodit-ui-input jodit-ui-block__link-type">\n            <span class="jodit-ui-input__label">${t("wysiwyg.dialogs.link.type")}</span>\n            <div class="jodit-ui-input__wrapper">\n              <select name="link_type" class="jodit-select">\n                <option value="">URL</option>\n                <option value="email">${t("wysiwyg.dialogs.link.email_type")}</option>\n                <option value="phone">${t("wysiwyg.dialogs.link.phone_type")}</option>\n              </select>\n            </div>\n          </div>\n        </div>\n      \n        <div class="jodit-ui-block jodit-ui-block_align_left" style="display: none">\n          <div class="jodit-ui-input jodit-ui-block__phone-number">\n            <span class="jodit-ui-input__label">${t("wysiwyg.dialogs.link.phone_number")} *</span>\n            <div class="jodit-ui-input__wrapper">\n              <input class="jodit-ui-input__input" name="phone-number" type="tel">\n            </div>\n          </div>\n        </div>\n      \n        <div class="jodit-ui-block jodit-ui-block_align_left" style="display: none">\n          <div class="jodit-ui-input jodit-ui-block__email-address">\n            <span class="jodit-ui-input__label">${t("wysiwyg.dialogs.link.email_address")} *</span>\n            <div class="jodit-ui-input__wrapper">\n              <input class="jodit-ui-input__input" name="email-address" type="text">\n            </div>\n          </div>\n        </div>\n      \n        <div class="jodit-ui-block jodit-ui-block_align_left" style="display: none">\n          <div class="jodit-ui-input jodit-ui-block__email-subject">\n            <span class="jodit-ui-input__label">${t("wysiwyg.dialogs.link.subject")}</span>\n            <div class="jodit-ui-input__wrapper">\n              <input class="jodit-ui-input__input" name="email-subject" type="text">\n            </div>\n          </div>\n        </div>\n      \n        <div class="jodit-ui-block jodit-ui-block_align_left" style="display: none">\n          <div class="jodit-ui-input jodit-ui-block__email-body">\n            <span class="jodit-ui-input__label">${t("wysiwyg.dialogs.link.content")}</span>\n            <div class="jodit-ui-input__wrapper">\n              <input class="jodit-ui-input__input" name="email-body" type="text">\n            </div>\n          </div>\n        </div>\n      `);
            return html;
        };
        Jodit.defaultOptions.link.formTemplate = formTemplateFn;
        const linkPlugin = Jodit.plugins.get("link");
        const originalGenerateForm = linkPlugin.prototype.__generateForm;
        const originalAfterInit = linkPlugin.prototype.afterInit;
        linkPlugin.prototype.afterInit = function(...args) {
            originalAfterInit.apply(this, args);
            const [jodit] = args;
            jodit.e.on("dblclick.link", e => {
                if ($(e.target).is("a")) {
                    $(jodit.container).find(".jodit-toolbar-button_link button:visible").first().trigger("click");
                }
            });
        };
        linkPlugin.prototype.__generateForm = function(...args) {
            const res = originalGenerateForm.apply(this, args);
            const originalValidateFn = res.validate;
            const $form = $(res.container);
            const $phoneNumber = $form.find(".jodit-ui-block__phone-number input");
            const $emailAddress = $form.find(".jodit-ui-block__email-address input");
            const $emailSubject = $form.find(".jodit-ui-block__email-subject input");
            const $emailBody = $form.find(".jodit-ui-block__email-body input");
            const $url = $form.find(".jodit-ui-block__url input");
            const $linkType = $form.find(".jodit-ui-block__link-type select");
            const $submitBtn = $form.find('button[type="submit"]');
            const $emailFields = [ $emailAddress, $emailSubject, $emailBody ];
            res.validate = function(...args) {
                const isValid = originalValidateFn.apply(this, args);
                if (!isValid) {
                    return false;
                }
                const showFieldError = ($field, text) => {
                    AGN.Lib.Form.cleanFieldFeedback$($field);
                    AGN.Lib.Form.appendFeedbackMessage($field, text);
                    AGN.Lib.Form.markField($field);
                };
                if ($linkType.val() === "email") {
                    const email = $emailAddress.val();
                    if (!AGN.Lib.Helpers.isValidEmail(email)) {
                        showFieldError($emailAddress, t("defaults.invalidEmail"));
                        return false;
                    }
                } else if ($linkType.val() === "") {
                    const url = $url.val();
                    if (!AGN.Lib.Helpers.isUrl(url) && !AGN.Lib.Helpers.isAgnTag(url)) {
                        showFieldError($url, t("url.invalid"));
                        return false;
                    }
                }
                return true;
            };
            function updateSubmitBtn() {
                $submitBtn.prop("disabled", $emailAddress.is(":visible") && !$emailAddress.val() || $phoneNumber.is(":visible") && !$phoneNumber.val());
            }
            function toggleInput($input, show = false) {
                $input.closest(".jodit-ui-block").toggle(show);
            }
            $linkType.on("change", function() {
                [ ...$emailFields, $phoneNumber ].forEach($e => toggleInput($e));
                toggleInput($url, true);
                const linkType = $(this).val();
                if (linkType === "phone") {
                    toggleInput($phoneNumber, true);
                    toggleInput($url);
                } else if (linkType === "email") {
                    $emailFields.forEach($e => toggleInput($e, true));
                    toggleInput($url);
                } else {
                    $url.val("");
                }
                updateSubmitBtn();
            });
            function updateMailLink() {
                const email = $emailAddress.val().trim();
                const subject = $emailSubject.val().trim();
                const body = $emailBody.val().trim();
                let link = "";
                if (email) {
                    link = `mailto:${email}`;
                    const params = [];
                    if (subject) params.push(`subject=${encodeURIComponent(subject)}`);
                    if (body) params.push(`body=${encodeURIComponent(body)}`);
                    if (params.length) {
                        link += `?${params.join("&")}`;
                    }
                }
                $url.val(link);
            }
            [ $emailAddress, $emailSubject, $emailBody ].forEach($e => $e.on("input", () => {
                updateMailLink();
                updateSubmitBtn();
            }));
            $phoneNumber.on("input", function() {
                const number = $(this).val();
                $url.val(number.length ? `tel:${number}` : "");
                updateSubmitBtn();
            });
            const url = $url.val();
            if (url.startsWith("tel:")) {
                $phoneNumber.val(url.substring(4).trim());
                $linkType.val("phone").trigger("change");
            } else if (url.startsWith("mailto:")) {
                const mailto = url.substring(7);
                const [emailPart, queryPart] = mailto.split("?", 2);
                $emailAddress.val(emailPart);
                if (queryPart) {
                    const params = new URLSearchParams(queryPart);
                    $emailSubject.val(params.get("subject") || "");
                    $emailBody.val(params.get("body") || "");
                }
                $linkType.val("email").trigger("change");
            }
            return res;
        };
    }
    extendLinkPlugin();
})();

(() => {
    if (!window.Jodit) {
        return;
    }
    Jodit.modules.Icon.set("wrap-text-in-p", `<i class="icon icon-code"></i>`);
    const MAILING_IMAGES_MAP_CACHE = new Map;
    let MEDIAPOOL_IMAGES;
    const NUMERIC_CHAR_REFERENCE_RE = /&#(x[0-9a-f]+|[0-9]+);/gi;
    const LITERAL_INVISIBLE_RE = /[\u200B-\u200D\u2060\uFEFF]/g;
    const PRESERVE_NEWLINES_BLOCKS_RE = /(<(pre|script|style|textarea)\b[^>]*>[\s\S]*?<\/\2>)|[\n\r]+/gi;
    function removeWhitespaceHtmlEntities(html) {
        if (!html) {
            return html;
        }
        let result = html.replace(NUMERIC_CHAR_REFERENCE_RE, (match, ref) => {
            const isHex = ref[0].toLowerCase() === "x";
            const codePoint = Number.parseInt(isHex ? ref.slice(1) : ref, isHex ? 16 : 10);
            if (codePoint === 32 || codePoint === 9) {
                return match;
            }
            if (codePoint >= 10 && codePoint <= 13) {
                return "";
            }
            try {
                const char = String.fromCodePoint(codePoint);
                if (/\s/.test(char) || /[\u200B-\u200D\u2060\uFEFF]/.test(char)) {
                    return "";
                }
            } catch (e) {
                console.error("Error on whitespace handler", e);
            }
            return match;
        });
        result = result.replace(LITERAL_INVISIBLE_RE, "");
        result = result.replace(PRESERVE_NEWLINES_BLOCKS_RE, (match, preservedBlock) => {
            if (preservedBlock) {
                return preservedBlock;
            }
            return "";
        });
        return result;
    }
    const TOOLBARS = {
        Full: [ {
            buttons: [ "cut", "copy", "paste" ]
        }, {
            buttons: [ "undo", "redo" ]
        }, {
            buttons: [ "find", "selectall", "spellcheck" ]
        }, {
            buttons: [ "link", "image", "table-props", "hr", "symbols" ]
        }, {
            buttons: [ "font", "fontsize", "paragraph", "brush" ]
        }, {
            buttons: [ "bold", "italic", "underline", "strikethrough", "superscript", "subscript" ]
        }, {
            buttons: [ "eraser", "align" ]
        }, {
            buttons: [ "ul", "ol" ]
        }, {
            buttons: [ "outdent", "indent" ]
        }, {
            buttons: [ "emm-tag", "emoji", "wrap-text-in-p" ]
        } ],
        Trimmed: [ {
            buttons: [ "cut", "copy", "paste" ]
        }, {
            buttons: [ "undo", "redo" ]
        }, {
            buttons: [ "find", "link", "symbols" ]
        }, {
            buttons: [ "bold", "italic", "underline", "strikethrough", "superscript", "subscript" ]
        }, {
            buttons: [ "eraser", "outdent", "indent" ]
        }, {
            buttons: [ "emm-tag", "emoji", "wrap-text-in-p" ]
        } ],
        EMM: [ {
            buttons: [ "cut", "copy", "paste" ]
        }, {
            buttons: [ "undo", "redo" ]
        }, {
            buttons: [ "find", "selectall" ]
        }, {
            buttons: [ "link", "image", "table-props", "hr", "symbols" ]
        }, {
            buttons: [ "font", "fontsize", "paragraph", "brush" ]
        }, {
            buttons: [ "bold", "italic", "underline", "strikethrough", "superscript", "subscript" ]
        }, {
            buttons: [ "eraser", "align" ]
        }, {
            buttons: [ "ul", "ol" ]
        }, {
            buttons: [ "outdent", "indent" ]
        }, {
            buttons: [ "emm-tag", "emoji", "wrap-text-in-p" ]
        } ],
        EMC: [ {
            buttons: [ "cut", "copy", "paste" ]
        }, {
            buttons: [ "undo", "redo" ]
        }, {
            buttons: [ "find", "selectall" ]
        }, {
            buttons: [ "link", "symbols" ]
        }, {
            buttons: [ "font", "fontsize", "paragraph", "brush", "align" ]
        }, {
            buttons: [ "ul", "ol" ]
        }, {
            buttons: [ "bold", "italic", "underline", "strikethrough", "superscript", "subscript" ]
        }, {
            buttons: [ "eraser", "emm-tag", "emoji", "wrap-text-in-p" ]
        } ]
    };
    Jodit.plugins.add("emm", editor => {
        editor.options.buttons = TOOLBARS[editor.options.emmToolbarType] || TOOLBARS.EMM;
        editor.options.controls["emm-tag"] = {
            icon: `<svg><use href="${AGN.url(`/assets/core/images/wysiwyg/wysiwyg-icon-sprite.svg#agn_tag`, true)}"></use></svg>`,
            tooltip: t("wysiwyg.dialogs.agn_tags.tooltip"),
            exec: editor => {
                AGN.Lib.Confirm.request(AGN.url("/wysiwyg/dialogs/agn-tags.action")).done(code => insertContent(editor, code));
            }
        };
        editor.options.controls["wrap-text-in-p"] = {
            icon: "wrap-text-in-p",
            tooltip: t("wysiwyg.wrapTextInP"),
            isDisabled: editor => editor.s.isCollapsed() || Boolean(editor.s.current() && Jodit.modules.Dom.closest(editor.s.current(), "p", editor.editor)),
            exec: editor => {
                editor.s.commitStyle({
                    element: "p"
                });
                editor.synchronizeValues();
            }
        };
        const mailingId = editor.options.emmMailingId;
        if (mailingId && !MAILING_IMAGES_MAP_CACHE.get(mailingId)) {
            MAILING_IMAGES_MAP_CACHE.set(mailingId, getMailingImages(mailingId));
        }
        if (!MEDIAPOOL_IMAGES) {
            MEDIAPOOL_IMAGES = getMediapoolImages();
        }
        if (mailingId && !window.isOpenEmm) {
            const imagePopupMethod = Jodit.defaultOptions.controls.image.popup;
            editor.options.controls.image.popup = function(editor, current, close) {
                const popup = imagePopupMethod.apply(this, Array.prototype.slice.apply(arguments));
                const topicId = `image-browser:selectedLink:${editor.id}`;
                AGN.Lib.Messaging.unsubscribe(topicId);
                if (!popup.querySelector(".jodit-ui-button--browse-server")) {
                    createBrowseServerBtn(popup);
                }
                AGN.Lib.Messaging.subscribe(topicId, link => {
                    const img = editor.s.insertImage(link);
                    editor.e.fire("openImageProperties", img);
                });
                return popup;
            };
            function createBrowseServerBtn(popup) {
                const link = AGN.url(`/wysiwyg/image-browser.action?mailingID=${mailingId}&editorId=${editor.id}`);
                const insertBtn = popup.querySelector(".jodit-ui-form .jodit-ui-button");
                const btn = insertBtn.cloneNode(true);
                btn.classList.add("jodit-ui-button--browse-server");
                btn.querySelector(".jodit-ui-button__text").textContent = "Browse server";
                btn.style.marginLeft = "5px";
                btn.setAttribute("type", "button");
                btn.setAttribute("data-popup", "");
                btn.setAttribute("data-popup-options", `width: 1200, height: 630, url: ${link}`);
                insertBtn.parentNode.appendChild(btn);
                return btn;
            }
        }
        function processContent(content) {
            if (!content) {
                return content;
            }
            content = removeWhitespaceHtmlEntities(content);
            content = processUrls(content, mailingId);
            content = AGN.Lib.Helpers.prettifyHtml(content);
            content = AGN.Lib.Helpers.unescapeAgnTags(content);
            return AGN.Lib.Helpers.unescapeVelocityDirectives(content);
        }
        if (editor.options.editHTMLDocumentMode) {
            editor.events.on("beforeGetNativeEditorValue", function(options) {
                if (options?.fromEmmPlugin) {
                    return "";
                }
                let content = editor.e.fire("beforeGetNativeEditorValue", {
                    fromEmmPlugin: true
                });
                editor.e.stopPropagation("beforeGetNativeEditorValue");
                content = AGN.Lib.Helpers.prettifyHtml(content);
                return processContent(content);
            });
            editor.events.on("beforeSetNativeEditorValue", function(data) {
                if ((editor.options.iframe || editor.options.editHTMLDocumentMode) && !editor.history.canUndo()) {
                    data.value = "";
                }
            });
            editor.events.on("beforeSetElementValue", function(data) {
                if (editor._initialRawValue === undefined) {
                    editor._initialRawValue = editor.element.value;
                    editor._initialHasHtmlStructure = isFullHtmlDocument(editor._initialRawValue);
                    editor._initialBodyHtml = extractBodyHtml(editor._initialRawValue);
                    editor._initialHasDefaultHead = editor._initialHasHtmlStructure && hasEmptyTitleHead(editor._initialRawValue);
                }
                if (data.value === editor._initialRawValue) {
                    return;
                }
                const doc = parseHtml(data.value);
                const linksToRemove = editor.o.iframeCSSLinks.map(cssLink => doc.head.querySelector(`link[rel="stylesheet"][href="${cssLink}"]`)).filter(el => !!el);
                if (linksToRemove.length) {
                    linksToRemove.forEach(el => {
                        const nextElement = el.nextSibling;
                        if (nextElement?.nodeType === Node.TEXT_NODE && nextElement.textContent.trim() === "") {
                            nextElement.remove();
                        }
                        el.remove();
                    });
                    let newValue = `${editor.o.iframeDoctype}\n${doc.documentElement.outerHTML}`;
                    newValue = AGN.Lib.Helpers.prettifyHtml(newValue);
                    newValue = AGN.Lib.Helpers.unescapeAgnTags(newValue);
                    data.value = AGN.Lib.Helpers.unescapeVelocityDirectives(newValue);
                }
                const bodyHtml = doc.body.innerHTML.trim();
                if (editor._initialRawValue.trim() === "" && isBodyEmpty(bodyHtml)) {
                    data.value = "";
                } else if (editor._initialHasHtmlStructure) {
                    if (editor._initialBodyHtml.trim() === bodyHtml) {
                        data.value = editor._initialRawValue;
                    } else if (editor._initialHasDefaultHead && isBodyEmpty(bodyHtml)) {
                        data.value = "";
                    }
                } else if (isBodyEmpty(bodyHtml)) {
                    data.value = "";
                }
            });
            function extractBodyHtml(str) {
                return parseHtml(str).body.innerHTML;
            }
            function isBodyEmpty(bodyHtml) {
                return bodyHtml === "" || bodyHtml === "<br>";
            }
            function hasEmptyTitleHead(str) {
                const doc = parseHtml(str);
                const head = doc.head;
                if (!head) {
                    return false;
                }
                const headChildren = Array.from(head.children);
                if (headChildren.length !== 1) {
                    return false;
                }
                const title = headChildren[0];
                if (title.tagName.toLowerCase() !== "title") {
                    return false;
                }
                return title.textContent.trim() === "";
            }
            function isFullHtmlDocument(str) {
                const hasTags = /<html[\s\S]*?>/i.test(str) && /<head[\s\S]*?>/i.test(str) && /<body[\s\S]*?>/i.test(str);
                if (!hasTags) {
                    return false;
                }
                const doc = parseHtml(str);
                return !!(doc.documentElement && doc.head && doc.body);
            }
            function parseHtml(html) {
                html = AGN.Lib.Helpers.escapeAgnTags(html);
                html = AGN.Lib.Helpers.escapeVelocityDirectives(html);
                return (new DOMParser).parseFromString(html, "text/html");
            }
        } else {
            editor.events.on("afterGetValueFromEditor", data => {
                data.value = processContent(data.value);
            });
        }
        editor.events.on("processPaste", function(e, text) {
            if (e.clipboardData?.types?.includes("text/html")) {
                return text.replace(/<(\w+)([^>]*)>/g, (match, tag, attrs) => {
                    const cleaned = attrs.replace(/\s+(?!href=|src=)[\w:-]+(?:=(["']).*?\1)?/g, "");
                    return `<${tag}${cleaned}>`;
                }).replace(/<path[^>]*>\s*<\/path>/g, "").replace(/<svg[^>]*>\s*<\/svg>/g, "");
            }
            return undefined;
        });
        function escapeForNativeWrite(html) {
            if (!html) {
                return html;
            }
            html = removeWhitespaceHtmlEntities(html);
            html = AGN.Lib.Helpers.escapeAgnTags(replaceAgnImageTags(html, mailingId));
            return AGN.Lib.Helpers.escapeVelocityDirectives(html);
        }
        editor.events.on("beforeSetValueToEditor", html => escapeForNativeWrite(html));
        editor.events.on("beforePasteInsert", html => processContent(html));
        editor.events.on("beforeSetNativeEditorValue", function(data) {
            data.value = escapeForNativeWrite(data.value);
        }, {
            top: true
        });
        editor.events.on("beforeCommand", command => {
            if (command.toLowerCase() === "delete") {
                const selection = editor.s;
                const range = selection.range;
                const startElement = range.startContainer.nodeType === Node.TEXT_NODE ? range.startContainer.parentElement : range.startContainer;
                const caption = startElement ? startElement.closest("caption") : null;
                if (caption && !selection.isCollapsed()) {
                    const selectedText = selection.sel.toString().replace(/\uFEFF/g, "").trim();
                    const captionText = caption.textContent.replace(/\uFEFF/g, "").trim();
                    if (selectedText.length >= captionText.length) {
                        caption.innerHTML = "<br>";
                        selection.setCursorIn(caption);
                        return false;
                    }
                }
            }
        });
        editor.e.on("backSpaceBeforeCases", (backspace, fakeNode) => {
            const caption = fakeNode.parentElement ? fakeNode.parentElement.closest("caption") : null;
            if (caption) {
                const textContent = caption.textContent.replace(/\uFEFF/g, "").trim();
                if (textContent === "") {
                    if (!caption.querySelector("br")) {
                        caption.innerHTML = "<br>";
                    }
                    editor.s.setCursorIn(caption);
                    return true;
                }
            }
        });
    });
    function insertContent(editor, content) {
        if (content) {
            editor.s.insertHTML(content);
            editor.synchronizeValues();
        }
    }
    function replaceAgnImageTags(data, mailingId) {
        const mailingImagesUrlsMap = MAILING_IMAGES_MAP_CACHE.get(mailingId);
        if (!mailingImagesUrlsMap && !Object.keys(MEDIAPOOL_IMAGES).length) {
            return data;
        }
        return AGN.Lib.Helpers.replaceAgnTags(data, (tag, tagHtml) => {
            if (tag.name === "agnIMAGE" && tag.attributes["name"]) {
                let imageUrl = mailingImagesUrlsMap[tag.attributes.name];
                if (imageUrl) {
                    return encodeURI(imageUrl);
                }
                imageUrl = MEDIAPOOL_IMAGES[tag.attributes.name];
                if (imageUrl) {
                    return encodeURI(imageUrl);
                }
            }
            return tagHtml;
        });
    }
    function getMailingImages(mailingId) {
        let result;
        $.ajax({
            url: AGN.url("/wysiwyg/mailing/images.action"),
            type: "GET",
            async: false,
            data: {
                mailingId: mailingId
            },
            success: json => result = json
        });
        return result;
    }
    function getMediapoolImages() {
        if (window.isOpenEmm) {
            return {};
        }
        let result;
        $.ajax({
            url: AGN.url("/wysiwyg/mediapool/images.action"),
            type: "GET",
            async: false,
            success: json => result = json
        });
        return result;
    }
    function processUrls(content, mailingId) {
        const mailingImagesUrlsMap = MAILING_IMAGES_MAP_CACHE.get(mailingId);
        if (!mailingImagesUrlsMap && !Object.keys(MEDIAPOOL_IMAGES).length) {
            return content;
        }
        const urls = content.match(/https?:\/\/[\w\-._~:\/?#@!$&'()*+,;=%]+/g);
        if (!urls) {
            return content;
        }
        const urlToImageNameMap = {};
        Object.keys(mailingImagesUrlsMap).forEach(key => {
            urlToImageNameMap[mailingImagesUrlsMap[key]] = key;
        });
        Object.keys(MEDIAPOOL_IMAGES).forEach(key => {
            urlToImageNameMap[MEDIAPOOL_IMAGES[key]] = key;
        });
        urls.forEach(url => {
            let normalizedUrl = url.replace(/(\/mediapool_element)(\/\d+)?(\/\d+\/\d+\/0\/\d+)(\.\w+)?/, function(match, $1, $2, $3) {
                return $1 + $3;
            });
            try {
                normalizedUrl = decodeURI(normalizedUrl);
            } catch (e) {
                console.error("Error with encoding URL: " + normalizedUrl);
            }
            normalizedUrl = normalizedUrl.replaceAll("&amp;", "&");
            const imageName = urlToImageNameMap[normalizedUrl];
            if (imageName) {
                content = content.replace(url, `[agnIMAGE name='${imageName}']`);
            }
        });
        return content.replaceAll("&amp;", "&");
    }
})();

(() => {
    if (!window.Jodit) {
        return;
    }
    const POPUP_TEMPLATE = `\n    <div class="jodit-emoji">\n      <div class="jodit-emoji__header">\n        <input type="text" placeholder="Search" class="jodit-emoji__search-input form-control">\n      </div>\n      \n      <div class="jodit-emoji__body">\n          {{ _.each(Object.keys(emojis), group => { }}\n            <div class="jodit-emoji__group" data-jodit-emoji-group="{{- group }}">\n                <h1 class="jodit-emoji__group-name">{{- t('wysiwyg.dialogs.emoji.groups.' + group) }}</h1>\n                \n                <div class="jodit-emoji__group-content">\n                  {{ _.each(emojis[group], emoji => { }}\n                      <a class="jodit-emoji__symbol" data-jodit-emoji-id="{{- emoji.id }}" type="button">{{- emoji.symbol }}</a>\n                  {{ }) }}\n                </div>\n            </div>\n          {{ }) }}\n      </div>\n    </div>\n  `;
    Jodit.modules.Icon.set("smile", `<i class="icon icon-smile"></i>`);
    Jodit.plugins.add("emoji", editor => {
        let emojis;
        $.get(Jodit.BASE_PATH + "emoji.json").success(json => emojis = _.groupBy(json, "group"));
        editor.options.controls["emoji"] = {
            icon: "smile",
            tooltip: t("wysiwyg.emoji"),
            popup: (editor, current, close) => {
                setTimeout(() => {
                    $(document).off("click", ".jodit-emoji__symbol");
                    $(document).off("input", ".jodit-emoji__search-input");
                    $(document).on("click", ".jodit-emoji__symbol", function() {
                        editor.s.insertHTML($(this).text());
                        close();
                    });
                    $(document).on("input", ".jodit-emoji__search-input", function() {
                        const searchText = $(this).val().toUpperCase();
                        const groupNames = Object.keys(emojis);
                        groupNames.forEach(group => {
                            let hasMatchedItem = false;
                            emojis[group].forEach(emoji => {
                                const matches = !!emoji.keywords.find(kw => kw.toUpperCase().includes(searchText));
                                $(`[data-jodit-emoji-id="${emoji.id}"]`).toggle(matches);
                                if (matches) {
                                    hasMatchedItem = true;
                                }
                            });
                            $(`[data-jodit-emoji-group="${group}"]`).toggle(hasMatchedItem);
                        });
                    });
                }, 0);
                return _.template(POPUP_TEMPLATE)({
                    emojis: emojis
                });
            }
        };
    });
})();

