            radio_empty: t("querybuilder.errors.radio_empty"),
            checkbox_empty: t("querybuilder.errors.checkbox_empty"),
            select_empty: t("querybuilder.errors.select_empty"),
            string_empty: t("querybuilder.errors.string_empty"),
            string_exceed_min_length: t("querybuilder.errors.string_exceed_min_length"),
