(function() {
    function setViaClipboardApi(value, callback) {
        try {
            navigator.clipboard.writeText(value).then(function() {
                callback(true);
            }, function() {
                callback(false);
            });
        } catch (e) {
            console.warn(e);
            callback(false);
        }
    }
    function setViaTempInput(value, callback) {
        var success = true;
        try {
            var $input = $("<input>");
            $("body").append($input);
            $input.val(value);
            $input.select();
            document.execCommand("copy");
            $input.remove();
        } catch (e) {
            console.warn(e);
            success = false;
        }
        if (callback) {
            callback(success);
        }
    }
    AGN.Lib.Clipboard = {
        set: function(value, callback) {
            setViaClipboardApi(value, function(success1) {
                if (success1) {
                    if (callback) {
                        callback(value, true);
                    }
                } else {
                    setViaTempInput(value, function(success2) {
                        if (callback) {
                            callback(value, success2);
                        }
                    });
                }
            });
        }
    };
})();

(() => {
    class Colorpicker {
        static DATA_KEY="agn:colorpicker";
        static get($el) {
            return $el.data(Colorpicker.DATA_KEY);
        }
        constructor($el) {
            this.$el = $el;
            this.$trigger = this.#createTriggerInput();
            $el.spectrum({
                showInput: true,
                allowEmpty: true,
                preferredFormat: "hex",
                move: color => {
                    $el.val(color.toHexString());
                    this.$trigger.val(color.toHexString());
                    this.#updatePipetteColor(color);
                },
                change: color => {
                    this.#updatePipetteColor(color);
                }
            });
            this.#updatePipetteColor($el.spectrum("get"));
            $el.data(Colorpicker.DATA_KEY, this);
        }
        #createTriggerInput() {
            const $input = this.$el.clone();
            if (this.$el.attr("id")) {
                $input.attr("id", this.$el.attr("id") + "_colorpicker");
            }
            $input.attr("name", "");
            $input.removeClass("js-colorpicker");
            this.$el.before($input);
            $input.on("input", () => {
                const color = $input.val();
                this.$el.spectrum("set", color);
                this.#updatePipetteColor(this.$el.spectrum("get"));
            });
            $input.on("blur", () => $input.val(this.$el.val()));
            this.$el.on("change", () => {
                $input.val(this.$el.val());
                this.$el.spectrum("set", this.$el.val());
            });
            return $input;
        }
        #updatePipetteColor(selectedColor) {
            const color = selectedColor ? this.#invertColor(selectedColor.toHexString()) : this.$el.css("--bs-body-color");
            this.$el.parent().find(".sp-preview").css("color", color);
        }
        #invertColor(hex) {
            return AGN.Lib.Helpers.getColorLuminance(hex) > .5 ? "#000" : "#FFF";
        }
    }
    AGN.Lib.Colorpicker = Colorpicker;
})();

(() => {
    class Confirm {
        constructor($modal, deferred) {
            this.$modal = $modal;
            this.deferred = deferred || $.Deferred();
        }
        promise() {
            return this.deferred.promise();
        }
        positive(resp) {
            this.deferred.resolve(resp);
            this.$modal.modal("hide");
            this.$modal.remove();
        }
        negative(resp) {
            this.deferred.reject(resp);
            this.$modal.modal("hide");
            this.$modal.remove();
        }
        static get($needle) {
            const $confirm = Confirm.getWrapper($needle);
            return $confirm.data("_confirm");
        }
        static getWrapper($needle) {
            return $needle.closest(".modal");
        }
        static create(html, deferred) {
            const modal = AGN.Lib.Modal.create(html);
            const confirm = new Confirm(modal, deferred);
            if (modal) {
                modal.data("_confirm", confirm);
            }
            return confirm.promise();
        }
        static from(template, conf = {}, deferred) {
            const modal = AGN.Lib.Modal.fromTemplate(template, conf);
            const confirm = new Confirm(modal, deferred);
            modal.data("_confirm", confirm);
            return confirm.promise();
        }
        static request(source) {
            const deferred = $.Deferred();
            let jqxhr;
            if (_.isString(source)) {
                jqxhr = $.get(source);
            } else {
                jqxhr = source;
            }
            jqxhr.done(resp => {
                const $modal = $(resp).all(".modal");
                if ($modal.length === 1) {
                    const confirm = new Confirm($modal, deferred);
                    $modal.data("_confirm", confirm);
                    AGN.Lib.Modal.create($modal);
                } else if (typeof resp === "object" && "success" in resp) {
                    AGN.Lib.JsonMessages(resp.popups, true);
                    resp.success ? deferred.resolve() : deferred.reject();
                } else {
                    AGN.Lib.Page.render(resp);
                    deferred.reject();
                }
            }).fail(() => deferred.reject());
            return deferred.promise();
        }
    }
    AGN.Lib.Confirm = Confirm;
})();

(function() {
    AGN.Lib.ContextMenu = {
        create: function(params) {
            $.each(params, function(selector, config) {
                $.contextMenu({
                    selector: selector,
                    build: function($element, event) {
                        return build(config, $element, event);
                    }
                });
            });
        }
    };
    function build(config, $element, event) {
        if (config.shown === false || _.isFunction(config.shown) && config.shown($element, event) === false) {
            return false;
        }
        var definitions = config.items;
        if (_.isFunction(definitions)) {
            definitions = definitions($element, event);
        }
        var items = {};
        var count = 0;
        $.each(definitions, function(key, options) {
            if (!_.isFunction(options.shown) || options.shown($element, event) !== false) {
                var item = items[key] = {
                    name: options.name,
                    icon: options.icon
                };
                if (_.isFunction(options.disabled)) {
                    item.disabled = options.disabled($element, event) === true;
                } else if (options.disabled === true) {
                    item.disabled = true;
                }
                if (_.isFunction(options.clicked)) {
                    item.callback = function(k, opts) {
                        options.clicked($element, k, opts);
                    };
                }
                count++;
            }
        });
        return count ? {
            items: items
        } : false;
    }
})();

(() => {
    const Controller = function(func = _.noop) {
        func = _.bind(func, this);
        func(this);
    };
    Controller.prototype.addAction = function(events, action) {
        AGN.Lib.Action.new(AGN.Lib.Action.translate(events), action);
    };
    Controller.prototype.addInitializer = function(name, initializer) {
        AGN.Lib.CoreInitializer.new(name, initializer);
    };
    Controller.prototype.addDomInitializer = function(name, initializer) {
        AGN.Lib.DomInitializer.new(name, initializer);
    };
    Controller.prototype.runInitializer = function(name) {
        AGN.Lib.CoreInitializer.run(name);
    };
    Controller.new = function(name, func) {
        AGN.Opt.Controllers[name] = func;
    };
    Controller.newExtended = function(name, baseName, func) {
        Controller.new(name, instance => {
            const baseController = AGN.Opt.Controllers[baseName];
            if (baseController) {
                _.bind(baseController, instance)(instance);
            }
            _.bind(func, instance)(instance);
        });
    };
    Controller.init = function($scope = $(document)) {
        $scope.all("[data-controller]").each(function() {
            const name = $(this).data("controller");
            const init = AGN.Opt.Controllers[name];
            if (init) {
                if (isClass(init)) {
                    new init;
                } else {
                    new AGN.Lib.Controller(init);
                }
                AGN.Opt.Controllers[name] = undefined;
            }
        });
    };
    function isClass(func) {
        return /^class\s/.test(Function.prototype.toString.call(func));
    }
    AGN.Lib.Controller = Controller;
})();

(function() {
    var map = {};
    function register(name) {
        var dependencies = null;
        var handler;
        if (arguments.length > 2) {
            dependencies = arguments[1];
            handler = arguments[2];
        } else {
            handler = arguments[1];
        }
        if (_.isFunction(handler)) {
            map["key#" + name] = {
                name: name,
                handler: handler,
                dependencies: dependencies
            };
        } else {
            console.error("Handler must be a function");
        }
    }
    function execute($scope, initializer, executed, pending) {
        var key = "key#" + initializer.name;
        if (executed[key]) {
            return;
        }
        if (Array.isArray(initializer.dependencies) && initializer.dependencies.length) {
            pending.push(initializer.name);
            initializer.dependencies.forEach(function(dependencyName) {
                var dependency = map["key#" + dependencyName];
                if (dependency) {
                    if (pending.includes(dependencyName)) {
                        var description = pending.map(function(value) {
                            return "`" + value + "`";
                        }).join(" => ");
                        console.error("Cyclic initializer dependency detected (" + description + " => `" + dependencyName + "`)");
                        return;
                    }
                    execute($scope, dependency, executed, pending);
                } else {
                    console.error("Unknown initializer dependency: `" + name + "`");
                }
            });
            pending.pop();
        }
        try {
            initializer.handler.call(initializer.handler, $scope);
        } catch (e) {
            console.error(e);
        }
        executed[key] = true;
    }
    function autorun($scope) {
        var executed = {};
        var pending = [];
        $.each(map, function(k, initializer) {
            execute($scope, initializer, executed, pending);
        });
    }
    function run(name, $scope) {
        if (Array.isArray(name)) {
            name.forEach(function(nm) {
                run(nm, $scope);
            });
        } else {
            var initializer = map["key#" + name];
            if (initializer) {
                initializer.handler.call(initializer.handler, $scope);
                return true;
            } else {
                console.error("Unknown initializer: `" + name + "`");
                return false;
            }
        }
    }
    AGN.Lib.CoreInitializer = {
        autorun: autorun,
        run: run,
        new: register
    };
})();

(() => {
    class CSRF {
        static HEADER_NAME="";
        static COOKIE_NAME="";
        static PARAM_NAME="";
        static getParameterName() {
            return this.PARAM_NAME;
        }
        static getCookieName() {
            return this.COOKIE_NAME;
        }
        static getHeaderName() {
            return this.HEADER_NAME;
        }
        static setHeaderName(headerName) {
            this.HEADER_NAME = headerName;
        }
        static setParamName(paramName) {
            this.PARAM_NAME = paramName;
        }
        static setCookieName(cookieName) {
            this.COOKIE_NAME = cookieName;
        }
        static isProtectionEnabled() {
            return this.getHeaderName() && this.getParameterName() && this.getCookieName();
        }
        static readActualToken() {
            if (CSRF.isProtectionEnabled()) {
                return AGN.Lib.Storage.readCookie(this.getCookieName());
            }
            return "";
        }
        static setTokenToReqHeader(jqxhr, reqType) {
            if (reqType !== "GET") {
                jqxhr.setRequestHeader(this.getHeaderName(), this.readActualToken());
            }
        }
        static updateTokenInDOM($scope = $(document)) {
            if (!this.isProtectionEnabled()) {
                return $scope;
            }
            const isPlainText = !($scope instanceof $);
            if (isPlainText) {
                $scope = $("<div>").append($scope);
            }
            const csrfToken = this.readActualToken();
            const $tokenInputs = $scope.find(`input[name="${this.getParameterName()}"]`);
            _.each($tokenInputs, input => {
                if (isPlainText) {
                    $(input).attr("value", csrfToken);
                } else {
                    $(input).val(csrfToken);
                }
            });
            if (isPlainText) {
                return $scope.html();
            }
        }
    }
    AGN.Lib.CSRF = CSRF;
})();

(function() {
    var DataProvider = {};
    DataProvider.get = function($element) {
        var type = $element.data("provider"), src = $element.data("provider-src"), provider;
        switch (type) {
          case "opt":
            provider = DataProvider.opt(src);
            break;

          case "remote":
            provider = DataProvider.remote(src);
            break;

          default:
            break;
        }
        return provider;
    };
    DataProvider.opt = function(src) {
        var deferred = $.Deferred();
        if (AGN.Opt[src]) {
            setTimeout(function() {
                deferred.resolve(AGN.Opt[src]);
            }, 100);
        } else {
            setTimeout(function() {
                deferred.reject();
            }, 100);
        }
        return deferred;
    };
    DataProvider.remote = function(src) {
        return $.get(src);
    };
    AGN.Lib.DataProvider = DataProvider;
})();

