(() => {
    function PromiseProgressWatcher() {
        this.deferred = $.Deferred();
        this.callback = null;
    }
    PromiseProgressWatcher.prototype.promise = function() {
        return this.deferred.promise();
    };
    PromiseProgressWatcher.prototype.bind = function(src) {
        var self = this;
        if (src === false) {
            self.callback = null;
        } else {
            var callback = self.callback = function() {
                if (self.callback === callback) {
                    self.deferred.notifyWith(this, arguments);
                }
            };
            if ($.isArray(src)) {
                src.forEach(function(promise) {
                    promise.progress(callback);
                });
            } else {
                src.progress(callback);
            }
        }
    };
    AGN.Lib.LB.PromiseProgressWatcher = PromiseProgressWatcher;
})();

