            revert: "invalid",
            distance: 20,
            helper: "clone",
            appendTo: "body",
            containment: "window",
            zIndex: Def.TOP_Z,
            refreshPositions: true,
            start: function(event, ui) {
                ui.helper.width($(this).width());
                Messaging.send(Def.TOPICS.DRAG_STARTED);
            },
