(() => {
    AGN.Lib.Template.register("schedule-time-item-add-btn", `\n    <a href="#" class="btn btn-icon btn-primary" data-schedule-add-time-item data-tooltip="{{- t('defaults.add') }}">\n      <i class="icon icon-plus"></i>\n    </a>\n  `);
    AGN.Lib.Template.register("schedule-time-item-remove-btn", `\n    <a href="#" class="btn btn-icon btn-danger" data-schedule-remove-time-item data-tooltip="{{- t('defaults.clear') }}">\n      <i class="icon icon-trash-alt"></i>\n    </a>\n  `);
    AGN.Lib.Template.register("schedule-time-item", `\n    <div class="input-group" data-schedule-time-item>\n        {{ const isExplicitTimeSelected = time.type === 'EXPLICIT'; }}\n        <select class="form-control" data-schedule-time-interval>\n            <option value="" {{ isExplicitTimeSelected ? print('selected') : print('') }}>\n              {{- t('schedule.defineTime') }}\n            </option>\n            \n            {{ intervals.forEach(interval => { }}\n               <option value="{{- interval }}" {{ !isExplicitTimeSelected && time.value == interval ? print('selected') : print('') }}>\n                {{- t('schedule.intervals.' + interval) }}\n               </option> \n            {{ }); }}\n        </select>\n\n        <div class="input-icon-container flex-grow-1 {{ isExplicitTimeSelected ? print('') : print('hidden') }}">\n          <input class="form-control js-timepicker" type="text" value="{{- isExplicitTimeSelected ? time.value : '' }}"\n                 data-schedule-time data-timepicker-options="mask: 'h:s'"\n                 placeholder="_" {{ isExplicitTimeSelected ? print('') : print('disabled') }}/>\n\n          <i class="icon icon-clock" data-tooltip="{{- window.agnTimeZoneId }}"></i>\n        </div>\n    </div>\n  `);
    AGN.Lib.Template.register("schedule-day-item", `\n    <div class="row g-1 mb-1" data-schedule-day-item>\n        <div class="col d-flex flex-column gap-1">\n            <select class="form-control" size="1" data-schedule-day-of-week>\n              {{ weekDays.forEach(weekDay => { }}\n                  <option value="{{- weekDay }}" {{ weekDay == entry.weekDay ? print('selected') : print('') }}>\n                    {{- t('schedule.weekdays.' + weekDay) }}\n                  </option>\n              {{ }); }}\n            </select>\n\n            <div class="d-flex flex-column gap-inherit" data-schedule-time-items>\n              {{ _.each(entry.times, time => { }}\n                  {{= AGN.Lib.Template.text('schedule-time-item', { time, intervals }) }}\n              {{ }); }}\n            </div>\n        </div>\n        <div class="col-auto">\n          <a href="#" class="btn btn-icon btn-primary" data-add-day data-tooltip="{{- t('defaults.add') }}">\n              <i class="icon icon-plus"></i>\n          </a>\n          <a href="#" class="btn btn-icon btn-danger hidden" data-remove-day data-tooltip="{{- t('defaults.clear') }}">\n              <i class="icon icon-trash-alt"></i>\n          </a>\n        </div>\n    </div>\n  `);
    class DayItem {
        static DATA_ATTR_NAME="agn:scheduleBuilder:weeklyDayItem";
        static ALLOWED_INTERVALS=[ 1, 2, 3, 4, 6, 12 ];
        static defaults() {
            return {
                weekDay: "0",
                times: [ {
                    type: "EXPLICIT",
                    value: ""
                } ]
            };
        }
        static get($needle) {
            let $item;
            if ($needle.is("[data-schedule-day-item]")) {
                $item = $needle;
            } else {
                $item = $needle.closest("[data-schedule-day-item]");
            }
            return $item.data(DayItem.DATA_ATTR_NAME);
        }
        static create(settings, options = {}) {
            const $item = AGN.Lib.Template.dom("schedule-day-item", {
                entry: $.extend(DayItem.defaults(), options),
                intervals: DayItem.ALLOWED_INTERVALS,
                ...settings
            });
            new DayItem($item);
            return $item;
        }
        constructor($item, weekDays) {
            if (!$item.exists()) {
                $item = DayItem.create({
                    weekDays: weekDays
                });
            }
            this.$el = $item;
            this.$el.data(DayItem.DATA_ATTR_NAME, this);
        }
        getSettings() {
            const weekDay = this.$el.find("[data-schedule-day-of-week]").val();
            const times = this.#getTimeItems$().map((i, item) => {
                const $item = $(item);
                const isIntervalSelection = this.#isTimeIntervalSelected($item);
                return {
                    type: isIntervalSelection ? "INTERVAL" : "EXPLICIT",
                    value: isIntervalSelection ? this.#getTimeInterval($item) : this.#getExplicitTime($item)
                };
            }).get();
            return {
                weekDay: weekDay,
                times: times
            };
        }
        toggleTimePickerVisibility($needle) {
            const $timeItem = this.#getTimeItem$($needle);
            const isIntervalSelected = this.#isTimeIntervalSelected($timeItem);
            this.#getExplicitTime$($timeItem).prop("disabled", isIntervalSelected).parent().toggleClass("hidden", isIntervalSelected);
        }
        toggleTimeItemsButtonsVisibility() {
            const $timeItems = this.#getTimeItems$();
            $timeItems.each((i, item) => {
                const $item = $(item);
                const $btnIcon = $item.find(".btn-icon");
                const $newBtn = AGN.Lib.Template.dom($item.is(":last-child") ? "schedule-time-item-add-btn" : "schedule-time-item-remove-btn");
                if ($btnIcon.exists()) {
                    $btnIcon.replaceWith($newBtn);
                } else {
                    $item.append($newBtn);
                }
                AGN.Lib.CoreInitializer.run("tooltip", $newBtn);
            });
        }
        addTimeItem(options = {}) {
            const $timeWrapper = AGN.Lib.Template.dom("schedule-time-item", {
                time: $.extend(DayItem.defaults().times[0], options),
                intervals: DayItem.ALLOWED_INTERVALS
            });
            this.$el.find("[data-schedule-time-items]").append($timeWrapper);
            AGN.runAll($timeWrapper);
            this.toggleTimeItemsButtonsVisibility();
        }
        removeTimeItem($needle) {
            this.#getTimeItem$($needle).remove();
            this.toggleTimeItemsButtonsVisibility();
        }
        getDayOfWeek() {
            return parseInt(this.$el.find("[data-schedule-day-of-week]").val());
        }
        disableDayOptions(values) {
            const $daySelect = this.$el.find("[data-schedule-day-of-week]");
            $daySelect.find("option").prop("disabled", false);
            AGN.Lib.Select.get($daySelect).disableOptions(values);
        }
        disableSelectedIntervalOptions() {
            const $timeItems = this.#getTimeItems$();
            const usedIntervals = $timeItems.filter((i, item) => this.#isTimeIntervalSelected($(item))).map((i, item) => this.#getTimeInterval($(item))).get();
            $timeItems.find("[data-schedule-time-interval]").each((i, select) => {
                const $select = $(select);
                $select.find("option").prop("disabled", false);
                const intervalsToDisable = usedIntervals.filter(interval => interval !== $select.val());
                AGN.Lib.Select.get($select).disableOptions(intervalsToDisable);
            });
        }
        #isTimeIntervalSelected($timeItem) {
            return !!this.#getTimeInterval($timeItem);
        }
        #getTimeInterval($timeItem) {
            return $timeItem.find("[data-schedule-time-interval]").val();
        }
        #getExplicitTime($timeItem) {
            return this.#getExplicitTime$($timeItem).val();
        }
        #getExplicitTime$($timeItem) {
            return $timeItem.find("[data-schedule-time]");
        }
        #getTimeItems$() {
            return this.$el.find("[data-schedule-time-item]");
        }
        #getTimeItem$($needle) {
            return $needle.closest("[data-schedule-time-item]");
        }
    }
    class WeeklyInterval extends AGN.Lib.Schedule.ScheduleInterval {
        getSettings() {
            const days = this.#hasDefaultSettings() ? [] : this.#getAllDayItems().map(item => item.getSettings());
            return {
                days: days
            };
        }
        validate() {
            return this.#hasDefaultSettings() || super.validate();
        }
        drawSettings() {
            super.drawSettings();
            if (this.settings?.days?.length) {
                this.settings.days.map(options => DayItem.create({
                    weekDays: this.getPossibleWeekDays()
                }, options)).forEach($dayItem => this.#addDayItem($dayItem));
            } else {
                this.#addEmptyDayItem();
            }
            this.#addActions();
        }
        getPossibleWeekDays() {
            return [ 0, ...super.getPossibleWeekDays() ];
        }
        getSettingsHtml() {
            return `<label class="form-label">${t("schedule.daysAndTime")}</label>`;
        }
        #addActions() {
            AGN.Lib.Action.new({
                click: "[data-add-day]"
            }, () => {
                const dayItems = this.#getAllDayItems();
                const usedDays = dayItems.map(item => item.getDayOfWeek());
                const nextFreeDay = this.getPossibleWeekDays().find(day => !usedDays.includes(day));
                this.#addDayItem(DayItem.create({
                    weekDays: this.getPossibleWeekDays()
                }, {
                    weekDay: nextFreeDay
                }));
            }, this.$container);
            AGN.Lib.Action.new({
                click: "[data-remove-day]"
            }, $el => {
                this.#deleteDayItem(DayItem.get($el));
            }, this.$container);
            AGN.Lib.Action.new({
                click: "[data-schedule-add-time-item]"
            }, $el => {
                const dayItem = DayItem.get($el);
                dayItem.addTimeItem();
                dayItem.disableSelectedIntervalOptions();
            }, this.$container);
            AGN.Lib.Action.new({
                click: "[data-schedule-remove-time-item]"
            }, $el => {
                const dayItem = DayItem.get($el);
                dayItem.removeTimeItem($el);
                dayItem.disableSelectedIntervalOptions();
            }, this.$container);
            AGN.Lib.Action.new({
                change: "[data-schedule-time-interval]"
            }, $el => {
                const dayItem = DayItem.get($el);
                dayItem.toggleTimePickerVisibility($el);
                dayItem.disableSelectedIntervalOptions();
            }, this.$container);
            AGN.Lib.Action.new({
                change: "[data-schedule-day-of-week]"
            }, () => {
                this.#updateDaysOptions();
            }, this.$container);
            AGN.Lib.Action.new({
                change: "[data-schedule-time-items]"
            }, () => this.validate(), this.$container);
        }
        #getAllDayItems() {
            return this.$container.find("[data-schedule-day-item]").map((i, item) => DayItem.get($(item))).get();
        }
        #deleteDayItem(dayItem) {
            this.$container.find(dayItem.$el).remove();
            this.#toggleDayButtonsVisibility();
            this.#updateDaysOptions();
        }
        #addEmptyDayItem() {
            this.#addDayItem(DayItem.create({
                weekDays: this.getPossibleWeekDays()
            }));
        }
        #addDayItem($dayItem) {
            this.$container.append($dayItem);
            AGN.runAll($dayItem);
            this.#toggleDayButtonsVisibility();
            const dayItem = DayItem.get($dayItem);
            dayItem.toggleTimeItemsButtonsVisibility();
            dayItem.disableSelectedIntervalOptions();
            this.#updateDaysOptions();
        }
        #updateDaysOptions() {
            const dayItems = this.#getAllDayItems();
            dayItems.forEach(item => {
                const optionsToDisable = dayItems.filter(dayItem => item !== dayItem).map(dayItem => String(dayItem.getDayOfWeek()));
                item.disableDayOptions(optionsToDisable);
            });
        }
        #toggleDayButtonsVisibility() {
            const dayItems = this.#getAllDayItems();
            const dayItemsCount = dayItems.length;
            const $removeDayBtns = this.$container.find("[data-remove-day]").addClass("hidden");
            const $addDayBtns = this.$container.find("[data-add-day]").addClass("hidden");
            if (dayItemsCount > 1) {
                $removeDayBtns.slice(0, -1).removeClass("hidden");
            }
            if (dayItemsCount < this.getPossibleWeekDays().length) {
                $addDayBtns.last().removeClass("hidden");
            } else {
                $removeDayBtns.last().removeClass("hidden");
            }
        }
        #hasDefaultSettings() {
            const dayItems = this.#getAllDayItems();
            return dayItems.length === 1 && _.isEqual(dayItems[0].getSettings(), DayItem.defaults());
        }
    }
    AGN.Lib.Schedule.ScheduleWeeklyInterval = WeeklyInterval;
})();

(() => {
    AGN.Lib.Template.register("schedule-interval-type", `\n   <div>\n      <label for="interval-type" class="form-label">\n        {{- t('schedule.interval') }}\n      </label>\n      <select id="interval-type" class="form-control" data-change-interval-type>\n          {{ Object.keys(intervals).forEach(intervalType => { }}\n            <option value="{{- intervalType }}" {{ intervalType === type ? print('selected') : print() }}>\n              {{= intervals[intervalType].label }}\n            </option>\n          {{ }) }}\n      </select>\n    </div>\n  `);
    const INTERVALS = {
        WEEKLY: {
            label: t("schedule.interval_type.weekly"),
            class: AGN.Lib.Schedule.ScheduleWeeklyInterval
        },
        BI_WEEKLY: {
            label: t("schedule.interval_type.bi_weekly"),
            class: AGN.Lib.Schedule.ScheduleBiWeeklyInterval
        },
        MONTHLY: {
            label: t("schedule.interval_type.monthly"),
            class: AGN.Lib.Schedule.ScheduleMontlyInterval
        },
        WEEKDAYS: {
            label: t("schedule.interval_type.weekdays"),
            class: AGN.Lib.Schedule.ScheduleWeekdaysInterval
        }
    };
    class ScheduleBuilder {
        static DATA_ATTR_NAME="agn:scheduleBuilder";
        constructor($container) {
            this.config = $container.find("script[data-config]").json();
            this.settings = JSON.parse(this.config.settings);
            this.settingsCache = new Map;
            this.#renderControls($container);
            $container.data(ScheduleBuilder.DATA_ATTR_NAME, this);
        }
        static get($needle) {
            return $needle.data(ScheduleBuilder.DATA_ATTR_NAME);
        }
        validate() {
            return this.interval.validate();
        }
        toJson() {
            return JSON.stringify({
                type: this.getCurrentIntervalType(),
                ...this.interval.getSettings()
            });
        }
        addAction(events, handler) {
            AGN.Lib.Action.new(events, handler, this.$container);
        }
        #renderControls($container) {
            this.$container = $('<div class="vstack gap-3">');
            this.#renderIntervalTypeControl();
            this.$dynamicContainer = $("<div>");
            $container.append(this.$container.append(this.$dynamicContainer));
            AGN.Lib.CoreInitializer.run("select", this.$container);
            this.changeIntervalType(INTERVALS[this.settings?.type]?.class ?? INTERVALS.WEEKLY.class, _.omit(this.settings, [ "type" ]));
            this.addAction({
                change: "[data-change-interval-type]"
            }, this.#handleChangedInterval.bind(this));
        }
        #renderIntervalTypeControl() {
            this.$container.append(AGN.Lib.Template.text("schedule-interval-type", {
                intervals: INTERVALS,
                type: this.settings?.type
            }));
        }
        #handleChangedInterval($el) {
            this.settingsCache.set(this.interval.constructor.name, this.interval.getSettings());
            const SettingsClass = INTERVALS[$el.val()].class;
            this.changeIntervalType(SettingsClass, this.settingsCache.get(SettingsClass.name) ?? {});
        }
        changeIntervalType(SettingsClass, settings) {
            this.interval = new SettingsClass(this.$dynamicContainer, settings);
            this.interval.drawSettings();
        }
        getCurrentIntervalType() {
            return this.$container.find("[data-change-interval-type]").val();
        }
    }
    AGN.Lib.Schedule.Builder = ScheduleBuilder;
})();

