(() => {
    const Def = AGN.Lib.WM.Definitions;
    const Helpers = AGN.Lib.Helpers;
    const DateFormat = AGN.Lib.DateFormat;
    AGN.Lib.WM.Utils = {
        checkActivation: function(withWarn) {
            const currentWorkflowStatus = $("#workflow-status").val();
            if (Def.constants.initialWorkflowStatus === Def.constants.statusActive && (currentWorkflowStatus === Def.constants.statusActive || currentWorkflowStatus === Def.constants.statusTesting)) {
                if (withWarn) {
                    AGN.Lib.Messages.warn("error.workflow.saveActivatedWorkflow");
                }
                return true;
            }
            return false;
        },
        isPausedWorkflow: function() {
            return $("#workflow-status").val() === Def.constants.statusPaused;
        },
        getConfigData: function($e) {
            return Helpers.objFromString($e.data("config"));
        },
        mapAsOptionsHtml: function(options) {
            var html = "";
            Object.keys(options).forEach(function(key) {
                var attributes = 'value="' + key + '"';
                html += "<option " + attributes + ">" + options[key] + "</option>";
            });
            return html;
        },
        arrayAsOptionsHtml: function(options) {
            var html = "";
            options.forEach(function(option) {
                var attributes = 'value="' + option.id + '"';
                var extras = option.data;
                if (extras) {
                    Object.keys(extras).forEach(function(k) {
                        attributes += " data-" + k + '="' + extras[k].replace('"', "&quot;") + '"';
                    });
                }
                var text = option.text.replace("<", "&lt;").replace(">", "&gt;");
                html += "<option " + attributes + ">" + text + "</option>";
            });
            return html;
        }
    };
    AGN.Lib.WM.DateTimeUtils = {
        toDateTime: function(date, hour, minute) {
            var value = null;
            if (!!date && date.getMonth) {
                value = new Date(date);
                if (!!hour && hour !== 0) {
                    value.setHours(hour);
                }
                if (!!minute && minute !== 0) {
                    value.setMinutes(minute);
                }
            }
            return value;
        },
        getDateTimeValue: function(date, hour, minute) {
            var value = this.toDateTime(date, hour, minute);
            return value != null ? value.getTime() : null;
        },
        getDateTimeStr: function(date, hour, minute, datePattern) {
            if (!date || !date.getMonth) {
                return "";
            }
            hour = hour || date.getHours();
            minute = minute || date.getMinutes();
            var dateTime = this.toDateTime(date, hour, minute);
            if (!!dateTime) {
                return DateFormat.format(dateTime, datePattern);
            } else {
                return "";
            }
        },
        getDateStr: function(date, datePattern) {
            return this.getDateTimeStr(date, null, null, datePattern);
        },
        getCurrentAdminTime() {
            return $.ajax({
                url: AGN.url("/workflow/getCurrentAdminTime.action"),
                async: false
            }).responseJSON;
        }
    };
})();

(function() {
    function Constraints(rules) {
        this.rules = rules;
    }
    Constraints.prototype.isConstraint = function(value) {
        return _.isBoolean(value) || _.isFunction(value);
    };
    Constraints.prototype.evaluate = function(constraint, source, target) {
        if (constraint === true || constraint === false) {
            return constraint;
        }
        if (_.isFunction(constraint)) {
            return constraint(source, target);
        }
        return undefined;
    };
    Constraints.prototype.getRulesToCheck = function(source, target) {
        return [ {
            from: source.type,
            to: [ target.type, "*" ]
        }, {
            from: "*",
            to: [ target.type, "*" ]
        } ];
    };
    Constraints.prototype.getRelevantConstraints = function(source, target) {
        var isConstraint = this.isConstraint;
        var rulesToCheck = this.getRulesToCheck(source, target);
        var rules = this.rules;
        var constraints = [];
        rulesToCheck.forEach(function(rule) {
            var isRuleMissing = true;
            if (_.has(rules, rule.from)) {
                var value = rules[rule.from];
                if (isConstraint(value)) {
                    constraints.push(value);
                    isRuleMissing = false;
                } else {
                    rule.to.forEach(function(to) {
                        if (_.has(rules[rule.from], to)) {
                            value = rules[rule.from][to];
                            if (isConstraint(value)) {
                                constraints.push(value);
                                isRuleMissing = false;
                            }
                        }
                    });
                }
            }
            if (isRuleMissing && rule.from != "*") {
                constraints.push(false);
            }
        });
        return constraints;
    };
    Constraints.prototype.check = function(source, target) {
        var constraints = this.getRelevantConstraints(source, target);
        var result = false;
        for (var i = 0; i < constraints.length; i++) {
            if (this.evaluate(constraints[i], source, target)) {
                result = true;
            } else {
                return false;
            }
        }
        return result;
    };
    AGN.Lib.WM.ConnectionConstraints = Constraints;
})();

(function() {
    const Popover = AGN.Lib.Popover;
    class NodePopover {
        constructor(node) {
            this.node = node;
            this.getMailingThumbnailWithCache = _.memoize(this.getMailingThumbnail.bind(this));
            this.#initPopover();
        }
        #initPopover() {
            this.getPopoverContent().then(content => this.createPopover(content));
            this.setEnabled(true);
        }
        createPopover(content) {
            if (!content) {
                return;
            }
            this.popover = Popover.getOrCreate(this.node.get$(), {
                trigger: "hover",
                html: true,
                content: content
            });
        }
        remove() {
            if (this.popover) {
                this.popover.hide();
            }
            Popover.remove(this.node.get$());
            this.popover = null;
        }
        update() {
            this.remove();
            this.#initPopover();
        }
        async getPopoverContent() {
            const thumbnailEl = await this.getThumbnail();
            const comment = this.node.getComment();
            if (!thumbnailEl && !comment?.trim()) {
                return null;
            }
            return $("<div>").addClass("d-flex flex-column align-items-center").append(thumbnailEl).append($("<div>").text(comment));
        }
        async getThumbnail() {
            const mailingId = this.node.getData().mailingId;
            if (!this.node.isMailingNode() || !mailingId) {
                return "";
            }
            return this.getMailingThumbnailWithCache(mailingId);
        }
        async getMailingThumbnail(mailingId) {
            const thumbnailSrc = await this.getMailingThumbnailSrc(mailingId);
            if (!thumbnailSrc) {
                return "";
            }
            const img = new Image;
            img.src = thumbnailSrc;
            img.className = "popover__thumbnail";
            return img;
        }
        async getMailingThumbnailSrc(mailingId) {
            const componentId = await $.get(AGN.url(`/workflow/mailing/${mailingId}/thumbnail.action`));
            return componentId > 0 ? AGN.url("/sc?compID=" + componentId) : "";
        }
        setEnabled(isEnabled) {
            this.isEnabled = isEnabled;
            if (!this.popover) {
                return;
            }
            if (isEnabled) {
                this.popover.enable();
            } else {
                this.popover.disable();
            }
        }
    }
    AGN.Lib.WM.NodePopover = NodePopover;
})();

(() => {
    const DateTimeUtils = AGN.Lib.WM.DateTimeUtils;
    const Template = AGN.Lib.Template;
    const Def = AGN.Lib.WM.Definitions;
    const NodePopover = AGN.Lib.WM.NodePopover;
    class Node {
        constructor(type, data) {
            this.id = null;
            this.x = 0;
            this.y = 0;
            this.type = type;
            this.title = "";
            this.overlayTitle = "";
            this.filled = false;
            this.editable = true;
            this.expandable = false;
            this.dependent = false;
            this.inRecipientsChain = false;
            this.anchors = Def.ICONS_CONFIG[type].anchors;
            this.data = data;
            this.$element = Node.create$(type);
            this.$element.data("agn:node", this);
            this.$connectionButton = this.$element.find(".node-connect-button");
            this.$titleDiv = Node.createTitleDiv$();
            this.$titleSpan = this.$titleDiv.find(".icon-title-span");
            this.$overlayTitle = this.$element.find(".icon-overlay-title");
            this.nodePopover = new NodePopover(this);
            this.lastTitleAnchor = Def.BOTTOM;
        }
        static restore(node) {
            var agnData = node.get$().data("agn:node");
            if (!agnData) {
                node.get$().data("agn:node", node);
            }
            return node;
        }
        static get(el) {
            if (el instanceof Node) {
                return el;
            }
            if (el instanceof HTMLElement) {
                el = $(el);
            }
            if (!el.is(".node")) {
                el = el.closest(".node");
            }
            return el.data("agn:node");
        }
        static isDecisionNode(node) {
            return node.getType() === Def.NODE_TYPE_DECISION;
        }
        isMailingNode() {
            return Def.NODE_TYPES_MAILING.includes(this.getType());
        }
        get isSplitNode() {
            return this.getType() === Def.NODE_TYPE_SPLIT;
        }
        get isParameterNode() {
            return this.getType() === Def.NODE_TYPE_PARAMETER;
        }
        static isMailingNode(node) {
            if (!node) {
                return false;
            }
            return Def.NODE_TYPES_MAILING.includes(node.getType());
        }
        static isBranchingDecisionNode(node) {
            if (Node.isDecisionNode(node)) {
                var data = node.getData();
                if (data.decisionType === Def.constants.decisionTypeDecision) {
                    return true;
                }
            }
            return false;
        }
        static isDecisionBranchesOrderFromPositiveToNegative(source, target1, target2) {
            if (target1.y <= source.y && target2.y <= source.y) {
                if (target1.y < target2.y) {
                    return true;
                } else if (target2.y < target1.y) {
                    return false;
                } else {
                    return target1.x < target2.x;
                }
            } else if (target1.y > source.y && target2.y > source.y) {
                return target1.x > target2.x;
            } else {
                return target1.y < target2.y;
            }
        }
        static getDecisionBranches(connections) {
            if (connections.length === 2) {
                var source = Node.getPosition(connections[0].source.get$());
                var target1 = Node.getPosition(connections[0].target.get$());
                var target2 = Node.getPosition(connections[1].target.get$());
                if (this.isDecisionBranchesOrderFromPositiveToNegative(source, target1, target2)) {
                    return {
                        positive: connections[0],
                        negative: connections[1]
                    };
                } else {
                    return {
                        positive: connections[1],
                        negative: connections[0]
                    };
                }
            }
            return null;
        }
        static isCommented(node) {
            return !!_.trim(node.getComment());
        }
        static isSelected($element) {
            return $element.hasClass("ui-selected");
        }
        static setSelected($element, isSelected) {
            return $element.toggleClass("ui-selected", !!isSelected);
        }
        static isChainSource($element) {
            return $element.hasClass("chain-mode-source");
        }
        static setChainSource($element, isSource) {
            $element.toggleClass("chain-mode-source", !!isSource);
        }
        static getAnchors($node) {
            var node = Node.get($node);
            if (node) {
                return node.getAnchors();
            }
            return Def.ICONS_CONFIG[$node.data("type")].anchors;
        }
        static getAnchorsInUse(endpoints) {
            var anchorsInUse = {};
            endpoints.forEach(function(endpoint) {
                var orientation = endpoint.anchor.getOrientation();
                if (orientation[0] > 0) {
                    anchorsInUse[Def.RIGHT] = true;
                } else if (orientation[0] < 0) {
                    anchorsInUse[Def.LEFT] = true;
                } else if (orientation[1] > 0) {
                    anchorsInUse[Def.BOTTOM] = true;
                } else if (orientation[1] < 0) {
                    anchorsInUse[Def.TOP] = true;
                }
            });
            return anchorsInUse;
        }
        static getPosition($node) {
            var position = $node.position();
            return {
                x: position.left,
                y: position.top
            };
        }
        static getBox($node) {
            var position = $node.position();
            var rect = $node[0].getBoundingClientRect();
            return {
                minX: position.left,
                minY: position.top,
                maxX: position.left + rect.width,
                maxY: position.top + rect.height
            };
        }
        static isInRegion($node, regionBox) {
            var nodeBox = Node.getBox($node);
            return (nodeBox.minX >= regionBox.minX && nodeBox.minX <= regionBox.maxX || nodeBox.maxX >= regionBox.minX && nodeBox.maxX <= regionBox.maxX) && (nodeBox.minY >= regionBox.minY && nodeBox.minY <= regionBox.maxY || nodeBox.maxY >= regionBox.minY && nodeBox.maxY <= regionBox.maxY);
        }
        static getCollisionBox($node) {
            var anchors = Node.getAnchors($node);
            var position = $node.position();
            var rect = $node[0].getBoundingClientRect();
            var paddingLeft = (anchors[0][0] - Def.NODE_MIN_MARGIN) * rect.width;
            var paddingTop = (anchors[1][1] - Def.NODE_MIN_MARGIN) * rect.height;
            var paddingRight = (1 - anchors[2][0] - Def.NODE_MIN_MARGIN) * rect.width;
            var paddingBottom = (1 - anchors[3][1] - Def.NODE_MIN_MARGIN) * rect.height;
            return {
                minX: position.left + paddingLeft,
                minY: position.top + paddingTop,
                maxX: position.left + rect.width - paddingRight,
                maxY: position.top + rect.height - paddingBottom
            };
        }
        static detectBoxCollision=function(box1, box2) {
            return !(box1.minX > box2.maxX || box1.maxX < box2.minX || box1.minY > box2.maxY || box1.maxY < box2.minY);
        };
        static create$(type) {
            if ([ "datebased_mailing", "actionbased_mailing" ].includes(type)) {
                type = "mailing";
            }
            return Template.dom("workflow-node", {
                type: type
            });
        }
        static createDraggable$(type) {
            return Template.dom("workflow-draggable-node", {
                type: type
            });
        }
        static createTitleDiv$() {
            return Template.dom("workflow-icon-title");
        }
        static create(type) {
            var data = {
                iconComment: ""
            };
            var node = new Node(type, data);
            switch (type) {
              case Def.NODE_TYPE_SC_ABTEST:
              case Def.NODE_TYPE_SC_BIRTHDAY:
              case Def.NODE_TYPE_SC_DOI:
              case Def.NODE_TYPE_BIRTHDAY_WITH_COUPON:
              case Def.NODE_TYPE_WELCOME_TRACK:
              case Def.NODE_TYPE_WELCOME_TRACK_WITH_INCENTIVE:
              case Def.NODE_TYPE_SHOPPING_CART_ABANDONERS_SMALL:
              case Def.NODE_TYPE_SHOPPING_CART_ABANDONERS_LARGE:
              case Def.NODE_TYPE_ANNIVERSARY_MAIL:
                node.setFilled(true);
                node.setExpandable(true);
                data.copyContent = true;
                data.created = false;
                break;

              case "ownWorkflow":
                node.setExpandable(true);
                data.ownWorkflowId = 0;
                data.copyContent = true;
                data.created = false;
                break;

              case "start":
                data.startType = null;
                data.date = null;
                data.hour = 0;
                data.minute = 0;
                data.sendReminder = false;
                data.remindAdminId = 0;
                data.remindAtOnce = false;
                data.scheduleReminder = false;
                data.remindSpecificDate = false;
                data.remindDate = new Date;
                data.remindHour = 0;
                data.remindMinute = 0;
                data.event = null;
                data.reaction = null;
                data.mailingId = 0;
                data.profileField = "";
                data.dateProfileField = "";
                data.dateFieldOperator = 1;
                data.dateFieldValue = "";
                data.useRules = false;
                data.rules = [];
                data.executeOnce = true;
                data.comment = "";
                data.recipients = "";
                data.adminTimezone = "";
                break;

              case "stop":
                data.endType = null;
                data.date = null;
                data.hour = 0;
                data.minute = 0;
                data.sendReminder = false;
                data.remindAdminId = 0;
                data.remindAtOnce = false;
                data.scheduleReminder = false;
                data.remindSpecificDate = false;
                data.remindDate = new Date;
                data.remindHour = 0;
                data.remindMinute = 0;
                data.event = null;
                data.reaction = null;
                data.mailingId = 0;
                data.profileField = "";
                data.useRules = false;
                data.rules = [];
                data.executeOnce = true;
                data.comment = "";
                data.recipients = "";
                data.adminTimezone = "";
                break;

              case "decision":
                data.decisionType = null;
                data.decisionCriteria = null;
                data.reaction = null;
                data.mailingId = 0;
                data.linkId = 0;
                data.profileField = "";
                data.aoDecisionCriteria = null;
                data.threshold = "";
                data.decisionDate = new Date;
                data.rules = [];
                data.includeVetoed = true;
                break;

              case "deadline":
                data.deadlineType = null;
                data.date = new Date;
                data.timeUnit = null;
                data.delayValue = 0;
                data.hour = 0;
                data.minute = 0;
                data.useTime = false;
                break;

              case "parameter":
                data.value = 0;
                break;

              case "recipient":
                node.setDependent(false);
                data.mailinglistId = 0;
                data.targets = [];
                data.altgs = [];
                data.targetsOption = null;
                break;

              case "archive":
                data.campaignId = 0;
                data.archived = false;
                break;

              case "form":
                data.userFormId = 0;
                data.formType = "form";
                break;

              case "mailing":
                data.mailingId = 0;
                data.skipEmptyBlocks = true;
                data.doubleCheck = true;
                break;

              case "actionbased_mailing":
              case "datebased_mailing":
              case "mailing_mediatype_sms":
              case "mailing_mediatype_post":
                data.mailingId = 0;
                break;

              case "followup_mailing":
                data.baseMailingId = 0;
                data.mailingId = 0;
                data.decisionCriterion = "OPENED";
                break;

              case "import":
              case "export":
                data.importexportId = 0;
                data.errorTolerant = false;
                break;
            }
            return node;
        }
        static isExpandableType(type) {
            switch (type) {
              case Def.NODE_TYPE_SC_ABTEST:
              case Def.NODE_TYPE_SC_BIRTHDAY:
              case Def.NODE_TYPE_SC_DOI:
              case Def.NODE_TYPE_BIRTHDAY_WITH_COUPON:
              case Def.NODE_TYPE_WELCOME_TRACK:
              case Def.NODE_TYPE_WELCOME_TRACK_WITH_INCENTIVE:
              case Def.NODE_TYPE_SHOPPING_CART_ABANDONERS_SMALL:
              case Def.NODE_TYPE_SHOPPING_CART_ABANDONERS_LARGE:
              case Def.NODE_TYPE_ANNIVERSARY_MAIL:
              case Def.NODE_TYPE_OWN_WORKFLOW:
              case Def.NODE_TYPE_SPLIT:
                return true;

              default:
                return false;
            }
        }
        static deserialize(object) {
            var data = $.extend({}, object);
            var node = new Node(object.type, data);
            node.setId(object.id);
            node.setCoordinates(object.x, object.y);
            node.setComment(object.iconComment);
            node.setFilled(object.filled);
            node.setEditable(object.editable);
            if ([ Def.NODE_TYPE_OWN_WORKFLOW, Def.NODE_TYPE_SC_BIRTHDAY, Def.NODE_TYPE_SC_DOI, Def.NODE_TYPE_SC_ABTEST, Def.NODE_TYPE_BIRTHDAY_WITH_COUPON, Def.NODE_TYPE_WELCOME_TRACK, Def.NODE_TYPE_WELCOME_TRACK_WITH_INCENTIVE, Def.NODE_TYPE_SHOPPING_CART_ABANDONERS_SMALL, Def.NODE_TYPE_SHOPPING_CART_ABANDONERS_LARGE, Def.NODE_TYPE_ANNIVERSARY_MAIL ].includes(object.type)) {
                node.setExpandable(true);
            }
            if (node.isMailingNode() && data.mailingId) {
                $.get(AGN.url(`/mailing/${data.mailingId}/name.action`)).done(name => node.setTitle(name ? name : object.iconTitle));
            } else {
                node.setTitle(object.iconTitle);
            }
            delete data["id"];
            delete data["x"];
            delete data["y"];
            delete data["type"];
            delete data["iconTitle"];
            delete data["filled"];
            delete data["editable"];
            [ "date", "remindDate", "decisionDate" ].forEach(function(k) {
                if (data[k]) {
                    var string = data[k].toString();
                    if (string.includes("-")) {
                        var parts = string.split("-");
                        data[k] = new Date(parts[0], parts[1] - 1, parts[2]);
                    } else {
                        data[k] = new Date(data[k]);
                    }
                }
            });
            return node;
        }
        static deserializeConnections(icons, nodesMap) {
            var connections = [];
            icons.forEach(function(icon) {
                var source = nodesMap[icon.id];
                if (source instanceof Node) {
                    if (icon.connections) {
                        icon.connections.forEach(function(connection) {
                            var target = nodesMap[connection.targetIconId];
                            if (target instanceof Node) {
                                connections.push({
                                    source: source,
                                    target: target
                                });
                            }
                        });
                    }
                }
            });
            return connections;
        }
        static toMap(nodes) {
            var map = {};
            nodes.forEach(function(node) {
                map[node.getId()] = node;
            });
            return map;
        }
        appendTo($container, $titlesContainer, animation) {
            this.$container = $container;
            this.$titlesContainer = $titlesContainer;
            if (animation) {
                this.$element.addClass(animation);
            }
            $container.append(this.$element);
            $titlesContainer.append(this.$titleDiv);
            this.$titleDiv.toggleClass("expandable", this.$titleSpan.height() > this.$titleDiv.height());
        }
        isAppended() {
            return !!this.$container;
        }
        get $inUseBadge() {
            return this.$element.find(".node-status-badge");
        }
        toggleInUseBadge() {
            return this.$inUseBadge.toggle(Def.sentMailings.includes(parseInt(this.data.mailingId)));
        }
        get$() {
            return this.$element;
        }
        getId() {
            return this.id;
        }
        setId(id) {
            this.id = id;
            this.$element.prop("id", id);
        }
        getX() {
            return this.x;
        }
        getY() {
            return this.y;
        }
        getCoordinates() {
            return {
                x: this.x,
                y: this.y
            };
        }
        setCoordinates(x, y) {
            this.x = x;
            this.y = y;
            this.$element.css("left", x * Def.CANVAS_GRID_SIZE);
            this.$element.css("top", y * Def.CANVAS_GRID_SIZE);
        }
        updateCoordinates(scale) {
            var position = Node.getPosition(this.$element);
            this.x = position.x / scale / Def.CANVAS_GRID_SIZE;
            this.y = position.y / scale / Def.CANVAS_GRID_SIZE;
        }
        getType() {
            return this.type;
        }
        setType(type) {
            this.type = type;
            this.$element.find(".node-image").replaceWith(Template.dom("workflow-node-icon", {
                type: type
            }));
        }
        getTitle() {
            return this.title;
        }
        setTitle(title) {
            this.title = title;
            if (title) {
                this.$titleSpan.text(title);
                this.positionTitle(this.lastTitleAnchor);
                this.$titleDiv.toggleClass("expandable", this.$titleSpan.height() > this.$titleDiv.height());
            }
            this.setTitleEnabled(!!title);
        }
        setTitleEnabled(isEnabled) {
            this.$titleDiv.toggle(!!isEnabled && !!this.title);
        }
        setTitleExpanded(isExpanded) {
            this.$titleDiv.toggleClass("expanded", !!isExpanded);
            if (this.isAppended()) {
                if (isExpanded) {
                    this.$titleDiv.appendTo(this.$container);
                } else {
                    this.$titleDiv.appendTo(this.$titlesContainer);
                }
            }
        }
        positionTitle(anchor) {
            this.lastTitleAnchor = anchor;
            var minX = this.x * Def.CANVAS_GRID_SIZE;
            var maxX = minX + Def.NODE_SIZE;
            var minY = this.y * Def.CANVAS_GRID_SIZE;
            var maxY = minY + Def.NODE_SIZE;
            switch (anchor) {
              case Def.BOTTOM:
                this.$titleDiv.css({
                    top: maxY,
                    left: minX + (Def.NODE_SIZE - Def.TITLE_WIDTH) / 2,
                    transform: "none"
                });
                break;

              case Def.LEFT:
                this.$titleDiv.css({
                    top: (minY + maxY) / 2,
                    left: minX - Def.TITLE_WIDTH,
                    transform: "translateY(-50%)"
                });
                break;

              case Def.RIGHT:
                this.$titleDiv.css({
                    top: (minY + maxY) / 2,
                    left: maxX,
                    transform: "translateY(-50%)"
                });
                break;

              case Def.TOP:
                this.$titleDiv.css({
                    top: minY,
                    left: minX + (Def.NODE_SIZE - Def.TITLE_WIDTH) / 2,
                    transform: "translateY(-100%)"
                });
                break;

              default:
                return;
            }
        }
        getOverlayTitle() {
            return this.overlayTitle;
        }
        setOverlayTitle(overlayTitle) {
            this.overlayTitle = overlayTitle;
            this.$overlayTitle.text(_.trim(overlayTitle));
        }
        getComment() {
            return this.comment;
        }
        get $commentBtn() {
            return this.$element.find(".node-comment-button");
        }
        setComment(comment) {
            this.comment = this.data.iconComment = comment;
            this.updateCommentLabels();
        }
        updateCommentLabels() {
            const commented = !!_.trim(this.comment);
            this.$element.toggleClass("icon-commented", commented);
            this.$commentBtn.toggle(commented);
        }
        setFootnote(footnoteId) {
            if (footnoteId > 0) {
                this.$element.attr("comment-footnote", footnoteId);
            } else {
                this.$element.removeAttr("comment-footnote");
            }
        }
        isFilled() {
            return this.filled;
        }
        setFilled(filled) {
            this.filled = filled;
            this.$element.toggleClass("active", filled);
            if (filled && this.isMailingNode()) {
                this.toggleInUseBadge();
            }
        }
        isEditable() {
            return this.editable;
        }
        setEditable(editable) {
            this.editable = editable;
        }
        isExpandable() {
            return this.expandable;
        }
        setExpandable(expandable) {
            this.expandable = expandable;
        }
        isDependent() {
            return this.dependent;
        }
        setDependent(dependent) {
            this.dependent = dependent;
        }
        isInRecipientsChain() {
            return this.inRecipientsChain;
        }
        setInRecipientsChain(inRecipientsChain) {
            this.inRecipientsChain = inRecipientsChain;
        }
        getAnchors() {
            return this.anchors;
        }
        setAnchors(anchors) {
            this.anchors = anchors;
        }
        getData() {
            return this.data;
        }
        setData(data) {
            this.data = data;
        }
        setInteractionEnabled(isEnabled) {
            this.$connectionButton.toggle(!!isEnabled);
        }
        removePopover() {
            this.nodePopover.remove();
        }
        setPopoverEnabled(isEnabled) {
            this.nodePopover.setEnabled(isEnabled);
        }
        setHovered(isHovered) {
            this.setTitleExpanded(isHovered);
        }
        remove() {
            this.nodePopover.remove();
            this.$element.remove();
            this.$titleDiv.remove();
            this.$container = null;
            this.$titlesContainer = null;
        }
        serialize() {
            var object = $.extend({}, this.data, {
                id: this.id,
                x: this.x,
                y: this.y,
                type: this.type,
                filled: this.filled,
                editable: this.editable,
                iconTitle: this.title
            });
            if ("date" in object && "hour" in object && "minute" in object) {
                object.date = DateTimeUtils.getDateTimeValue(object.date, object.hour, object.minute);
            }
            if ("remindDate" in object && "remindHour" in object && "remindMinute" in object) {
                object.remindDate = DateTimeUtils.getDateTimeValue(object.remindDate, object.remindHour, object.remindMinute);
            }
            if ("decisionDate" in object) {
                object.decisionDate = DateTimeUtils.getDateTimeValue(object.decisionDate);
            }
            return object;
        }
    }
    AGN.Lib.WM.Node = Node;
})();

(function() {
    var Node = AGN.Lib.WM.Node;
    function Vertex(node) {
        this.id = node.getId();
        this.node = node;
        this.position = Node.getPosition(node.get$());
        this.box = Node.getBox(node.get$());
        this.connections = {
            incoming: [],
            outgoing: []
        };
    }
    Vertex.nodesToVertices = function(nodes) {
        return nodes.map(function(node) {
            return new Vertex(node);
        });
    };
    Vertex.verticesToMap = function(vertices) {
        var map = {};
        vertices.forEach(function(vertex) {
            map[vertex.id] = vertex;
        });
        return map;
    };
    Vertex.verticesFrom = function(nodes, connections) {
        var vertices = Vertex.nodesToVertices(nodes);
        var vertexMap = Vertex.verticesToMap(vertices);
        connections.forEach(function(connection) {
            var source, target;
            if ("sourceId" in connection) {
                source = vertexMap[connection.sourceId];
                target = vertexMap[connection.targetId];
            } else {
                source = vertexMap[connection.source.getId()];
                target = vertexMap[connection.target.getId()];
            }
            source.connections.outgoing.push(target);
            target.connections.incoming.push(source);
        });
        return vertices;
    };
    Vertex.compareByPosition = function(v1, v2) {
        var box1 = v1.box;
        var box2 = v2.box;
        if (box1.minX == box2.minX) {
            return box1.minY - box2.minY;
        }
        return box1.minX - box2.minX;
    };
    Vertex.filterUnvisited = function(vertices, visitedIds) {
        return vertices.filter(function(vertex) {
            if (visitedIds[vertex.id]) {
                return false;
            } else {
                visitedIds[vertex.id] = true;
                return true;
            }
        });
    };
    Vertex.getDecisionBranches = function(sourceVertex) {
        var connections = sourceVertex.connections.outgoing.map(function(targetVertex) {
            return {
                source: sourceVertex.node,
                target: targetVertex.node,
                targetVertex: targetVertex
            };
        });
        var targets = Node.getDecisionBranches(connections);
        if (targets) {
            return {
                positive: targets.positive.targetVertex,
                negative: targets.negative.targetVertex
            };
        }
        return null;
    };
    Vertex.getIncomingChains = function(vertex) {
        var visitedIds = {};
        var chains = [];
        collectIncomingChains([], vertex, visitedIds, chains);
        return chains;
    };
    Vertex.getOutgoingChains = function(vertex) {
        var visitedIds = {};
        var chains = [];
        collectOutgoingChains([], vertex, visitedIds, chains);
        return chains;
    };
    Vertex.prototype.getNode = function() {
        return this.node;
    };
    Vertex.prototype.siblings = function() {
        return this.connections.incoming.concat(this.connections.outgoing);
    };
    Vertex.prototype.rightSiblingsOrdered = function() {
        var siblings = this.connections.outgoing;
        if (Node.isBranchingDecisionNode(this.node)) {
            var targets = Vertex.getDecisionBranches(this);
            if (targets) {
                return [ targets.positive, targets.negative ];
            }
        }
        return siblings.sort(function(v1, v2) {
            return v1.node.getY() - v2.node.getY();
        });
    };
    function collectIncomingChains(chain, vertex, visitedIds, chains) {
        if (visitedIds[vertex.id]) {
            chains.push(chain);
        } else {
            chain.push(vertex.node);
            var connections = vertex.connections.incoming;
            if (connections.length) {
                visitedIds[vertex.id] = true;
                if (connections.length == 1) {
                    collectIncomingChains(chain, connections[0], visitedIds, chains);
                } else {
                    connections.forEach(function(connection) {
                        collectIncomingChains(chain.slice(), connection, visitedIds, chains);
                    });
                }
                visitedIds[vertex.id] = false;
            } else {
                chains.push(chain);
            }
        }
    }
    function collectOutgoingChains(chain, vertex, visitedIds, chains) {
        if (visitedIds[vertex.id]) {
            chains.push(chain);
        } else {
            chain.push(vertex.node);
            var connections = vertex.connections.outgoing;
            if (connections.length) {
                visitedIds[vertex.id] = true;
                if (connections.length == 1) {
                    collectOutgoingChains(chain, connections[0], visitedIds, chains);
                } else {
                    connections.forEach(function(connection) {
                        collectOutgoingChains(chain.slice(), connection, visitedIds, chains);
                    });
                }
                visitedIds[vertex.id] = false;
            } else {
                chains.push(chain);
            }
        }
    }
    AGN.Lib.WM.Vertex = Vertex;
})();

(function() {
    var Vertex = AGN.Lib.WM.Vertex;
    function VertexGroup(vertices) {
        this.vertices = vertices;
        this.box = vertices.map(function(v) {
            return v.box;
        }).reduce(function(b1, b2) {
            return {
                minX: Math.min(b1.minX, b2.minX),
                minY: Math.min(b1.minY, b2.minY),
                maxX: Math.max(b1.maxX, b2.maxX),
                maxY: Math.max(b1.maxY, b2.maxY)
            };
        });
    }
    VertexGroup.detectGroups = function(vertices) {
        var groups = [];
        var visitedIds = {};
        vertices.forEach(function(vertex) {
            var group = VertexGroup.detectGroup(vertex, visitedIds);
            if (group) {
                groups.push(group);
            }
        });
        return groups.sort(VertexGroup.compareByPosition);
    };
    VertexGroup.detectGroup = function(vertex, visitedIds) {
        if (visitedIds[vertex.id]) {
            return null;
        }
        var group = [];
        var vertices = vertex.siblings();
        group.push(vertex);
        visitedIds[vertex.id] = true;
        while (vertices.length) {
            vertices = _.flatMap(vertices, function(v) {
                if (visitedIds[v.id]) {
                    return [];
                } else {
                    group.push(v);
                    visitedIds[v.id] = true;
                    return v.siblings();
                }
            });
        }
        return new VertexGroup(group);
    };
    VertexGroup.compareByPosition = function(g1, g2) {
        var d = g1.box.minX + g1.box.maxX - (g2.box.minX + g2.box.maxX);
        if (d == 0) {
            return g1.box.minY + g1.box.maxY - (g2.box.minY + g2.box.maxY);
        }
        return d;
    };
    VertexGroup.prototype.getNodes = function() {
        return this.vertices.map(function(vertex) {
            return vertex.getNode();
        });
    };
    VertexGroup.prototype.getStartingVertices = function() {
        var startingVertices = this.vertices.filter(function(vertex) {
            return vertex.connections.incoming.length == 0;
        });
        if (startingVertices.length) {
            return startingVertices.sort(Vertex.compareByPosition);
        }
        var bestCandidate = this.vertices.reduce(function(v1, v2) {
            var rate1 = v1.connections.outgoing.length / v1.connections.incoming.length;
            var rate2 = v2.connections.outgoing.length / v2.connections.incoming.length;
            if (rate1 == rate2) {
                return Vertex.compareByPosition(v1, v2) >= 0 ? v1 : v2;
            }
            return rate1 > rate2 ? v1 : v2;
        });
        return [ bestCandidate ];
    };
    AGN.Lib.WM.VertexGroup = VertexGroup;
})();

(function() {
    var Def = AGN.Lib.WM.Definitions, DateTimeUtils = AGN.Lib.WM.DateTimeUtils;
    var ENTITY_NAMES_BY_TYPE = {};
    var NodeTitleHelper = function() {};
    function getEntityNameByType(type, id, url) {
        if (id <= 0) {
            return "";
        }
        if (_.isEmpty(ENTITY_NAMES_BY_TYPE[type])) {
            $.ajax({
                url: AGN.url(url),
                async: false
            }).done(function(resp) {
                ENTITY_NAMES_BY_TYPE[type] = _.extend({}, resp);
            });
        }
        var name = ENTITY_NAMES_BY_TYPE[type][id];
        return !!name ? name : "";
    }
    NodeTitleHelper.addArchiveName = function(id, name) {
        addEntityName("archive", id, name);
    };
    NodeTitleHelper.addMailingName = function(id, name) {
        addEntityName("mailing", id, name);
    };
    function addEntityName(type, id, name) {
        const names = ENTITY_NAMES_BY_TYPE[type] || {};
        names[id] = name;
        ENTITY_NAMES_BY_TYPE[type] = names;
    }
    NodeTitleHelper.getWebFormName = function(webFormId) {
        return getEntityNameByType("form", webFormId, "/workflow/ajax/getWebFormNames.action");
    };
    NodeTitleHelper.getTargetName = function(targetId) {
        return getEntityNameByType("target", targetId, "/workflow/ajax/getTargetNames.action");
    };
    NodeTitleHelper.getMailingName = function(mailingId) {
        return getEntityNameByType("mailing", mailingId, "/workflow/ajax/getMailingNames.action");
    };
    NodeTitleHelper.getArchiveName = function(archiveId) {
        return getEntityNameByType("archive", archiveId, "/workflow/ajax/getArchiveNames.action");
    };
    NodeTitleHelper.getAutoExportName = function(autoExportId) {
        return getEntityNameByType("autoExport", autoExportId, "/workflow/ajax/getAutoExportNames.action");
    };
    NodeTitleHelper.getAutoImportName = function(autoImportId) {
        return getEntityNameByType("autoImport", autoImportId, "/workflow/ajax/getAutoImportNames.action");
    };
    NodeTitleHelper.getMailinglistName = function(mailinglistId) {
        return getEntityNameByType("mailinglist", mailinglistId, "/workflow/ajax/getMailinglistNames.action");
    };
    function getReactionName(reaction) {
        switch (reaction) {
          case Def.constants.reactionOpened:
            return t("workflow.reaction.opened");

          case Def.constants.reactionNotOpened:
            return t("workflow.reaction.not_opened");

          case Def.constants.reactionClicked:
            return t("workflow.reaction.clicked");

          case Def.constants.reactionNotClicked:
            return t("workflow.reaction.not_clicked");

          case Def.constants.reactionBought:
            return t("workflow.reaction.bought");

          case Def.constants.reactionNotBought:
            return t("workflow.reaction.not_bought");

          case Def.constants.reactionChangeOfProfile:
            return t("workflow.reaction.change_of_profile");

          case Def.constants.reactionWaitingForConfirm:
            return t("workflow.reaction.waiting_for_confirm");

          case Def.constants.reactionOptIn:
            return t("workflow.reaction.opt_in");

          case Def.constants.reactionOptOut:
            return t("workflow.reaction.opt_out");

          case Def.constants.reactionClickedLink:
            return t("workflow.reaction.clicked_on_link");

          case Def.constants.reactionOpenedAndClicked:
            return t("workflow.reaction.opened_and_clicked");

          case Def.constants.reactionOpenedOrClicked:
            return t("workflow.reaction.opened_or_clicked");
        }
    }
    function getDelayUnitName(delayValue, delayUnit) {
        if (delayValue > 1) {
            switch (delayUnit) {
              case Def.constants.deadlineTimeUnitMinute:
                return t("workflow.deadline.minutes");

              case Def.constants.deadlineTimeUnitHour:
                return t("workflow.defaults.hours");

              case Def.constants.deadlineTimeUnitDay:
                return t("workflow.defaults.days");

              case Def.constants.deadlineTimeUnitWeek:
                return t("workflow.defaults.weeks");

              case Def.constants.deadlineTimeUnitMonth:
                return t("workflow.defaults.months");
            }
        } else {
            switch (delayUnit) {
              case Def.constants.deadlineTimeUnitMinute:
                return t("workflow.deadline.minute");

              case Def.constants.deadlineTimeUnitHour:
                return t("workflow.defaults.hour");

              case Def.constants.deadlineTimeUnitDay:
                return t("workflow.defaults.day");

              case Def.constants.deadlineTimeUnitWeek:
                return t("workflow.defaults.week");

              case Def.constants.deadlineTimeUnitMonth:
                return t("workflow.defaults.month");
            }
        }
    }
    function getDecisionCriteriaName(value) {
        switch (value) {
          case Def.constants.decisionAOCriteriaClickRate:
            return t("workflow.defaults.ckickrate");

          case Def.constants.decisionAOCriteriaOpenrate:
            return t("workflow.opening_rate");

          default:
            return t("workflow.statistic.revenue");
        }
    }
    function getCloseParenthesis(value) {
        switch (Number(value)) {
          case 1:
            return ")";

          case 0:
            return "";
        }
    }
    function getOpenParenthesis(value) {
        switch (Number(value)) {
          case 1:
            return "(";

          case 0:
            return "";
        }
    }
    function getProfileFieldValue(field, value) {
        if (field && Def.GENDER_PROFILE_FIELD === field.toLowerCase()) {
            return Def.constants.genderOptions[!value ? 0 : value];
        } else {
            return _.isEmpty(value) ? "" : value;
        }
    }
    function getRulesDescription(profileField, rules) {
        var rulesMsg = "";
        rules.forEach(function(rule) {
            rulesMsg += (_.isEmpty(rulesMsg) ? "" : " " + rule.chainOperator + " ") + getOpenParenthesis(rule.parenthesisOpened) + profileField + " " + Def.constants.operatorsMap[rule.primaryOperator] + " " + getProfileFieldValue(profileField, rule.primaryValue) + getCloseParenthesis(rule.parenthesisClosed);
        });
        return t("workflow.start.rule") + (!!rulesMsg ? ": " + rulesMsg : "");
    }
    function getTargetsDescription(targets, option) {
        var targetNames = [];
        for (var i = 0; i < Def.TITLE_MAX_TARGETS && i < targets.length; i++) {
            targetNames.push(NodeTitleHelper.getTargetName(targets[i]));
        }
        var separator = ", ";
        if (Def.constants.targetOptions[option]) {
            separator = " " + Def.constants.targetOptions[option] + " ";
        }
        if (targets.length > Def.TITLE_MAX_TARGETS) {
            return targetNames.join(separator) + " " + t("defaults.andMore", targets.length - Def.TITLE_MAX_TARGETS) + "...";
        } else {
            return targetNames.join(separator);
        }
    }
    function getDateDescription(date, hour, minute) {
        if (date) {
            if (arguments.length === 1) {
                return DateTimeUtils.getDateStr(date, Def.constants.localeDateTimePattern);
            } else {
                return DateTimeUtils.getDateTimeStr(date, hour, minute, Def.constants.localeDateTimePattern);
            }
        } else {
            return "";
        }
    }
    function getDelayDescription(value, timeUnit) {
        return value + " " + getDelayUnitName(value, timeUnit);
    }
    function getReactionDescription(reaction, mailingId) {
        return t("workflow.reaction.title") + ": " + getReactionName(reaction) + ",\n" + t("workflow.defaults.mailing") + ": " + NodeTitleHelper.getMailingName(mailingId);
    }
    function getAutoOptimizationDescription(criteria, threshold, date) {
        var description = getDecisionCriteriaName(criteria) + (_.isEmpty(threshold) ? "" : ": " + threshold) + "\n";
        if (!!date) {
            description += t("workflow.defaults.date") + ": " + getDateDescription(date);
        }
        return description;
    }
    function getDateBasedStartDescription(field, operator, value) {
        return field + " " + Def.constants.operatorsMap[operator] + (!value ? "" : " " + value);
    }
    function getFollowupMailingDescription(followUpMailingName, baseMailingName, reaction) {
        if (followUpMailingName) {
            if (baseMailingName) {
                return baseMailingName + " (" + getReactionName(reaction) + ") " + followUpMailingName;
            } else {
                return followUpMailingName;
            }
        }
    }
    function getRecipientDescription(mailinglistId, targets, targetsOption, showMailingList) {
        var title = "";
        if (showMailingList) {
            title += t("workflow.mailinglist.short") + ": " + NodeTitleHelper.getMailinglistName(mailinglistId);
        }
        if (!_.isEmpty(targets)) {
            if (!_.isEmpty(title)) {
                title += "\n";
            }
            title += t("workflow.target.short") + ": " + getTargetsDescription(targets, targetsOption);
        }
        return title;
    }
    NodeTitleHelper.positionTitle = function(node, anchorsInUse) {
        if (node.type === "split") {
            node.positionTitle(Def.BOTTOM);
            return;
        }
        if (anchorsInUse[Def.BOTTOM]) {
            if (anchorsInUse[Def.LEFT]) {
                if (anchorsInUse[Def.RIGHT]) {
                    if (anchorsInUse[Def.TOP]) {
                        node.positionTitle(Def.BOTTOM);
                    } else {
                        node.positionTitle(Def.TOP);
                    }
                } else {
                    node.positionTitle(Def.RIGHT);
                }
            } else {
                node.positionTitle(Def.LEFT);
            }
        } else {
            node.positionTitle(Def.BOTTOM);
        }
    };
    var getStartNodeTitle = function(data) {
        var startType = data.startType;
        var title = "";
        if (Def.constants.startTypeDate === startType) {
            title = t("workflow.start.start_date") + ":\n" + getDateDescription(data.date, data.hour, data.minute);
        } else if (Def.constants.startTypeEvent === startType) {
            var eventType = data.event;
            if (Def.constants.startEventReaction === eventType) {
                title = t("workflow.start.start_event") + ":\n" + getReactionName(data.reaction) + ": (" + getDateDescription(data.date, data.hour, data.minute) + ")";
            } else if (Def.constants.startEventDate === eventType) {
                title = t("workflow.start.start_event") + ":\n" + getDateBasedStartDescription(data.dateProfileField, data.dateFieldOperator, data.dateFieldValue) + ":\n" + "(" + getDateDescription(data.date, data.hour, data.minute) + ")";
            }
        }
        return title;
    };
    var getStopNodeTitle = function(data, node, isNormalWorkflow) {
        var endType = data.endType;
        var title = "";
        if (Def.constants.endTypeDate === endType) {
            title = t("workflow.stop.end_date") + ":\n" + getDateDescription(data.date, data.hour, data.minute);
        } else if (Def.constants.endTypeAutomatic === endType) {
            title = isNormalWorkflow ? t("workflow.stop.automatic_end") : t("workflow.stop.open_end");
        }
        return title;
    };
    var getDeadlineNodeTitle = function(data) {
        var deadlineType = data.deadlineType;
        var title = "";
        if (Def.constants.deadlineTypeFixedDeadline === deadlineType) {
            title = t("workflow.deadline.title") + ":\n" + getDateDescription(data.date, data.hour, data.minute);
        } else if (Def.constants.deadlineTypeDelay === deadlineType) {
            title = t("workflow.defaults.delay") + ":\n" + getDelayDescription(data.delayValue, data.timeUnit);
        }
        return title;
    };
    var getDecisionNodeTitle = function(data) {
        var decisionType = data.decisionType;
        var title = "";
        if (Def.constants.decisionTypeAutoOptimization === decisionType) {
            title = t("workflow.mailing.autooptimization") + ":\n" + getAutoOptimizationDescription(data.aoDecisionCriteria, data.threshold, data.decisionDate);
        } else {
            if (Def.constants.decisionReaction === data.decisionCriteria) {
                title = t("workflow.decision") + ",\n" + getReactionDescription(data.reaction, data.mailingId);
            } else {
                title = t("workflow.decision") + ",\n" + getRulesDescription(data.profileField, data.rules);
            }
        }
        return title;
    };
    var getFollowUpMailingNodeTitle = function(data, node) {
        var baseMailingName, followUpMailingName;
        var title = node.title;
        baseMailingName = NodeTitleHelper.getMailingName(data.baseMailingId) || "?";
        followUpMailingName = NodeTitleHelper.getMailingName(data.mailingId) || "?";
        var description = getFollowupMailingDescription(followUpMailingName, baseMailingName, data.decisionCriterion);
        if (description) {
            title = description;
        }
        return title;
    };
    var MAILING_TITLE_CONFIG = {
        title: function(data) {
            return NodeTitleHelper.getMailingName(data.mailingId);
        }
    };
    const TITLE_CONFIG = {
        "*": {
            overlayTitle: "",
            title: ""
        },
        start: {
            title: getStartNodeTitle
        },
        stop: {
            title: getStopNodeTitle
        },
        deadline: {
            title: getDeadlineNodeTitle
        },
        parameter: {
            title: "",
            overlayTitle: data => data.value
        },
        split: {
            title: data => t(`split.ratio.${data.splitType}`)
        },
        decision: {
            title: getDecisionNodeTitle,
            branches: {
                title: () => ({
                    positive: t("defaults.yes"),
                    negative: t("defaults.no")
                })
            }
        },
        recipient: {
            title: (data, node) => getRecipientDescription(data.mailinglistId, data.targets, data.targetsOption, !node.isInRecipientsChain())
        },
        archive: {
            title: data => NodeTitleHelper.getArchiveName(data.campaignId)
        },
        form: {
            title: data => NodeTitleHelper.getWebFormName(data.userFormId)
        },
        mailing: MAILING_TITLE_CONFIG,
        mailing_mediatype_sms: MAILING_TITLE_CONFIG,
        mailing_mediatype_post: MAILING_TITLE_CONFIG,
        actionbased_mailing: MAILING_TITLE_CONFIG,
        datebased_mailing: MAILING_TITLE_CONFIG,
        followup_mailing: {
            title: getFollowUpMailingNodeTitle
        },
        import: {
            title: data => NodeTitleHelper.getAutoImportName(data.importexportId)
        },
        export: {
            title: data => NodeTitleHelper.getAutoExportName(data.importexportId)
        }
    };
    function ignoreUpdateTitle(node) {
        var type = node.getType();
        if (Def.NODE_TYPES_MAILING.includes(type) || Def.NODE_TYPES_IMPORT_EXPORT.includes(type)) {
            return !!node.title;
        }
        return false;
    }
    NodeTitleHelper.getDecisionBranchesLabels = function() {
        return TITLE_CONFIG.decision.branches.title();
    };
    NodeTitleHelper.updateTitle = function(node, isNormalWorkflow, forceUpdate) {
        if (!forceUpdate && ignoreUpdateTitle(node)) {
            return;
        }
        if (!node.isFilled()) {
            node.setTitle("");
            node.setOverlayTitle("");
            return;
        }
        node.setTitle(generateNodeTitle(node, isNormalWorkflow));
        node.setOverlayTitle(generateOverlayTitle(node));
    };
    function generateOverlayTitle(node) {
        return getConfiguration(node.getType(), "overlayTitle", node.getData());
    }
    function generateNodeTitle(node, isNormalWorkflow) {
        return getConfiguration(node.getType(), "title", node.getData(), node, isNormalWorkflow);
    }
    function getConfiguration(type, configName) {
        var configs = TITLE_CONFIG[type];
        if (!configs.hasOwnProperty(configName)) {
            configs = TITLE_CONFIG["*"];
        }
        var config = configs[configName];
        var args = Array.prototype.slice.call(arguments, 2);
        return _.isFunction(config) ? config.apply(configs, args) : config;
    }
    AGN.Lib.WM.NodeTitleHelper = NodeTitleHelper;
})();

(function() {
    const Node = AGN.Lib.WM.Node;
    const Def = AGN.Lib.WM.Definitions;
    const ARROW_CLICK_STEP = 50;
    class MinimapCanvas {
        constructor(minimap, selector) {
            this.minimap = minimap;
            this.$element = minimap.$container.find(selector);
            this.scale = 1;
        }
        setScale(scale) {
            this.scale = scale;
        }
        getScale() {
            return this.scale;
        }
        getPosition() {
            var position = this.$element.position();
            return {
                x: position.left,
                y: position.top
            };
        }
        update() {
            this.reset();
            var pureBox = this.minimap.getPureIconsBox();
            var padding = Def.MINIMAP_PADDING * 2;
            var width = pureBox.maxX - pureBox.minX + padding;
            var height = pureBox.maxY - pureBox.minY + padding;
            var xRatio = (this.minimap.getWidth() - padding) / width;
            var yRatio = (this.minimap.getHeight() - padding) / height;
            this.setScale(Math.min(xRatio, yRatio));
            var left = -pureBox.minX * this.scale + Def.MINIMAP_PADDING;
            var top = -pureBox.minY * this.scale + Def.MINIMAP_PADDING;
            this.$element.css({
                transform: "scale(" + this.scale + ")",
                width: width,
                height: height,
                left: left,
                top: top
            });
            this.renderIcons();
        }
        renderIcons() {
            var self = this;
            this.minimap.getPureIconsPosition().forEach(function(position) {
                var $node = $('<div class="miniview-element"></div>').css({
                    width: Def.NODE_SIZE,
                    height: Def.NODE_SIZE,
                    left: position.x,
                    top: position.y
                });
                self.$element.append($node);
            });
        }
        reset() {
            this.scale = 1;
            this.$element.css({
                transform: "scale(1)",
                width: 0,
                height: 0,
                left: 0,
                top: 0
            });
            this.$element.html("");
        }
    }
    class MinimapPanner {
        constructor(minimap, selector, options) {
            this.minimap = minimap;
            this.$element = minimap.get$().find(selector);
            this.onDrag = _.isFunction(options.onPannerDrag) ? options.onPannerDrag : _.noop;
            this.containment = $.extend({
                mode: "",
                padding: 0
            }, options.containment);
            this.containmentBox = null;
            var self = this;
            var prevX = 0;
            var prevY = 0;
            this.$element.draggable({
                start: function(event, ui) {
                    prevX = ui.position.left;
                    prevY = ui.position.top;
                    if (!self.containmentBox) {
                        self.containmentBox = self.getContainmentBox(self.containment);
                    }
                },
                drag: function(event, ui) {
                    var scale = self.getScale();
                    if (self.containmentBox) {
                        var left = ui.position.left;
                        var top = ui.position.top;
                        if (left < self.containmentBox.minX) {
                            ui.position.left = self.containmentBox.minX;
                        } else if (left > self.containmentBox.maxX) {
                            ui.position.left = self.containmentBox.maxX;
                        }
                        if (top < self.containmentBox.minY) {
                            ui.position.top = self.containmentBox.minY;
                        } else if (top > self.containmentBox.maxY) {
                            ui.position.top = self.containmentBox.maxY;
                        }
                    }
                    var dX = (prevX - ui.position.left) / scale;
                    var dY = (prevY - ui.position.top) / scale;
                    prevX = ui.position.left;
                    prevY = ui.position.top;
                    self.onDrag.call(self, dX, dY);
                }
            });
        }
        getContainmentBox(options) {
            if (!options.mode || options.mode == "none") {
                return undefined;
            }
            var $minimap = this.minimap.get$();
            var scaledWidth = this.getScaledWidth();
            var scaledHeight = this.getScaledHeight();
            if (options.mode == "panner-box") {
                return {
                    minX: -scaledWidth + options.padding,
                    maxX: $minimap.width() - options.padding,
                    minY: -scaledHeight + options.padding,
                    maxY: $minimap.height() - options.padding
                };
            } else if (options.mode == "minimap-box") {
                return {
                    minX: options.padding,
                    maxX: Math.max(0, $minimap.width() - scaledWidth) - options.padding,
                    minY: options.padding,
                    maxY: Math.max(0, $minimap.height() - scaledHeight) - options.padding
                };
            }
            return undefined;
        }
        getScale() {
            return this.minimap.getMiniCanvasScale() / this.minimap.getCanvasZoom();
        }
        getScaledWidth() {
            return this.getWidth() * this.getScale();
        }
        getScaledHeight() {
            return this.getHeight() * this.getScale();
        }
        getWidth() {
            return this.$element.width();
        }
        getHeight() {
            return this.$element.height();
        }
        update() {
            var viewPortScreen = this.minimap.getCanvasParent$();
            var originWidth = viewPortScreen.width();
            var originHeight = viewPortScreen.height();
            var width = originWidth + Def.MINIMAP_PADDING * 2;
            var height = originHeight + Def.MINIMAP_PADDING * 2;
            this.$element.css({
                width: width,
                height: height
            });
            this.containmentBox = this.getContainmentBox(this.containment);
            this.updatePosition();
        }
        updatePosition() {
            var position = this.minimap.getCanvasPosition();
            var delta = this.minimap.getMiniCanvasPosition();
            var scale = this.getScale();
            var left = -position.x * scale + delta.x;
            var top = -position.y * scale + delta.y;
            this.$element.css({
                transform: "scale(" + scale + ")",
                left: left,
                top: top
            });
        }
    }
    class Minimap {
        constructor(canvas, options) {
            this.$container = $("#minimap");
            this.canvas = canvas;
            this.miniCanvas = new MinimapCanvas(this, ".minimap-canvas", options);
            this.miniPanner = new MinimapPanner(this, ".minimap-panner", options);
            this.enabled = false;
            const $collapseBtn = this.$container.find(".minimap-collapse");
            const $enlargeBtn = $("#collapsed-navigator");
            this.$container.on("click", ".minimap-panner, .minimap-collapse, .minimap-arrow", e => e.preventFocusOnArea = true);
            $collapseBtn.on("click", () => this.toggleMinimap(false));
            $enlargeBtn.on("click", () => this.toggleMinimap(true));
            this.$container.on("click", e => this.moveToClickPos(e));
            this.$container.find(".minimap-arrow").on("click", e => {
                const direction = $(e.currentTarget).data("arrow");
                const newPos = this.#getStepPos(direction);
                this.moveCanvasTo(newPos.x, newPos.y);
            });
        }
        #getStepPos(direction) {
            const {x: x, y: y} = this.canvas.getPosition();
            switch (direction) {
              case "up":
                return {
                    x: x,
                    y: y + ARROW_CLICK_STEP
                };

              case "right":
                return {
                    x: x - ARROW_CLICK_STEP,
                    y: y
                };

              case "down":
                return {
                    x: x,
                    y: y - ARROW_CLICK_STEP
                };

              case "left":
                return {
                    x: x + ARROW_CLICK_STEP,
                    y: y
                };
            }
        }
        moveToClickPos(e) {
            if (e.preventFocusOnArea) {
                return;
            }
            const rec = this.$container[0].getBoundingClientRect();
            const pX = e.clientX - rec.left;
            const pY = e.clientY - rec.top;
            this.focusOnClickedArea(pX, pY);
        }
        get$() {
            return this.$container;
        }
        getWidth() {
            return this.get$().width();
        }
        getHeight() {
            return this.get$().height();
        }
        moveCanvasTo(x, y) {
            this.canvas.moveTo(x, y);
        }
        getCanvas$() {
            return this.canvas.get$();
        }
        getCanvasParent$() {
            return this.canvas.get$().parent();
        }
        focusOnClickedArea(pointerX, pointerY) {
            var miniCanvasPosition = this.getMiniCanvasPosition();
            var scale = this.getMiniPannerScale();
            var x = (pointerX - miniCanvasPosition.x) / scale;
            var y = (pointerY - miniCanvasPosition.y) / scale;
            var miniPannerCenter = this.getMiniPannerCenter();
            var zoom = this.getCanvasZoom();
            var centeredX = (x - miniPannerCenter.x) * zoom;
            var centeredY = (y - miniPannerCenter.y) * zoom;
            this.moveCanvasTo(-centeredX, -centeredY);
        }
        toggleMinimap(shown) {
            $("#navigator").toggle(shown);
            $("#collapsed-navigator").toggle(!shown);
        }
        getIcons() {
            return this.canvas.getIcons();
        }
        getPureIconsPosition() {
            var zoom = this.getCanvasZoom();
            return this.getIcons().map(function($element) {
                var position = Node.getPosition($element);
                return {
                    x: position.x / zoom,
                    y: position.y / zoom
                };
            });
        }
        getPureIconsBox() {
            return this.canvas.getPureIconsBox();
        }
        getMiniCanvasScale() {
            return this.miniCanvas.getScale();
        }
        getMiniCanvasPosition() {
            return this.miniCanvas.getPosition();
        }
        getMiniPannerScale() {
            return this.miniCanvas.getScale();
        }
        getMiniPannerCenter() {
            return {
                x: this.miniPanner.getWidth() / 2,
                y: this.miniPanner.getHeight() / 2
            };
        }
        getCanvasZoom() {
            return this.canvas.getZoom();
        }
        getCanvasPosition() {
            return this.canvas.getPosition();
        }
        updateMinimap() {
            if (this.enabled) {
                this.miniCanvas.update();
                this.miniPanner.update();
            }
        }
        onPanZoom() {
            if (this.enabled) {
                this.miniPanner.updatePosition();
            }
        }
        setEnabled(isEnabled) {
            this.enabled = isEnabled;
            if (isEnabled) {
                this.updateMinimap();
                this.get$().show();
            } else {
                this.get$().hide();
            }
        }
    }
    AGN.Lib.WM.Minimap = Minimap;
})();

(function() {
    const Def = AGN.Lib.WM.Definitions;
    const Node = AGN.Lib.WM.Node;
    const Minimap = AGN.Lib.WM.Minimap;
    class Canvas {
        constructor($canvas) {
            const self = this;
            this.$canvas = $canvas;
            this.mouseWheelZoomEnabled = false;
            this.panningEnabled = false;
            this.zoomEventHandler = null;
            this.moveEventHandler = null;
            this.ignoreNextZoomEvent = false;
            this.minimap = new Minimap(this, {
                containment: {
                    mode: "panner-box",
                    padding: 5
                },
                onPannerDrag: function(dX, dY) {
                    if (dX || dY) {
                        var position = self.getPosition();
                        self.moveTo(position.x + dX, position.y + dY);
                    }
                }
            });
            this.panzoom = panzoom($canvas[0], {
                minZoom: Def.MIN_ZOOM,
                maxZoom: Def.MAX_ZOOM,
                initialZoom: Def.DEFAULT_ZOOM,
                disableKeyboardInteraction: true,
                smoothScroll: false,
                onDoubleClick: () => false,
                beforeWheel: () => !self.mouseWheelZoomEnabled,
                beforeMouseDown: e => e.button !== Def.MOUSE_BUTTON_MIDDLE
            });
            this.panzoom.on("zoom", function() {
                if (self.zoomEventHandler) {
                    if (self.ignoreNextZoomEvent) {
                        self.ignoreNextZoomEvent = false;
                    } else {
                        self.zoomEventHandler.call(null, self.getZoom());
                        self.minimap.onPanZoom();
                    }
                }
            });
            this.panzoom.on("pan", function() {
                self.minimap.onPanZoom();
                if (self.moveEventHandler) {
                    self.moveEventHandler.call(null, self.getPosition());
                }
            });
        }
        get$() {
            return this.$canvas;
        }
        setMinimapEnabled(isEnabled) {
            this.minimap.setEnabled(isEnabled);
        }
        updateMinimap() {
            this.minimap.updateMinimap();
        }
        setPanningEnabled(isEnabled) {
            this.panningEnabled = !!isEnabled;
        }
        setMouseWheelZoomEnabled(isEnabled) {
            this.mouseWheelZoomEnabled = isEnabled;
        }
        getZoom() {
            var transform = this.panzoom.getTransform();
            return transform.scale;
        }
        getPosition() {
            var transform = this.panzoom.getTransform();
            return {
                x: transform.x,
                y: transform.y
            };
        }
        getVisibleArea() {
            var $viewport = this.$canvas.parent();
            var viewportWidth = $viewport.width();
            var viewportHeight = $viewport.height();
            var transform = this.panzoom.getTransform();
            return {
                minX: -transform.x / transform.scale,
                minY: -transform.y / transform.scale,
                maxX: (viewportWidth - transform.x) / transform.scale,
                maxY: (viewportHeight - transform.y) / transform.scale
            };
        }
        moveTo(x, y) {
            this.panzoom.moveTo(x, y);
        }
        setZoom(scale) {
            var transform = this.panzoom.getTransform();
            this.ignoreNextZoomEvent = true;
            this.panzoom.zoomAbs(transform.x, transform.y, scale);
            this.minimap.onPanZoom();
        }
        setOnZoom(handler) {
            this.zoomEventHandler = handler;
        }
        setOnMove(handler) {
            this.moveEventHandler = handler;
        }
        getCanvasParent$() {
            return this.get$().parent();
        }
        getIcons() {
            var icons = [];
            this.get$().children(".node").each(function(index, element) {
                icons.push($(element));
            });
            return icons;
        }
        getPureIconsBox() {
            var icons = this.getIcons();
            var zoom = this.getZoom();
            if (icons.length) {
                var box = icons.map(function($node) {
                    return Node.getBox($node);
                }).reduce(function(result, current, index) {
                    return {
                        minX: Math.min(result.minX, current.minX),
                        minY: Math.min(result.minY, current.minY),
                        maxX: Math.max(result.maxX, current.maxX),
                        maxY: Math.max(result.maxY, current.maxY)
                    };
                });
                return {
                    minX: box.minX / zoom - Def.CANVAS_GRID_SIZE,
                    minY: box.minY / zoom - Def.CANVAS_GRID_SIZE,
                    maxX: box.maxX / zoom + Def.CANVAS_GRID_SIZE,
                    maxY: box.maxY / zoom + Def.CANVAS_GRID_SIZE
                };
            } else {
                var $viewport = this.getCanvasParent$();
                return {
                    minX: -Def.CANVAS_GRID_SIZE,
                    minY: -Def.CANVAS_GRID_SIZE,
                    maxX: $viewport.width() / zoom + Def.CANVAS_GRID_SIZE,
                    maxY: $viewport.height() / zoom + Def.CANVAS_GRID_SIZE
                };
            }
        }
        fitPdfPage(size, orientation) {
            var box = this.getPureIconsBox();
            var width = box.maxX - box.minX + Def.NODE_MIN_MARGIN;
            var height = box.maxY - box.minY + Def.NODE_MIN_MARGIN;
            if (!Def.PAGE_DIMENSIONS[size]) {
                return;
            }
            var pageDimension = Def.PAGE_DIMENSIONS[size];
            var isLandscape = orientation == "landscape";
            var sceneWidth = isLandscape ? pageDimension.height : pageDimension.width;
            var sceneHeight = isLandscape ? pageDimension.width : pageDimension.height;
            var transformX = 0;
            var transformY = 0;
            var scale = 1;
            if (width > sceneWidth || height > sceneHeight) {
                if (width / height < sceneWidth / sceneHeight) {
                    scale = sceneHeight / height;
                } else {
                    scale = sceneWidth / width;
                }
            }
            if (box.minX < 0) {
                transformX = -box.minX * scale;
            }
            if (box.minY < 0) {
                transformY = -box.minY * scale;
            }
            var transformCss = "matrix(" + scale + ", 0, 0, " + scale + ", " + transformX + ", " + transformY + ")";
            var transformOrigin = "left top 0";
            this.getCanvasParent$().css({
                transform: transformCss,
                "-webkit-transform": transformCss,
                "transform-origin": transformOrigin,
                "-webkit-transform-origin": transformOrigin,
                "backface-visibility": "hidden",
                "-webkit-backface-visibility": "hidden",
                overflow: "visible"
            });
        }
    }
    AGN.Lib.WM.Canvas = Canvas;
})();

