AGN.Lib.CoreInitializer.new("trackable-link-extensions", function($scope = $(document)) {
    class TrackableLinkExtensionsTable extends AGN.Lib.InputTable {
        constructor($container) {
            super($container);
        }
        get rowTemplate() {
            return `\n        <tr>\n            <td><input type="text" class="form-control" data-name="name" value="{{- name }}" placeholder="${t("defaults.name")}" ${this.readonly ? "disabled" : ""}></td>\n            <td><input type="text" class="form-control" data-name="value" value="{{- value }}" placeholder="${t("defaults.value")}" ${this.readonly ? "disabled" : ""}></td>\n        </tr>\n      `;
        }
        get headerTemplate() {
            return `\n        <tr>\n            <th>${t("defaults.name")}</th>\n            <th>${t("defaults.value")}</th>\n        </tr>\n      `;
        }
        addActions() {
            super.addActions();
            AGN.Lib.Action.new({
                click: "[data-delete-all-extensions]"
            }, this.clean.bind(this), this.$container);
            AGN.Lib.Action.new({
                click: "[data-add-default-extensions]"
            }, this.addDefaultExtensions.bind(this), this.$container);
        }
        addDefaultExtensions() {
            const $lastRow = this.$table.find("tbody tr:last");
            if (this.isEmptyRow$($lastRow)) {
                $lastRow.remove();
            }
            _.each(this.config.defaultExtensions, extension => this.addRow(extension));
            this.addEmptyRow();
        }
    }
    _.each($scope.find("[data-trackable-link-extensions]"), function(el) {
        new TrackableLinkExtensionsTable($(el));
    });
});

AGN.Lib.CoreInitializer.new("truncated-text-popover", function($scope = $(document)) {
    const Popover = AGN.Lib.Popover;
    const Helpers = AGN.Lib.Helpers;
    document.fonts.ready.then(() => {
        $scope.find(`\n      .text-truncate,\n      table:not(.input-table) td,\n      table:not(.input-table) th,\n      .ag-header-cell,\n      .select2-selection__rendered,\n      [data-truncated-text],\n      .dashboard-calendar__label--comment .text-truncate-lines\n      `).each((i, el) => showPopoverIfTruncated(el));
    });
    function showPopoverIfTruncated(el) {
        const $el = detectHoverEl$(el);
        const popover = Popover.get($el);
        if (containsTruncatedElement(el)) {
            if (!popover) {
                Popover.create($el, {
                    delay: {
                        show: 400,
                        hide: 50
                    },
                    content: $(Helpers.retrieveTextElement($el[0])).text()
                }).forTruncatedText = true;
            }
        } else if (popover?.forTruncatedText) {
            Popover.remove($el);
        }
    }
    function detectHoverEl$(el) {
        const $el = $(el);
        const $cell = $el.closest("td");
        return $cell.exists() ? $cell : $el;
    }
    function containsTruncatedElement(el) {
        let $el = $(el);
        if ($el.is(".text-truncate-alt")) {
            return $el.is(":truncatedAlt");
        }
        if ($el.is(".ag-header-cell")) {
            $el = $el.find(".ag-header-cell-text");
        }
        return $el.is(":truncated") || $el.is("td") && Helpers.containsTruncatedElements(el);
    }
});

