AGN.Lib.DomInitializer.new("workflow-pause-timer", function() {
    const WORKFLOW_ID = this.config.workflowId;
    const PAUSE_TIME_MS = this.config.pauseTime;
    const DEFAULT_EXPIRATION_HOURS = this.config.defaultExpirationHours;
    const EXPIRATION_HOURS = this.config.expirationHours > 0 ? this.config.expirationHours : DEFAULT_EXPIRATION_HOURS;
    const EXPIRATION_MS = EXPIRATION_HOURS * 60 * 60 * 1e3;
    const timeField = $("#workflow-pause-timer-text");
    const oneSecInterval = setInterval(function() {
        updateTimer();
    }, 1e3);
    updateTimer();
    function updateTimer() {
        timeField.html(getTimeStr());
    }
    function calculateTimeLeftMs() {
        return EXPIRATION_MS - (Date.now() - PAUSE_TIME_MS);
    }
    function getTimeStr() {
        const timeLeftMs = calculateTimeLeftMs();
        if (timeLeftMs <= 0) {
            if (oneSecInterval) {
                clearInterval(oneSecInterval);
            }
            autoUnpause();
            return '<i class="icon icon-refresh icon-spin"></i> ' + t("workflow.activating.auto");
        }
        const time = new Date(timeLeftMs);
        return formatTimeComponent(time.getUTCHours()) + ":" + formatTimeComponent(time.getUTCMinutes()) + ":" + formatTimeComponent(time.getUTCSeconds());
    }
    function formatTimeComponent(component) {
        return component > 0 ? component < 10 ? "0" + component : component : "00";
    }
    function autoUnpause() {
        return $.post(AGN.url(`/workflow/${WORKFLOW_ID}/autoUnpause.action`)).done(resp => {
            if (resp.success === true) {
                AGN.Lib.Page.reload(AGN.url(`/workflow/${WORKFLOW_ID}/view.action`));
            } else {
                AGN.Lib.JsonMessages(resp.popups);
            }
        });
    }
    return false;
});

(() => {
    const Loader = AGN.Lib.Loader, Page = AGN.Lib.Page, CSRF = AGN.Lib.CSRF;
    const AjaxLoader = {
        initialize: function(options) {
            if (options.loader === true || options.loader === undefined) {
                options.loader = {
                    show: () => Loader.show(),
                    hide: () => Loader.hide()
                };
            }
        },
        show: function(options) {
            const loader = options.loader;
            if (loader?.show) {
                try {
                    loader.show();
                } catch (e) {
                    console.error(e);
                }
            }
        },
        hide: function(options) {
            const loader = options.loader;
            if (loader?.hide) {
                try {
                    loader.hide();
                } catch (e) {
                    console.error(e);
                }
            }
        }
    };
    $.ajaxPrefilter(function(options) {
        AjaxLoader.initialize(options);
    });
    $(document).ajaxSend(function(e, jqxhr, options) {
        AjaxLoader.show(options);
        if (CSRF.isProtectionEnabled()) {
            CSRF.setTokenToReqHeader(jqxhr, options.type);
        }
    });
    $(document).ajaxComplete(function(e, jqxhr, options) {
        AjaxLoader.hide(options);
        CSRF.updateTokenInDOM();
    });
    $(document).ajaxError(function(e, jqxhr, options) {
        AjaxLoader.hide(options);
        if (jqxhr.readyState == 0 || jqxhr.status == 0) {
            return;
        }
        if (options.statusCode && jqxhr.status in options.statusCode) {
            return;
        }
        if (jqxhr.status === 401) {
            const event = $.Event("ajax:unauthorized");
            $(document).trigger(event);
            if (!event.isDefaultPrevented() && jqxhr.responseText) {
                Page.render(jqxhr.responseText);
            }
        } else if (jqxhr.status === 403) {
            if (jqxhr.responseText) {
                const $resp = $(jqxhr.responseText);
                const $csrfErrorMessage = $resp.filter("#csrf-error-message");
                if ($csrfErrorMessage.exists()) {
                    AGN.Lib.Modal.create(_.template($csrfErrorMessage.html())({}), {});
                    return;
                }
                if ($resp.all("script[data-message]").exists()) {
                    Page.render(jqxhr.responseText);
                    return;
                }
            }
            AGN.Lib.Modal.fromTemplate("permission-denied", {
                title: t("messages.permission.denied.title"),
                text: t("messages.permission.denied.text"),
                btn: t("defaults.ok")
            });
        } else {
            let isDefault = true;
            if (jqxhr.responseText) {
                try {
                    const json = JSON.parse(jqxhr.responseText);
                    if (json.popups) {
                        AGN.Lib.JsonMessages(json.popups, true);
                        isDefault = false;
                    }
                } catch (e) {
                    isDefault = true;
                }
                if (isDefault) {
                    try {
                        if ($(jqxhr.responseText).all("script[data-message]").exists()) {
                            Page.render(jqxhr.responseText);
                            isDefault = false;
                        }
                    } catch (e) {
                        isDefault = true;
                    }
                }
            }
            if (isDefault) {
                AGN.Lib.Modal.fromTemplate("error", {
                    headline: t("messages.error.headline"),
                    text: t("messages.error.text"),
                    reload: t("messages.error.reload")
                });
            }
        }
    });
    $(document).on("click", "a[data-ajax]", function(e) {
        const $e = $(this);
        e.preventDefault();
        Page.reload($e.attr("href"), true, $e.data("ajax"));
    });
    $(document).on("click", "[data-prevent-load]", function() {
        Loader.prevent();
    });
    window.onbeforeunload = function() {
        Loader.show();
    };
})();

(() => {
    const trapReadonlyInteractions = function(e) {
        const $target = $(e.target);
        const $checkbox = $target.is('input[type="checkbox"]') ? $target : $target.closest(".form-check").find('input[type="checkbox"]').first();
        if (!$checkbox[0]?.hasAttribute("readonly")) {
            return;
        }
        if (e.type === "click" || e.code === "Space" || e.key === " ") {
            e.preventDefault();
            e.stopPropagation();
        }
    };
    document.addEventListener("click", trapReadonlyInteractions, {
        capture: true
    });
    document.addEventListener("keydown", trapReadonlyInteractions, {
        capture: true
    });
})();

(() => {
    const Form = AGN.Lib.Form;
    const Confirm = AGN.Lib.Confirm;
    const Page = AGN.Lib.Page;
    const Helpers = AGN.Lib.Helpers;
    AGN.Lib.Action.new({
        click: "[data-confirm], .js-confirm"
    }, function() {
        $.get(this.el.attr("href")).done(resp => {
            const $modal = $(resp).all(".modal");
            if ($modal.length !== 1) {
                Page.render(resp);
                return;
            }
            Confirm.create(resp).done(resp => Page.render(resp));
        });
        this.event.preventDefault();
    });
    $(document).on("click", "[data-confirm-positive], .js-confirm-positive", function() {
        const $this = $(this);
        const confirm = Confirm.get($this);
        const $form = Form.getWrapper($this);
        if (confirm) {
            if ($form.exists()) {
                const form = Form.get($form);
                if ($this.is("[data-url]")) {
                    form.setActionOnce($this.data("url"));
                }
                if ($this.is("[data-form-set]")) {
                    const opts = Helpers.objFromString($this.data("form-set"));
                    _.forEach(opts, (value, field) => form.setValueOnce(field, value));
                }
                form.jqxhr().done(resp => confirm.positive(resp));
            } else {
                const $choice = confirm.$modal.find('[name="confirm-choice"]');
                if ($choice.exists()) {
                    confirm.positive($choice.val());
                } else {
                    confirm.positive($this.data("confirm-positive"));
                }
            }
        }
    });
    $(document).on("click", "[data-confirm-negative], .js-confirm-negative", function() {
        const $this = $(this);
        Confirm.get($this)?.negative($this.data("confirm-negative"));
    });
})();

(() => {
    const Tooltip = AGN.Lib.Tooltip;
    AGN.Lib.Action.new({
        click: "[data-copyable]"
    }, function() {
        let value = undefined;
        let $tooltipTarget = this.el;
        if (this.el.is("[data-copyable-value]")) {
            value = this.el.data("copyable-value");
        } else {
            const selector = this.el.data("copyable-target");
            const $target = selector ? $(selector) : this.el;
            if ($target.exists()) {
                value = $target.val() || $target.text();
                $tooltipTarget = $target;
            }
        }
        if (value !== undefined) {
            AGN.Lib.Clipboard.set(value, (v, success) => {
                if (success) {
                    const existingTooltip = Tooltip.get($tooltipTarget);
                    const copiedMsg = t("clipboard.copied.tooltip");
                    if (existingTooltip) {
                        Tooltip.setContent($tooltipTarget, copiedMsg);
                    } else {
                        Tooltip.create($tooltipTarget, {
                            title: copiedMsg,
                            trigger: "manual"
                        });
                    }
                    Tooltip.setShown($tooltipTarget);
                    const currentTimeoutId = this.el.data("tooltip-timeout-id");
                    if (currentTimeoutId) {
                        clearTimeout(currentTimeoutId);
                    }
                    const timeoutId = setTimeout(() => {
                        if (existingTooltip) {
                            Tooltip.restoreContent($tooltipTarget);
                            Tooltip.setShown($tooltipTarget, false);
                        } else {
                            Tooltip.remove($tooltipTarget);
                        }
                        this.el.removeData("tooltip-timeout-id");
                    }, 2500);
                    this.el.data("tooltip-timeout-id", timeoutId);
                }
            });
            this.event.stopPropagation();
        }
    });
})();

(() => {
    const Table = AGN.Lib.Table;
    const RenderMessages = AGN.Lib.RenderMessages;
    const WebStorage = AGN.Lib.WebStorage;
    const Confirm = AGN.Lib.Confirm;
    const RESTORE_ROW_SELECTOR = "[data-restore-row]";
    const BULK_RESTORE_ROWS_SELECTOR = '[data-bulk-action="restore"]';
    $(document).on("click", "[data-js-table-page]", function() {
        const $el = $(this);
        const page = $el.data("js-table-page");
        const api = Table.get($el).api;
        if (page === "first") {
            api.paginationGoToFirstPage();
        } else if (page === "prev") {
            api.paginationGoToPreviousPage();
        } else if (page === "next") {
            api.paginationGoToNextPage();
        } else if (page === "last") {
            api.paginationGoToLastPage();
        } else {
            api.paginationGoToPage(page);
        }
        api.deselectAll();
    });
    $(document).on("change", "[data-js-table] [data-number-of-rows]", function() {
        const $e = $(this);
        const pageSize = $e.val();
        Table.get($e).api.setGridOption("paginationPageSize", pageSize);
        const bundle = $e.closest(".table-wrapper").data("web-storage");
        if (bundle) {
            WebStorage.extend(bundle, {
                paginationPageSize: parseInt(pageSize)
            });
        }
    });
    $(window).on("viewportChanged", function() {
        $(document).all(".table-wrapper").each(function() {
            AGN.Lib.Table.get($(this))?.redraw();
        });
    });
    $(document).on("click", ".js-data-table-delete", function(e) {
        const $el = $(this);
        const table = Table.get($el);
        $.get($el.attr("href")).done(resp => {
            if ($(resp).all(".modal").exists()) {
                Confirm.create(resp).done(positiveResp => {
                    const row = table?.findRowByElement($el);
                    if (row) {
                        row.data.deleted = true;
                        row.data.active = "false";
                        table.api?.applyTransaction(isRestoreModeAvailable() ? {
                            update: [ row.data ]
                        } : {
                            remove: [ row.data ]
                        });
                        row.setSelected(false);
                    }
                    if (typeof positiveResp === "object") {
                        AGN.Lib.JsonMessages(positiveResp.popups, true);
                    } else {
                        RenderMessages($(positiveResp));
                    }
                });
            } else {
                AGN.Lib.Page.render(resp);
            }
        });
        e.preventDefault();
    });
    $(document).on("click", ".js-data-table-bulk-delete", e => deleteRows($(e.currentTarget)));
    $(document).on("click", `${BULK_RESTORE_ROWS_SELECTOR}, ${RESTORE_ROW_SELECTOR}`, e => restoreRows($(e.currentTarget)));
    function deleteRows($el) {
        hideRowsAfterAction($el, false);
    }
    function restoreRows($el) {
        hideRowsAfterAction($el, true);
    }
    function hideRowsAfterAction($el, restore) {
        const table = Table.get($el);
        const tableApi = table.api;
        const rows = $el.is(RESTORE_ROW_SELECTOR) ? [ table?.findRowByElement($el)?.data ] : tableApi.getSelectedRows();
        const ids = rows.map(row => row.id);
        requestAction(ids, $el.data("bulk-url"), restore ? "POST" : $el.data("method")).done(resp => {
            RenderMessages($(resp));
            removeRows(tableApi, rows, restore);
        });
    }
    function removeRows(tableApi, rows, restore) {
        rows.forEach(row => {
            row.active = "false";
            row.deleted = !restore;
            tableApi.getSelectedNodes().forEach(node => {
                if (node.data.id === row.id) {
                    node.setSelected(false);
                }
            });
        });
        tableApi.applyTransaction(isRestoreModeAvailable() ? {
            update: rows
        } : {
            remove: rows
        });
    }
    function isRestoreModeAvailable() {
        return $(BULK_RESTORE_ROWS_SELECTOR).exists();
    }
    function requestAction(bulkIds, url, method = "GET") {
        const deferred = $.Deferred();
        if (bulkIds && bulkIds.length) {
            const jqxhr = $.ajax(url, {
                method: method,
                traditional: true,
                data: {
                    bulkIds: bulkIds
                }
            }).fail(() => deferred.reject());
            Confirm.request(jqxhr).then(deferred.resolve, deferred.reject);
        } else {
            deferred.reject();
            AGN.Lib.Messages.alert("messages.error.nothing_selected");
        }
        return deferred.promise();
    }
})();

