(() => {
    const Messaging = AGN.Lib.Messaging;
    const inputKeys = [ "Enter", "Backspace", "Delete", "Tab" ];
    window.addEventListener("message", e => {
        if (e.data?.type === "scroll-transfer") {
            const editorId = e.data.wysiwygId;
            const iframe = Jodit.instances[editorId].iframe;
            const container = AGN.Lib.Scrollbar.get($(iframe))?.$el?.get(0);
            if (container) {
                container.scrollTop = container.scrollTop + e.data.deltaY;
            }
        }
    });
    $(document).on("tile:show", function(e) {
        const $target = $(e.target);
        const $editor = $target.find(".js-wysiwyg");
        if ($editor.length === 1) {
            const editorId = $editor.attr("id");
            const options = getEditorOptions($editor);
            const jodit = Jodit.make(`#${editorId}`, {
                theme: AGN.Lib.Helpers.isDarkTheme() ? "dark" : "default",
                editHTMLDocumentMode: options.isFullHtml,
                language: window.adminLocale?.split("-")[0] || "en",
                cleanHTML: {
                    denyTags: `${options.allowExternalScript ? "" : "script"}`
                },
                emmMailingId: options.browseMailingId || -1,
                emmToolbarType: options.toolbarType
            });
            if (options.isFullHtml) {
                $(jodit.editor).trigger("click");
                fixJoditEvents(jodit);
                setTimeout(() => {
                    jodit.e.on("keyup", e => {
                        if (e.key.length === 1 || inputKeys.includes(e.key)) {
                            jodit.userInputHappened = true;
                        }
                    });
                    Messaging.send("html-version-wysiwyg-shown");
                }, 100);
            }
            addTransferScrollBehavior(jodit.iframe, jodit.id);
            Messaging.send("wysiwyg-shown");
        }
    });
    $(document).on("tile:hide modal:close", function(e) {
        $(e.target).find(".js-wysiwyg").each(function() {
            const $textArea = $(this);
            const jodit = Jodit.instances[$textArea.attr("id")];
            if (jodit?.options.editHTMLDocumentMode) {
                jodit.e.fire("outsideClick");
                jodit.synchronizeValues();
            }
            jodit?.destruct();
            AGN.Lib.Editor.get($textArea).val($textArea.val());
        });
    });
    $(document).on("form:submit", function(e) {
        const $editor = $(e.target).find(".js-wysiwyg");
        if ($editor.exists()) {
            if (window.Jodit) {
                Object.values(Jodit.instances).forEach(editor => editor.destruct());
            } else if (window.removeAllEditors) {
                window.removeAllEditors();
            }
        }
    });
    const getEditorOptions = $editor => {
        const options = {};
        if (window.Jodit) {
            options.isFullHtml = false;
        } else {
            options.isFullHtml = !!$editor.data("full-tags");
            options.height = $editor.height();
            options.width = "100%";
        }
        options.allowExternalScript = false;
        options.browseMailingId = getMailingId($editor);
        return _.extend(options, AGN.Lib.Helpers.objFromString($editor.data("editor-options")));
    };
    function getMailingId($editor) {
        const formId = $editor.data("form-target");
        const $form = !!formId ? $(formId) : null;
        if (!$form || !$form.exists()) {
            return null;
        }
        const form = AGN.Lib.Form.get($form);
        let mailingId = form.getValue("mailingID");
        if (!mailingId) {
            mailingId = form.getValue("mailingId");
        }
        return mailingId;
    }
    function fixJoditEvents(jodit) {
        const doc = jodit.iframe.contentWindow.document;
        if (jodit.iframe.contentWindow.document.documentElement) {
            jodit.e.on(doc.documentElement, "mousedown touchend", () => {
                if (!jodit.s.isFocused()) {
                    jodit.s.focus();
                    if (jodit.editor === doc.body) {
                        jodit.s.setCursorIn(doc.body);
                    }
                }
            }).on(jodit.ew, "mousedown touchstart keydown keyup touchend click mouseup mousemove scroll", e => {
                jodit.events?.fire(jodit.ow, e);
            });
        }
    }
    function addTransferScrollBehavior(iframe, wysiwygId) {
        if (!iframe) {
            return;
        }
        const iframeWindow = iframe.contentWindow;
        const iframeDocument = iframe.contentDocument || iframeWindow.document;
        iframeWindow.addEventListener("wheel", e => {
            const atTop = iframeWindow.scrollY <= 0;
            const atBottom = iframeWindow.scrollY + iframeWindow.innerHeight >= iframeDocument.body.scrollHeight;
            if (atTop && e.deltaY < 0 || atBottom && e.deltaY > 0) {
                window.parent.postMessage({
                    type: "scroll-transfer",
                    deltaY: e.deltaY,
                    wysiwygId: wysiwygId
                }, "*");
                e.preventDefault();
            }
        }, {
            passive: false
        });
    }
})();

AGN.Lib.Validator.new("action", {
    valid: function($e, options, isFieldsValid) {
        return isFieldsValid && !this.errors($e, options).length;
    },
    errors: function($e, options) {
        const errors = [];
        if ($("#serviceMailOperation").length) this.validateSendServiceOperation(errors);
        return errors;
    },
    validateSendServiceOperation: function(errors) {
        validateEmailList($("input[id$=toAddress]"), errors, "triggerManager.operation.serviceMail.error.recipientAddress");
        validateEmail($("input[id$=fromAddress]"), errors, "triggerManager.operation.serviceMail.error.senderAddress");
        validateEmail($("input[id$=replyAddress]"), errors, "triggerManager.operation.serviceMail.error.replyAddress");
        validateSubject($("input[id$=subjectLine]"), errors);
    }
});

function validateEmailList($fields, errors, errorCode) {
    $fields.each(function(i, field) {
        const $field = $(field);
        const emails = getEmailsFromField($field);
        if (!emails || !AGN.Lib.Helpers.isValidEmails(emails)) {
            errors.push({
                field: $field,
                msg: t(errorCode)
            });
        } else {
            $field.val(emails.join(","));
        }
    });
}

function validateEmail($fields, errors, errorCode) {
    $fields.each(function(i, field) {
        const $field = $(field);
        const value = $field.val().trim();
        if (!AGN.Lib.Helpers.isValidEmail(value)) {
            errors.push({
                field: $field,
                msg: t(errorCode)
            });
        } else {
            $field.val(value);
        }
    });
}

function validateSubject($fields, errors) {
    $fields.each(function(i, field) {
        const $field = $(field);
        const value = $field.val().trim();
        if (!value || value.length < 3) {
            errors.push({
                field: $field,
                msg: t("triggerManager.operation.serviceMail.error.subjectToShort")
            });
        } else if (value && value.length > 200) {
            errors.push({
                field: $field,
                msg: t("triggerManager.operation.serviceMail.error.subjectToLong")
            });
        } else {
            $field.val(value);
        }
    });
}

function getEmailsFromField($field) {
    const value = $field.val();
    let emails = value.trim() && value.trim().split(/[ ,|]+/);
    _.map(emails, _.trim);
    return emails;
}

AGN.Lib.Validator.new("email-validator", {
    valid: function($e, options) {
        return !this.errors($e, options).length;
    },
    errors: function($e, options) {
        const emails = $e.is("select[multiple]") ? $e.val() : $e.val().split(",");
        if (!emails.length && options.required) {
            return [ {
                field: $e,
                msg: t("fields.required.errors.missing")
            } ];
        }
        if (AGN.Lib.Helpers.isValidEmails(emails)) {
            return [];
        }
        return [ {
            field: $e,
            msg: t("defaults.invalidEmail")
        } ];
    }
});

(() => {
    AGN.Lib.Validator.new("export/form", {
        valid: function($e, options) {
            return !this.errors($e, options).length;
        },
        errors: function($e, options) {
            const errors = [];
            validateColumnMappings(errors);
            return errors;
        }
    });
    function validateColumnMappings(errors) {
        const allCustomColumnNames = [];
        _.each($("#custom-column-mappings tbody").find("tr"), row => {
            const $row = $(row);
            const $columnNameField = $row.find('[data-name="dbColumn"]');
            const name = getColumnName($columnNameField);
            checkColumnNameValid($row, $columnNameField, errors);
            checkColumnNameUnique(name, allCustomColumnNames, errors, $columnNameField);
            allCustomColumnNames.push(name.toLowerCase());
        });
    }
    function checkColumnNameValid($row, $columnNameField, errors) {
        const name = getColumnName($columnNameField);
        const isLastRow = $row.is(":last-child");
        if (!isLastRow && name.length === 0) {
            errors.push({
                field: $columnNameField,
                msg: t("export.columnMapping.error.nameEmpty")
            });
            return;
        }
        if (!isLastRow && name.length < 3 || isLastRow && name && name.length < 3) {
            errors.push({
                field: $columnNameField,
                msg: t("export.columnMapping.error.nameTooShort")
            });
            return;
        }
        if (!isLastRow && !/^[a-zA-Z0-9_]{3,}$/.test(name) || isLastRow && name && !/^[a-zA-Z0-9_]{3,}$/.test(name)) {
            errors.push({
                field: $columnNameField,
                msg: t("export.columnMapping.error.invalidColName")
            });
        }
    }
    function checkColumnNameUnique(name, allCustomColumnNames, errors, $columnNameField) {
        if (name && allCustomColumnNames.indexOf(name.toLowerCase()) >= 0) {
            errors.push({
                field: $columnNameField,
                msg: t("export.columnMapping.error.duplicate")
            });
        }
        if (getProfileFieldColumnNames().indexOf(name.toLowerCase()) >= 0) {
            errors.push({
                field: $columnNameField,
                msg: t("export.columnMapping.error.exist")
            });
        }
    }
    function getColumnName($row) {
        return $row.val().trim();
    }
    function getProfileFieldColumnNames() {
        return $.map($('select[name="userColumns"] option'), function(option) {
            return option.value.toLowerCase();
        });
    }
})();

(() => {
    AGN.Lib.Validator.new("import-profile-mappings/form", {
        valid: function($e, options) {
            return !this.errors($e, options).length;
        },
        errors: function($e, options) {
            return validateDefaultValues(options.columns, options.doNotImportValue, options.$mappingsBlock);
        }
    });
    function isValidDataLength(columnInfo, value) {
        return value.length <= getMaxColumnLength(columnInfo);
    }
    function getMaxColumnLength(columnInfo) {
        const dataType = columnInfo.simpleDataType.toLowerCase();
        if (dataType === "float" || dataType === "numeric") {
            return columnInfo.numericPrecision + columnInfo.numericScale;
        }
        return columnInfo.characterLength;
    }
    function getDefValFieldValue($defValField) {
        let value = $defValField.val();
        if (value[0] == "'" && value[value.length - 1] == "'") {
            value = value.substring(1, value.length - 1);
        }
        return value;
    }
    function validateDefValField($defValField, columns, doNotImportValue, errors) {
        const value = getDefValFieldValue($defValField);
        if (!value) {
            return;
        }
        const columnName = getColNameByDefValField($defValField);
        if (columnName === doNotImportValue) {
            return;
        }
        const columnInfo = columns[columnName];
        const dataType = columnInfo.simpleDataType.toLowerCase();
        if (columnName === "email" && !AGN.Lib.Helpers.isValidEmail(value)) {
            errors.push({
                field: $defValField,
                msg: t("import.columnMapping.error.invalidEmail")
            });
        } else if (dataType === "date" || dataType === "datetime") {
            if (isDbDateFunction($defValField.val().trim())) {
                return;
            }
            validateDateOrDateTimeValue(dataType, value, errors, $defValField);
        } else if (!isValidValueForDataType(dataType, value)) {
            errors.push({
                field: $defValField,
                msg: t("import.columnMapping.error.type", dataType)
            });
        } else if (!isValidDataLength(columnInfo, value)) {
            errors.push({
                field: $defValField,
                msg: t("import.columnMapping.error.length", getMaxColumnLength(columnInfo))
            });
        }
    }
    function validateDateOrDateTimeValue(dataType, value, errors, $defValField) {
        if (!value || !isValidValueForDataType(dataType, value)) {
            errors.push({
                field: $defValField,
                msg: t("import.columnMapping.error.dateFormat", dataType === "datetime" ? window.adminDateFormat + " hh:mm" : window.adminDateFormat)
            });
        }
    }
    function validateDefaultValues(columns, doNotImportValue, $mappingsBlock) {
        const errors = [];
        _.each($mappingsBlock.find("[data-mapping-defaultValue]"), defValueField => {
            const $defValueField = $(defValueField);
            const $row = $defValueField.closest("[data-mapping-row]");
            if (!$row.is("[data-mapping-new]") || getColNameByDefValField($defValueField) !== doNotImportValue && !isCurrentTimeChecked()) {
                validateDefValField($defValueField, columns, doNotImportValue, errors);
            }
        });
        return errors;
    }
    function getColNameByDefValField($defValField) {
        return $defValField.closest("[data-mapping-row]").find("[data-mapping-db-column]").first().val();
    }
    function isValidValueForDataType(dataType, value) {
        switch (dataType) {
          case "numeric":
          case "float":
          case "double":
            return isNumeric(value);

          case "integer":
            return isInteger(value);

          case "date":
            return isValidDate(value);

          case "datetime":
            return isValidDateTime(value);

          default:
            return true;
        }
    }
    function isDbDateFunction(val) {
        return /^(now|now\(\)|sysdate|sysdate\(\)|current_timestamp|current_timestamp\(\)|today)\s*([+\-]\s*\d+\s*)?$/im.test(val);
    }
    function isValidDate(value) {
        return moment(value, window.adminDateFormat.toUpperCase(), true).isValid();
    }
    function isValidDateTime(value) {
        const dateAndTime = value.split(" ");
        return isValidDate(dateAndTime[0]) && /^(0[0-9]|1[0-9]|2[0-3]):[0-5][0-9]$/.test(dateAndTime[1]);
    }
    function isNumeric(n) {
        return !isNaN(parseFloat(n)) && isFinite(n);
    }
    function isInteger(value) {
        return /^-?\d+$/.test(value);
    }
    function isCurrentTimeChecked() {
        const currentTimeCheckbox = $("[data-action=set-today-date]");
        return currentTimeCheckbox.exists() && currentTimeCheckbox.is(":checked");
    }
})();

AGN.Lib.Validator.new("length", {
    valid: function($e, options) {
        return !this.errors($e, options).length;
    },
    errors: function($e, options) {
        var content = $e.val();
        var errors = [];
        if (content) {
            if (options.min >= 0 && content.length < options.min) {
                errors.push({
                    field: $e,
                    msg: t("fields.errors.string_exceed_min_length", options.min)
                });
            } else if (options.max >= 0 && content.length > options.max) {
                errors.push({
                    field: $e,
                    msg: t("fields.errors.string_exceed_max_length", options.max)
                });
            }
        } else if (options.min > 0 || options.required === true) {
            errors.push({
                field: $e,
                msg: t("fields.required.errors.missing")
            });
        }
        return errors;
    }
});

