(function() {
    AGN.Lib.Validator.new("number", {
        valid: function($e, options) {
            return !this.errors($e, options).length;
        },
        errors: function($e, options) {
            var errors = [];
            if (options.excludeHidden && $e.is(":hidden")) {
                return [];
            }
            var exactValue = $e.val();
            if (exactValue) {
                var value = options.float === true ? parseFloat(exactValue) : parseInt(exactValue);
                if (isNaN(value)) {
                    errors.push({
                        field: $e,
                        msg: t("fields.errors.number_nan")
                    });
                } else {
                    if (value < options.min) {
                        errors.push({
                            field: $e,
                            msg: t("fields.errors.number_exceed_min", options.min - 1)
                        });
                    } else if (value > options.max) {
                        errors.push({
                            field: $e,
                            msg: t("fields.errors.number_exceed_max", options.max)
                        });
                    } else if (options.strict === true) {
                        if ($.trim(exactValue) !== value.toString()) {
                            if (options.float === true) {
                                errors.push({
                                    field: $e,
                                    msg: t("fields.errors.number_not_double")
                                });
                            } else {
                                errors.push({
                                    field: $e,
                                    msg: t("fields.errors.number_not_integer")
                                });
                            }
                        }
                    }
                }
            } else if (options.required === true) {
                errors.push({
                    field: $e,
                    msg: t("fields.required.errors.missing")
                });
            }
            return errors;
        }
    });
})();

AGN.Lib.Validator.new("phone-number", {
    valid: function($e, options) {
        return !this.errors($e, options).length;
    },
    errors: function($e, options) {
        var content = $.trim($e.val());
        var errors = [];
        var TOKEN_BEGIN = 0;
        var TOKEN_PLUS = 1;
        var TOKEN_DIGIT = 3;
        var TOKEN_SEPARATOR = 4;
        var TOKEN_LPAREN = 5;
        var TOKEN_RPAREN = 6;
        if (content) {
            var previousToken = TOKEN_BEGIN;
            var hasViolations = false;
            var insideParentheses = false;
            var digitsCount = 0;
            for (var i = 0; i < content.length; i++) {
                var c = content.charAt(i);
                if (c >= "0" && c <= "9") {
                    digitsCount++;
                    previousToken = TOKEN_DIGIT;
                } else if (c == "." || c == "-" || c == "/") {
                    if (previousToken == TOKEN_DIGIT || previousToken == TOKEN_RPAREN) {
                        previousToken = TOKEN_SEPARATOR;
                    } else {
                        hasViolations = true;
                        break;
                    }
                } else if (c == "(") {
                    if (insideParentheses) {
                        hasViolations = true;
                        break;
                    }
                    previousToken = TOKEN_LPAREN;
                    insideParentheses = true;
                } else if (c == ")") {
                    if (previousToken == TOKEN_DIGIT && insideParentheses) {
                        previousToken = TOKEN_RPAREN;
                        insideParentheses = false;
                    } else {
                        hasViolations = true;
                        break;
                    }
                } else if (c == "+") {
                    if (previousToken == TOKEN_BEGIN) {
                        previousToken = TOKEN_PLUS;
                    } else {
                        hasViolations = true;
                        break;
                    }
                } else if (!/\s/.test(c)) {
                    hasViolations = true;
                    break;
                }
            }
            if (hasViolations || insideParentheses || digitsCount < 3 || digitsCount > 20) {
                errors.push({
                    field: $e,
                    msg: t("fields.errors.phone_number_invalid")
                });
            }
        } else if (options.required === true) {
            errors.push({
                field: $e,
                msg: t("fields.required.errors.missing")
            });
        }
        return errors;
    }
});

(function() {
    AGN.Lib.Validator.new("reference-table/form", {
        valid: function($e, options) {
            return !this.errors($e, options).length;
        },
        errors: function($e, options) {
            var errors = [];
            var $name = $('[name="shortname"]');
            var $keyColumn = $('[name="keyColumn"]');
            if ($name.length) validateTextField($name, errors, 5, options.isVoucher ? 27 : 29, new RegExp("^[a-z]*$", "i"), "referenceTables.table.error.name");
            if ($keyColumn.length) validateTextField($keyColumn, errors, 3, 30, /^(?![0-9_])[a-z0-9_]*$/, "referenceTables.table.error.keyColumn");
            return errors;
        }
    });
    function validateTextField($field, errors, minLength, maxLength, regex, errorMessage) {
        if (!validateFieldLength($field, errors, minLength, maxLength)) {
            return;
        }
        validateFieldPattern($field, errors, regex, errorMessage);
    }
    function validateFieldLength($field, errors, min, max) {
        var lengthErrors = AGN.Lib.Validator.get("length").errors($field, {
            min: min,
            max: max,
            required: true
        });
        if (lengthErrors.length) {
            lengthErrors.forEach(function(error) {
                errors.push(error);
            });
            return false;
        }
        return true;
    }
    function validateFieldPattern($field, errors, regex, errorMessage) {
        if (!$field.val().match(regex)) {
            errors.push({
                field: $field,
                msg: t(errorMessage)
            });
        }
    }
})();

(() => {
    AGN.Lib.Validator.new("reject-not-allowed-chars", {
        valid: function($e, options) {
            return !this.errors($e, options).length;
        },
        errors: function($e, options) {
            const chars = typeof options.chars === "string" ? $(options.chars).json().chars : options.chars;
            const disallowedChars = findDisallowedChars($e.val(), chars);
            if (!disallowedChars.length) {
                return [];
            }
            return [ {
                field: $e,
                msg: t(options.msgKey, disallowedChars.map(char => `'${char}'`).join(", "))
            } ];
        }
    });
    function findDisallowedChars(content, allowedChars) {
        const disallowedChars = [];
        const chars = new Set(allowedChars);
        for (let char of content) {
            if (!chars.has(char) && !disallowedChars.includes(char)) {
                disallowedChars.push(char);
            }
        }
        return disallowedChars;
    }
})();

AGN.Lib.Validator.new("reject-script-element", {
    valid: function($e, options) {
        return !this.errors($e, options).length;
    },
    errors: function($e, options) {
        var errors = [];
        var doc = (new DOMParser).parseFromString($e.val(), "text/html");
        var scripts = doc.querySelectorAll("script");
        Array.from(scripts).some(function(script) {
            var attrs = Array.from(script.attributes);
            var type = (script.getAttribute("type") || "").toLowerCase().trim();
            if (type !== "application/ld+json") {
                errors.push({
                    field: $e,
                    msg: t("fields.errors.illegal_script_type")
                });
                return true;
            }
            return false;
        });
        return errors;
    }
});

