AGN.Lib.Validator.new("unique-mobile-base", {
    valid: function($e, options) {
        return !this.errors($e, options).length;
    },
    errors: function($e, options) {
        var value = AGN.Lib.Select.get($e).getSelectedValue();
        var id = $e.attr("id");
        var errors = [];
        if (!this.isUniqueMobileBase(value, id)) {
            errors.push({
                field: $e,
                msg: t("fields.mediapool.errors.mobile_base_duplicate")
            });
        }
        return errors;
    },
    isUniqueMobileBase: function(value, excludeId) {
        if (value == "") {
            return true;
        }
        var duplicates = $("[id^=image-mobile-base]:not(#" + excludeId + ")").filter(function() {
            var $elem = $(this);
            return AGN.Lib.Select.get($elem).getSelectedValue() === value;
        });
        return duplicates.length === 0;
    }
});

AGN.Lib.Validator.new("upload-file/form", {
    valid: function(uploadForm, options, isFieldsValid) {
        let isSuccessfully = true;
        const $form = uploadForm.get$();
        if ($form.data("upload-selection").length < 1) {
            AGN.Lib.Messages.alert("error.upload.file");
            isSuccessfully = false;
        }
        return isFieldsValid && isSuccessfully && !this.errors(uploadForm, options).length;
    },
    errors: function(uploadForm, options) {
        const NAME_TOO_SHORT_MSG_KEY = "error.workflow.shortName";
        const REQUIRED_MSG_KEY = "fields.required.errors.missing";
        var validationRules = [ {
            field: $("#lastname"),
            minLength: {
                val: 3,
                msgKey: NAME_TOO_SHORT_MSG_KEY
            },
            maxLength: 99
        }, {
            field: $("#firstname"),
            minLength: {
                val: 3,
                msgKey: NAME_TOO_SHORT_MSG_KEY
            },
            maxLength: 99
        }, {
            field: $("#phone"),
            minLength: {
                val: 1,
                msgKey: REQUIRED_MSG_KEY
            },
            maxLength: 99
        }, {
            field: $("#contact-email"),
            maxLength: 99,
            regexpRules: [ {
                regexp: /\S+@\S+\.\S{2,}/,
                message: t("error.upload.email")
            } ]
        } ];
        var errors = [];
        validationRules.forEach(function(rule) {
            var field = rule.field;
            var value = field.val();
            if (!value || value.length < 1) {
                errors.push({
                    field: field,
                    msg: t(REQUIRED_MSG_KEY)
                });
                return;
            }
            if (rule.minLength && value.length < rule.minLength.val) {
                errors.push({
                    field: field,
                    msg: t(rule.minLength.msgKey)
                });
                return;
            }
            if (rule.maxLength && value.length > rule.maxLength) {
                errors.push({
                    field: field,
                    msg: t("fields.errors.contentLengthExceedsLimit", rule.maxLength)
                });
                return;
            }
            if (rule.regexpRules && rule.regexpRules.length > 0) {
                for (var i = 0; i < rule.regexpRules.length; ++i) {
                    var regexpRule = rule.regexpRules[i];
                    if (!value.match(regexpRule.regexp)) {
                        errors.push({
                            field: field,
                            msg: regexpRule.message
                        });
                        return;
                    }
                }
            }
        });
        return errors;
    }
});

AGN.Lib.Validator.new("userform-edit/form", {
    valid: function($e, options) {
        return !this.errors($e, options).length;
    },
    errors: function($e, options) {
        var errors = [];
        var formName = $('[name="formName"]');
        if (!formName.val().match(/^[a-zA-Z0-9-_]+$/gi)) {
            errors.push({
                field: formName,
                msg: t("userform.error.invalid_name")
            });
        }
        this.validateUrlField(errors, "success");
        this.validateUrlField(errors, "error");
        this.validateTemplateField(errors, $("#successTemplate"), "SUCCESS");
        this.validateTemplateField(errors, $("#errorTemplate"), "ERROR");
        return errors;
    },
    validateUrlField(errors, type) {
        const $url = $(`#${type}URL`);
        if ($(`[name="${type}Settings.useUrl"]`).prop("checked") && !AGN.Lib.Helpers.isUrl($url.val())) {
            errors.push({
                field: $url,
                msg: t(`userform.error.invalid_${type}Url`)
            });
        }
    },
    validateTemplateField: function(errors, field, typeUpperCase) {
        const type = typeUpperCase.toLowerCase();
        if (!$(`[name="${type}Settings.useUrl"]`).prop("checked") && !field.val().trim()) {
            errors.push({
                field: $(`#${type}-form-editor .tile-body`),
                msg: t(`userform.error.invalid_${type}Html`)
            });
        }
        if (!this.validateDirectives(errors, field)) {
            return false;
        }
        if (!this.validateHrefPattern(errors, field, typeUpperCase)) {
            return false;
        }
    },
    validateDirectives: function(errors, field) {
        var res = field.val().match(/#(?:include|parse)/gi);
        if (res) {
            errors.push({
                field: field,
                msg: t("userform.error.illegal_directive", res.join(", "))
            });
            return false;
        }
        return true;
    },
    validateHrefPattern: function(errors, field, type) {
        var value = field.val();
        var res = value.search(/\shref\s*=\s*(["'])\s/gi);
        if (res != -1) {
            var lineNumber = value.slice(0, res).match(/\r?\n/g).length + 1;
            errors.push({
                field: field,
                msg: t("userform.error.invalid_link", type, lineNumber)
            });
            return false;
        }
        return true;
    }
});

