(() => {
    const mailingSettingsView = AGN.url("/mailing/:mailingId:/settings.action");
    const mailingStatView = AGN.url("/statistics/mailing/:mailingId:/view.action?init=true");
    class CalendarBase {
        constructor($el, conf) {
            this.$el = $el;
            this.config = conf;
            this.firstDayOfWeek = conf.firstDayOfWeek;
            this.statisticsViewAllowed = conf.statisticsViewAllowed;
            this.$el.data("calendar", this);
        }
        get $year() {}
        get $month() {}
        get removeCurrentCalendar() {
            throw this.notImplementedError("removeCurrentCalendar()");
        }
        isToday(date) {
            return moment(date).isSame(moment(), "day");
        }
        showMonth(month, year) {
            this.removeCurrentCalendar();
            const monthDaysCount = this.daysInMonth(month + 1, year);
            let date = new Date(year, month, 1);
            let offset = date.getDay() - this.firstDayOfWeek;
            if (offset < 0) {
                offset = 7 + offset;
            }
            const weeksCount = Math.ceil((monthDaysCount + offset) / 7);
            const startDate = new Date(year, month, 1 - offset);
            const endDate = new Date(year, month, 1 + weeksCount * 7);
            date = new Date(startDate);
            for (let weekIndex = 0; weekIndex < weeksCount; weekIndex++) {
                const trId = "row-" + (weekIndex + 1);
                this.addWeekNumber(date, trId);
                for (let index = 0; index < 7; index++) {
                    const alien = date.getMonth() !== month;
                    this.addDay(date, alien, trId);
                    date.setDate(date.getDate() + 1);
                }
            }
            const startDateStr = this.dateToServiceFormat(startDate);
            const endDateStr = this.dateToServiceFormat(endDate);
            this.fillCalendar(startDateStr, endDateStr);
            this.synchronizeMonthsList(month, year);
        }
        addWeekNumber() {
            throw this.notImplementedError("addWeekNumber()");
        }
        addDay() {
            throw this.notImplementedError("addDay()");
        }
        fillCalendar() {
            throw this.notImplementedError("fillCalendar()");
        }
        notImplementedError(funcName) {
            return new Error(`${funcName} must be implemented in extended class`);
        }
        getMailingLink(mailing) {
            return mailing.status === "mailing.status.sent" && mailing.status !== "mailing.status.test" && this.statisticsViewAllowed ? mailingStatView.replace(":mailingId:", mailing.id) : mailingSettingsView.replace(":mailingId:", mailing.id);
        }
        addYearOption() {
            const $yearSelect = $("#month_list_year");
            const nextYear = parseInt($yearSelect.find("option:last").val(), 10) + 1;
            $yearSelect.append($("<option></option>").val(nextYear).text(nextYear));
        }
        lastYearSelected() {
            return $("#month_list_year option:selected").index() === $("#month_list_year option").length - 1;
        }
        daysInMonth(month, year) {
            return new Date(year, month, 0).getDate();
        }
        synchronizeMonthsList(month, year) {
            this.$year[0].selectedIndex = this.$year.find(`option[value=${year}]`)[0].index;
            this.$month[0].selectedIndex = this.$month.find(`option[value=${month}]`)[0].index;
            AGN.runAll(this.$year);
            AGN.runAll(this.$month);
        }
        static pad(num, size) {
            let s = num + "";
            while (s.length < size) s = "0" + s;
            return s;
        }
        dateToServiceFormat(date) {
            let dd = CalendarBase.pad(date.getDate(), 2);
            let mm = CalendarBase.pad(date.getMonth() + 1, 2);
            let yyyy = date.getFullYear();
            return dd + "-" + mm + "-" + yyyy;
        }
        getWeek(date) {
            var target = new Date(date.valueOf());
            var year = target.getFullYear();
            var month = target.getMonth();
            var day = target.getDate();
            if (this.firstDayOfWeek === 0) {
                day = day + 1;
            }
            month = month + 1;
            var a = Math.floor((14 - month) / 12);
            var y = year + 4800 - a;
            var m = month + 12 * a - 3;
            var J = day + Math.floor((153 * m + 2) / 5) + 365 * y + Math.floor(y / 4) - Math.floor(y / 100) + Math.floor(y / 400) - 32045;
            var d4 = (J + 31741 - J % 7) % 146097 % 36524 % 1461;
            var L = Math.floor(d4 / 1460);
            var d1 = (d4 - L) % 365 + L;
            return Math.floor(d1 / 7) + 1;
        }
    }
    AGN.Lib.Dashboard.CalendarBase = CalendarBase;
})();

(() => {
    const DateFormat = AGN.Lib.DateFormat;
    const Template = AGN.Lib.Template;
    const CalendarBase = AGN.Lib.Dashboard.CalendarBase;
    const Def = AGN.Lib.Dashboard.Def;
    const monthMailingsUrl = AGN.url("/calendar/light/mailings.action");
    const mailingsPopoverInfoUrl = AGN.url("/calendar/mailingsPopoverInfo.action");
    class CalendarLight extends CalendarBase {
        constructor($el, conf) {
            super($el, conf);
            this.$el = $el;
            this.firstDayOfWeek = conf.firstDayOfWeek;
            this.statisticsViewAllowed = conf.statisticsViewAllowed;
            this.#init();
        }
        get $month() {
            return $("#month_list");
        }
        get $year() {
            return $("#month_list_year");
        }
        #init() {
            const now = new Date;
            this.#displayWeekDays();
            this.showMonth(now.getMonth(), now.getFullYear());
            this.$el.on("change", "#month_list, #month_list_year", this.switchMonth.bind(this));
        }
        #displayWeekDays() {
            AGN.Lib.DateFormat.getLocalizedShortWeekdays(window.adminLocale, this.firstDayOfWeek).forEach(weekDay => {
                $("#calendar-header").append(`<td><div class="calendar-cell">${weekDay}</div></td>`);
            });
        }
        addWeekNumber(date, trId) {
            const weekNumber = this.getWeek(date);
            $("#calendar-container").append(`<tr id="${trId}"><td><div class="calendar-cell">${weekNumber}</div></td></tr>`);
        }
        addDay(date, alienMonth, trId) {
            const today = !alienMonth && this.isToday(date);
            const dateStr = this.dateToServiceFormat(new Date(date.getFullYear(), date.getMonth(), date.getDate()));
            const newId = "day-" + dateStr;
            $("#" + trId).append(`<td id="${newId}"></td>`);
            $("#" + newId).append(`<div class="calendar-cell calendar-day ${today ? "calendar-day--today" : ""} ${alienMonth ? "calendar-day--alien" : ""}" id="label-${newId}" data-date="${dateStr}">${date.getDate().toString().padStart(2, "0")}</div>`);
        }
        fillCalendar(startDate, endDate) {
            $.get(monthMailingsUrl, {
                start: startDate,
                end: endDate
            }).done(data => this.assignMailingsToCalendarDays(data));
        }
        removeCurrentCalendar() {
            $("#calendar-container tr:not(:first)").remove();
        }
        assignMailingsToCalendarDays(mailings) {
            mailings.forEach(mailing => {
                const mailingSendDate = moment(mailing.sendDate).tz(window.agnTimeZoneId);
                mailing.sendDate = mailingSendDate.format(Def.DATE_FORMAT);
                mailing.sendTime = mailingSendDate.format(Def.TIME_FORMAT);
                mailing.link = this.getMailingLink(mailing);
            });
            const mailingsByDays = _.groupBy(mailings, "sendDate");
            this.makeDaysSelectable(mailingsByDays);
            this.makeCurrentDayActive(mailingsByDays);
        }
        makeCurrentDayActive(mailingsBySendDate) {
            const currentDateStr = this.dateToServiceFormat(new Date);
            this.changeSelectedDay(currentDateStr, mailingsBySendDate[currentDateStr]);
        }
        makeDaysSelectable(mailingsByDays) {
            _.forEach($(".calendar-day"), calendarDay => {
                const $calendarDay = $(calendarDay);
                const dateStr = $calendarDay.data("date");
                const dayMailings = mailingsByDays[dateStr];
                if (!_.isEmpty(dayMailings)) {
                    $("#label-day-" + dateStr).addClass("calendar-day--selectable");
                }
                $calendarDay.off("click").on("click", () => this.changeSelectedDay(dateStr, _.sortBy(dayMailings, "sendTime")));
            });
        }
        changeSelectedDay(dateStr, dayMailings) {
            $("#calendar-container").find(".calendar-day--selected").removeClass("calendar-day--selected");
            $("#label-day-" + dateStr).addClass("calendar-day--selected");
            const dayDate = DateFormat.parseFormat(dateStr, "dd-MM-yy");
            const dayOfWeek = dayDate.toLocaleString(window.adminLocale, {
                weekday: "long"
            });
            dateStr = AGN.Lib.DateFormat.format(dayDate, window.adminDateFormat);
            $("#calendar-tile-day-mailings").html(Template.dom("dashboard-schedule-day", {
                dayOfWeek: dayOfWeek,
                dateStr: dateStr,
                dayMailings: dayMailings
            }));
            this.createPopovers(dayMailings);
        }
        createPopovers(dayMailings) {
            if (!dayMailings?.length) {
                return;
            }
            const mailingIds = dayMailings.map(mailing => mailing.id).join(",");
            $.get(mailingsPopoverInfoUrl, {
                mailingIds: mailingIds
            }).done(mailings => mailings.map(mailing => ({
                ...mailing,
                $el: $(`.schedule__day-mailing[data-mailing-id="${mailing.mailingId}"]`)
            })).forEach(mailing => new AGN.Lib.Dashboard.MailingPopover({
                ...mailing,
                isSent: mailing.sentCount
            }, false)));
        }
        switchMonth() {
            const month = parseInt($("#month_list option:selected").val());
            const year = parseInt($("#month_list_year option:selected").val());
            this.removeCurrentCalendar();
            this.showMonth(month, year);
            if (this.lastYearSelected()) {
                this.addYearOption();
            }
        }
    }
    AGN.Lib.Dashboard.CalendarLight = CalendarLight;
})();

(() => {
    const MONTH_FORMATTER = new Intl.DateTimeFormat(window.adminLocale, {
        month: "long"
    });
    const SHORT_MONTH_FORMATTER = new Intl.DateTimeFormat(window.adminLocale, {
        month: "short"
    });
    const MONTH_YEAR_FORMATTER = new Intl.DateTimeFormat(window.adminLocale, {
        month: "long",
        year: "numeric"
    });
    class DashboardCalendarPeriodPicker {
        constructor(calendar) {
            this.calendar = calendar;
            this.initActions();
        }
        jumpToDate(date) {
            this.#drawYears(date.getFullYear());
            this.#drawMonths();
            this.#drawWeeks(date.getFullYear());
            this.$findYear(date.getFullYear()).prop("checked", true);
            this.$findMonth(date.getMonth()).prop("checked", true);
            this.$findWeek(this.calendar.getWeek(date)).prop("checked", true);
            this.updateCalendarTitle();
            if (this.calendar.isWeekMode) {
                this.showWeeks();
            } else {
                this.showMonths();
            }
        }
        initActions() {
            this.$pickerTitleBtn.on("click", () => this.widerPeriod());
            this.$arrowUp.on("click", () => this.prev());
            this.$arrowDown.on("click", () => this.next());
            $("#period-picker").on("click", () => this.#updateArrowIcons());
        }
        widerPeriod() {
            if (this.$monthsBox.is(":visible")) {
                this.showYears();
            }
            if (this.$weeksBox.is(":visible")) {
                this.showMonths();
            }
        }
        selectYear() {
            this.$months.prop("checked", false);
            this.#drawWeeks(this.year);
            this.showMonths();
        }
        selectMonth() {
            if (this.calendar.isWeekMode) {
                this.showWeeks();
            } else {
                this.dropdown.hide();
                this.calendar.flip();
            }
        }
        selectWeek() {
            this.dropdown.hide();
            this.calendar.flip(moment().locale(window.adminLocale).isoWeekYear(this.year).isoWeek(this.week).startOf("isoWeek").toDate());
        }
        showYears() {
            this.$yearsBox.show();
            this.$monthsBox.hide();
            this.$weeksBox.hide();
            this.$pickerTitleBtn.text(`${this.$years.first().val()}-${this.$years.last().val()}`);
        }
        showMonths() {
            this.$yearsBox.hide();
            this.$monthsBox.show();
            this.$weeksBox.hide();
            this.$pickerTitleBtn.text(this.year);
        }
        showWeeks() {
            this.$yearsBox.hide();
            this.$monthsBox.hide();
            this.$weeksBox.show();
            this.$pickerTitleBtn.text(MONTH_FORMATTER.format(new Date(this.year, this.month)));
            this.$weeks.map((i, week) => $(week).next("label")).each((i, week) => $(week).hide().find("span:not(:first)").removeClass("alien"));
            this.$getMonthWeeks(this.year, this.month).forEach(week => {
                $(week).next("label").show();
                $(week).find("+ label span:not(:first)").each((i, day_el) => {
                    $(day_el).toggleClass("alien", parseInt($(day_el).data("month")) !== this.month);
                });
            });
        }
        $getMonthWeeks(year, month) {
            const weeks = new Set;
            const daysInMonth = moment().year(year).month(month).daysInMonth();
            for (let day = 1; day <= daysInMonth; day++) {
                const week = this.calendar.getWeek(new Date(year, month, day));
                if (!(month === 11 && week === 1) && !(month === 0 && week > 50)) {
                    weeks.add(week);
                }
            }
            return [ ...weeks ].map(week => this.$findWeek(week));
        }
        updateCalendarTitle() {
            this.calendar.$el.find(".tile-title > span").text(this.calendar.isWeekMode ? this.#getWeekText(this.year, this.week) : MONTH_YEAR_FORMATTER.format(new Date(this.year, this.month)));
        }
        #yearHtml(year) {
            return this.#btnHtml("year", year, year);
        }
        #monthHtml(month) {
            return this.#btnHtml("month", month, SHORT_MONTH_FORMATTER.format(new Date(2025, month)));
        }
        #weekHtml(week, content) {
            return this.#btnHtml("week", week, content);
        }
        #btnHtml(name, value, content) {
            return `\n        <input type="radio" class="btn-check" name="${name}" value="${value}" id="${name}-${value}" autocomplete="off">\n        <label class="btn" for="${name}-${value}">${content}</label>`;
        }
        get dropdown() {
            return bootstrap.Dropdown.getInstance($("#period-picker .dropdown-toggle"));
        }
        get year() {
            return parseInt(this.$yearsBox.find("input:checked").val());
        }
        get month() {
            return parseInt(this.$monthsBox.find("input:checked").val());
        }
        get week() {
            return parseInt(this.$weeksBox.find("input:checked").val());
        }
        get $yearsBox() {
            return this.$tile.find(".period-picker__years");
        }
        get $monthsBox() {
            return this.$tile.find(".period-picker__months");
        }
        get $weeksBox() {
            return this.$tile.find(".period-picker__weeks");
        }
        get $years() {
            return this.$yearsBox.find("input");
        }
        get $months() {
            return this.$monthsBox.find("input");
        }
        get $weeks() {
            return this.$weeksBox.find("input");
        }
        get $tile() {
            return $(".tile--period-picker");
        }
        get $pickerTitleBtn() {
            return this.$tile.find(".period-picker__title-btn");
        }
        get $arrowUp() {
            return this.$tile.find(".icon-caret-up");
        }
        get $arrowDown() {
            return this.$tile.find(".icon-caret-down");
        }
        next() {
            this.#step(true);
        }
        prev() {
            this.#step(false);
        }
        #step(next) {
            if (this.$yearsBox.is(":visible")) {
                this.#step12Years(next);
            }
            if (this.$monthsBox.is(":visible")) {
                this.#stepYear(next);
            }
            if (this.$weeksBox.is(":visible")) {
                this.#stepMonth(next);
            }
        }
        #step12Years(next) {
            this.#drawYears(parseInt(this.$years.first().val()) + (next ? 12 : -12));
            this.$pickerTitleBtn.text(`${this.$years.first().val()}-${this.$years.last().val()}`);
            this.$years.prop("checked", false);
        }
        #stepYear(next) {
            const nextYear = this.year + (next ? 1 : -1);
            let $nextYear = this.$findYear(nextYear);
            if (!$nextYear.length) {
                this.#drawYears(next ? nextYear : this.year - 12);
                $nextYear = this.$findYear(nextYear);
            }
            $nextYear.prop("checked", true);
            this.selectYear();
        }
        #stepMonth(next) {
            this.$findMonth(this.month + (next ? 1 : -1)).prop("checked", true);
            this.selectMonth();
        }
        $findYear(year) {
            return this.$yearsBox.find(`[value="${year}"]`);
        }
        $findMonth(month) {
            return this.$monthsBox.find(`[value="${month}"]`);
        }
        $findWeek(week) {
            return this.$weeksBox.find(`[value="${week}"]`);
        }
        #getWeekText(year, weekNumber) {
            const startOfWeek = moment().locale(window.adminLocale).isoWeekYear(year).isoWeek(weekNumber).startOf("isoWeek");
            const endOfWeek = moment(startOfWeek).endOf("isoWeek");
            const options = {
                year: "numeric",
                month: "2-digit",
                day: "2-digit"
            };
            const startFormatted = new Intl.DateTimeFormat(window.adminLocale, options).format(startOfWeek.toDate());
            const endFormatted = new Intl.DateTimeFormat(window.adminLocale, options).format(endOfWeek.toDate());
            const isoYear = startOfWeek.isoWeekYear();
            return `${startFormatted} - ${endFormatted} (${t("workflow.defaults.week")} ${weekNumber.toString().padStart(2, "0")}, ${isoYear})`;
        }
        #drawYears(startYear) {
            startYear = Math.max(Math.min(startYear, this.calendar.today.getFullYear()), this.calendar.config.minYear);
            this.$yearsBox.empty();
            for (let year = startYear; year < startYear + 12; year++) {
                this.$yearsBox.append(this.#yearHtml(year));
            }
            this.$years.on("click", () => this.selectYear());
        }
        #drawMonths() {
            this.$monthsBox.empty();
            Array.from({
                length: 12
            }, (j, month) => this.$monthsBox.append(this.#monthHtml(month)));
            this.$months.on("click", () => this.selectMonth());
        }
        #drawWeeks(year) {
            this.$weeksBox.empty();
            const firstWeekDay = new Date(year, 0, 1 - new Date(year, 0, 1).getDay() + this.calendar.firstDayOfWeek);
            if (this.calendar.getWeek(firstWeekDay) !== 1) {
                firstWeekDay.setTime(firstWeekDay.getTime() + 6048e5);
            }
            do {
                let weekNumber = this.calendar.getWeek(firstWeekDay);
                const $weekRow = $(`<div value="${weekNumber}">`);
                $weekRow.append($("<span>").text(weekNumber));
                for (let i = 0; i < 7; i++) {
                    $weekRow.append($(`<span data-month="${firstWeekDay.getMonth()}">${firstWeekDay.getDate()}</span>`));
                    firstWeekDay.setDate(firstWeekDay.getDate() + 1);
                }
                this.$weeksBox.append(this.#weekHtml(weekNumber, $weekRow.html()));
            } while (this.calendar.getWeek(firstWeekDay) !== 1 && firstWeekDay.getFullYear() === year);
            this.$weeks.on("click", () => this.selectWeek());
        }
        #updateArrowIcons() {
            this.$arrowDown.toggle(this.#shownArrowDown());
            this.$arrowUp.toggle(this.#shownArrowUp());
        }
        #shownArrowDown() {
            if (this.$yearsBox.is(":visible")) {
                return parseInt(this.$years.last().val()) < this.calendar.today.getFullYear() + 11;
            }
            if (this.$monthsBox.is(":visible")) {
                return this.year < this.calendar.today.getFullYear() + 11;
            }
            if (this.$weeksBox.is(":visible")) {
                return this.month < 11;
            }
            return false;
        }
        #shownArrowUp() {
            if (this.$yearsBox.is(":visible")) {
                return parseInt(this.$years.first().val()) > this.calendar.config.minYear;
            }
            if (this.$monthsBox.is(":visible")) {
                return this.year > this.calendar.config.minYear;
            }
            if (this.$weeksBox.is(":visible")) {
                return this.month > 0;
            }
            return false;
        }
    }
    AGN.Lib.Dashboard.DashboardCalendarPeriodPicker = DashboardCalendarPeriodPicker;
})();

(() => {
    const Form = AGN.Lib.Form;
    const Modal = AGN.Lib.Modal;
    const Storage = AGN.Lib.Storage;
    const Label = AGN.Lib.Dashboard.DashboardCalendarLabel;
    const CommentLabel = AGN.Lib.Dashboard.DashboardCalendarCommentLabel;
    class DashboardCalendarCommentsManager {
        constructor(calendar) {
            this.calendar = calendar;
            $("#toggle-calendar-comments").prop("checked", this.isCommentsShown);
        }
        get isCommentsShown() {
            return Storage.get("dashboard.calendar.comments");
        }
        set isCommentsShown(show) {
            return Storage.set("dashboard.calendar.comments", show);
        }
        toggle(show) {
            this.calendar.$grid.find(CommentLabel.SELECTOR).toggle(show);
            if (show && !this.calendar.commentsLoaded) {
                const startDate = $(`${this.calendar.daySelector}:first`).data("date");
                const endDate = $(`${this.calendar.daySelector}:last`).data("date");
                this.#load(startDate, endDate);
            }
            this.isCommentsShown = show;
        }
        create(date) {
            CommentLabel.showModal({
                date: date
            });
        }
        save(commentId) {
            const commentForm = Form.get($("#calendar-comment-form"));
            if (!commentForm.validate()) {
                return;
            }
            const data = commentForm.data();
            $.post(AGN.url("/calendar/saveComment.action"), data).done(resp => {
                if (!resp.commentId) {
                    AGN.Lib.Page.render(resp);
                    return;
                }
                if (!commentId) {
                    data.commentId = resp.commentId;
                    CommentLabel.getOrCreate(data).$el.toggle(this.isCommentsShown);
                } else {
                    Label.getByEntityId(commentId, CommentLabel.TYPE).updateComment(data);
                }
                Modal.getInstance(commentForm.$form).hide();
            });
        }
        remove(id) {
            Label.getByEntityId(id, CommentLabel.TYPE).remove();
        }
        #load(start, end) {
            $.get(AGN.url("/calendar/comments.action"), {
                start: start,
                end: end
            }).done(comments => _.each(comments, comment => CommentLabel.getOrCreate(comment)));
        }
    }
    AGN.Lib.Dashboard.DashboardCalendarCommentsManager = DashboardCalendarCommentsManager;
})();

(() => {
    const Template = AGN.Lib.Template;
    const Storage = AGN.Lib.Storage;
    const Label = AGN.Lib.Dashboard.DashboardCalendarLabel;
    const CommentLabel = AGN.Lib.Dashboard.DashboardCalendarCommentLabel;
    const MailingLabel = AGN.Lib.Dashboard.DashboardCalendarMailingLabel;
    const AutoOptLabel = AGN.Lib.Dashboard.DashboardCalendarAutoOptLabel;
    const PushLabel = AGN.Lib.Dashboard.DashboardCalendarPushLabel;
    const CalendarBase = AGN.Lib.Dashboard.CalendarBase;
    const Def = AGN.Lib.Dashboard.Def;
    const WEEK_MS = 6048e5;
    class DashboardCalendar extends CalendarBase {
        static DAY_CLASS="dashboard-calendar-day";
        static MODE_STORAGE_KEY="dashboard.calendar.mode";
        static SCROLL_STORAGE_KEY="dashboard.calendar.scroll";
        constructor($el, config) {
            super($el, config);
            this.today = new Date;
            this.dayMailingsLimit = config.showALlMailingsPerDay ? -1 : 6;
            this.commentsManager = new AGN.Lib.Dashboard.DashboardCalendarCommentsManager(this);
            this.periodPicker = new AGN.Lib.Dashboard.DashboardCalendarPeriodPicker(this);
            this.#initToggles();
            this.flip(this.today);
            this.$grid.css("background-color", "var(--xl-calendar-cell-border-color)");
        }
        get daySelector() {
            return `.${DashboardCalendar.DAY_CLASS}`;
        }
        get $days() {
            return $(this.daySelector);
        }
        get $grid() {
            return $("#dashboard-calendar-grid");
        }
        get isScrollShown() {
            return Storage.get(DashboardCalendar.SCROLL_STORAGE_KEY);
        }
        set isScrollShown(show) {
            return Storage.set(DashboardCalendar.SCROLL_STORAGE_KEY, show);
        }
        get isWeekMode() {
            return Storage.get(DashboardCalendar.MODE_STORAGE_KEY) === "week";
        }
        set mode(mode) {
            return Storage.set(DashboardCalendar.MODE_STORAGE_KEY, mode);
        }
        get selectedDate() {
            const date = new Date(this.periodPicker.year, this.periodPicker.month);
            if (date.getMonth() === this.today.getMonth() && date.getFullYear() === this.today.getFullYear()) {
                return this.today;
            }
            return date;
        }
        get $unsentList() {
            return $("#dashboard-calendar-unsent-tile").find(".tile-body");
        }
        get labels() {
            return this.$el.find(Label.SELECTOR).map((i, el) => Label.get($(el))).toArray();
        }
        #initToggles() {
            $('[data-action="switch-mode"]').prop("checked", this.isWeekMode).parent().show();
            $("#toggle-calendar-scroll").prop("checked", this.isScrollShown);
        }
        $day(date) {
            return this.$grid.find(`${this.daySelector}[data-date="${date}"]`);
        }
        removeCurrentCalendar() {
            this.$grid.empty();
        }
        showWeek(day, month, year) {
            this.removeCurrentCalendar();
            const date = new Date(year, month, day);
            date.setDate(day - date.getDay() - 1 + this.firstDayOfWeek);
            const startDate = new Date(date.getFullYear(), date.getMonth(), date.getDate());
            startDate.setDate(startDate.getDate() + 1);
            if (month === 0 && day === 1 && this.getWeek(startDate) !== 1) {
                startDate.setTime(startDate.getTime() + WEEK_MS);
                date.setTime(date.getTime() + WEEK_MS);
            }
            for (let i = 0; i < 7; i++) {
                date.setDate(date.getDate() + 1);
                this.addDay(date, false);
            }
            this.fillCalendar(this.dateToServiceFormat(startDate), this.dateToServiceFormat(date));
        }
        addWeekNumber(date) {}
        addDay(date, alien) {
            const dateStr = this.dateToServiceFormat(new Date(date.getFullYear(), date.getMonth(), date.getDate()));
            const $cell = Template.dom("dashboard-calendar-day", {
                day: date.getDate(),
                date: dateStr
            });
            $cell.find(".dashboard-calendar-day").toggleClass(`${DashboardCalendar.DAY_CLASS}--today`, this.isToday(date)).toggleClass(`${DashboardCalendar.DAY_CLASS}--alien`, alien);
            this.$grid.append($cell);
            if (!this.isWeekMode && $cell.is(":nth-child(7n+1)")) {
                $cell.append(`<div class="dashboard-calendar__week-number">${this.getWeek(date)}</div>`);
            }
        }
        fillCalendar(start, end) {
            this.#loadData(start, end);
            this.toggleScroll(this.isScrollShown);
            this.$days.droppable({
                accept: Label.SELECTOR
            });
        }
        #loadData(start, end) {
            const dayMailingsLimit = this.dayMailingsLimit;
            const loadComments = this.commentsManager.isCommentsShown;
            $.get(AGN.url("/calendar/labels.action"), {
                start: start,
                end: end,
                dayMailingsLimit: dayMailingsLimit,
                loadComments: loadComments
            }).done(data => {
                _.each(data.optimizations, autoOpt => AutoOptLabel.getOrCreate(autoOpt));
                _.each(data.pushes, push => PushLabel.getOrCreate(push));
                _.each(data.mailings, mailing => this.addMailingLabel(mailing, dayMailingsLimit));
                _.each(data.comments, comment => CommentLabel.getOrCreate(comment));
                this.commentsLoaded = loadComments;
                AGN.Lib.CoreInitializer.run("truncated-text-popover", this.$grid);
            });
        }
        flip(date = this.selectedDate) {
            if (this.isWeekMode) {
                this.showWeek(date.getDate(), date.getMonth(), date.getFullYear());
            } else {
                this.showMonth(date.getMonth(), date.getFullYear());
            }
            this.periodPicker.jumpToDate(date);
        }
        toggleMode(isWeekMode) {
            this.mode = isWeekMode ? "week" : "month";
            this.flip();
        }
        synchronizeMonthsList(month, year) {}
        jumpToToday() {
            this.flip(this.today);
        }
        dropLabel(event, ui) {
            const $label = ui.draggable;
            Label.get($label).drop($(this));
        }
        initUnsentList(mailings, planned) {
            if (!planned) {
                this.$unsentList.droppable({
                    accept: '[id^="dashboard-calendar-mailing-"]'
                });
            }
            mailings.map(mailing => this.asUnsentMailingData(mailing, planned)).forEach(mailing => new MailingLabel(mailing));
        }
        asUnsentMailingData(mailing, planned) {
            return {
                ...mailing,
                link: AGN.url(`/mailing/${mailing.id}/settings.action`),
                mediatype: mailing.mediatype?.toLowerCase(),
                labelId: `dashboard-calendar-unsent-${mailing.id}`,
                inUnsentList: true,
                planned: planned,
                sent: false,
                sendTime: false
            };
        }
        showMoreMailings($btn) {
            const date = $btn.closest(this.daySelector).data("date");
            this.getMailings(date, date, -1);
            $btn.remove();
        }
        getMailings(start, end, dayMailingsLimit) {
            $.get(AGN.url("/calendar/mailings.action"), {
                start: start,
                end: end,
                dayMailingsLimit: dayMailingsLimit
            }).done(mailings => _.each(mailings, mailing => this.addMailingLabel(mailing, dayMailingsLimit)));
        }
        $dayBody($day) {
            return $day.find(`${this.daySelector}__body`);
        }
        addMailingLabel(mailing, limit) {
            const mailingSendDate = moment(mailing.sendDate).tz(window.agnTimeZoneId);
            mailing.sendDate = mailingSendDate.format(Def.DATE_FORMAT);
            mailing.sendTime = mailingSendDate.format(Def.TIME_FORMAT);
            const $day = this.$day(mailing.sendDate);
            if (limit > 0 && $day.find('[id^="dashboard-calendar-mailing-"]').length >= limit - 1) {
                if (!$day.find('[data-action="show-more-mailings"]').exists()) {
                    this.$dayBody($day).append(Template.text("dashboard-calendar-show-more-btn"));
                }
                return;
            }
            mailing.link = this.getMailingLink(mailing);
            MailingLabel.getOrCreate(mailing);
        }
        toggleScroll(show) {
            this.$days.map((i, day) => this.$dayBody($(day))).each((i, body) => {
                $(body).toggleClass("js-scrollable", !show);
                if (show) {
                    AGN.Lib.Scrollbar.get($(body), false)?.destroy();
                }
            });
            if (!show) {
                AGN.Lib.Scrollbar.get(this.$grid, false)?.destroy();
            }
            AGN.Lib.CoreInitializer.run([ "scrollable", "tooltip" ], $("#dashboard-calendar-table"));
            this.isScrollShown = show;
        }
        search(str) {
            this.labels.forEach(label => label.toggle(label.text?.toLowerCase().includes(str)));
        }
        getLabelsByType($day, type) {
            return $day.find(Label.SELECTOR).map(label => Label.get($(label))).filter(label => label.type === type);
        }
        getLastLabelOfType($day, type) {
            return this.getLabelsByType($day, type).slice(-1)[0];
        }
    }
    AGN.Lib.Dashboard.DashboardCalendar = DashboardCalendar;
})();

(() => {
    const Field = AGN.Lib.Field;
    AGN.Lib.Validator.new("calendar-comment", {
        valid: function($e, options) {
            return !this.errors($e, options).length;
        },
        errors: function() {
            const errors = validateCommentText();
            if ($('[name="isCustomRecipients"]').val() === "true") {
                errors.push(...validateCustomRecipients());
            }
            if ($('[name="deadline"]').is(":checked")) {
                errors.push(...validateReminder());
            }
            return errors;
        }
    });
    function validateCommentText() {
        const errors = [];
        const $comment = $("#comment-text");
        const commentText = $comment.val();
        if (_.isEmpty(_.trim(commentText))) {
            errors.push({
                field: $comment,
                msg: t("calendar.error.empty_comment")
            });
        }
        if (byteCount(commentText) > 1e3) {
            errors.push({
                field: $comment,
                msg: t("calendar.error.long_comment")
            });
        }
        return errors;
    }
    function validateCustomRecipients() {
        const errors = [];
        const $recipients = $('[name="recipients"]');
        const emails = $recipients.val().filter(email => email?.trim() !== "");
        if (!emails?.length) {
            errors.push({
                field: $recipients,
                msg: t("calendar.error.empty_recipient_list")
            });
        }
        const recipients = emails.join(",");
        if (byteCount(recipients) > 2e3) {
            errors.push({
                field: $recipients,
                msg: t("calendar.error.long_recipient_list")
            });
        }
        _.each(emails, email => {
            if (!AGN.Lib.Helpers.isValidEmail(email)) {
                errors.push({
                    field: $recipients,
                    msg: t("calendar.error.invalid_email") + " " + email
                });
            }
        });
        return errors;
    }
    function validateReminder() {
        const $reminderDate = $("#remind-date");
        return Field.create($reminderDate).dateValue < new Date ? [ {
            field: $reminderDate,
            msg: t("calendar.error.reminderInPast")
        } ] : [];
    }
    function byteCount(s) {
        var escapedStr = encodeURI(s);
        if (escapedStr.indexOf("%") != -1) {
            var count = escapedStr.split("%").length - 1;
            if (count == 0) count++;
            var tmp = escapedStr.length - count * 3;
            count = count + tmp;
        } else {
            count = escapedStr.length;
        }
        return count;
    }
})();

(() => {
    const Def = AGN.Lib.Dashboard.Def;
    const TileSize = Def.TileSize;
    class DraggableTile {
        constructor(controller) {
            if (new.target === DraggableTile) {
                throw new TypeError("Cannot construct Abstract Tile instances directly!");
            }
            this._controller = controller;
            this.variants = [ TileSize.REGULAR ];
            this.size = this.variants[0];
        }
        displayIn($place) {
            if ($place?.is(".draggable-tile")) {
                $place.replaceWith(this.$el);
            } else {
                $place.append(this.$el);
            }
            this.afterTileAdded();
        }
        afterTileAdded() {
            this._$el.data("tile", this);
            this.$el.trigger("agn:grid-modified", [ this ]);
            AGN.runAll(this.$el);
        }
        insertAfter(tile) {
            tile.$el.after(this.$el);
            this.afterTileAdded();
        }
        insertBefore(tile) {
            tile.$el.before(this.$el);
            this.afterTileAdded();
        }
        remove() {
            const $container = this.$container;
            this.$el.remove();
            $container.trigger("agn:grid-modified");
        }
        switchDroppable(on) {
            this.$el.droppable("option", "disabled", !on);
        }
        swap(tileToSwapWith) {
            const tmp = $("<span>").hide();
            this.$el.before(tmp);
            tileToSwapWith.$el.before(this.$el);
            tmp.replaceWith(tileToSwapWith.$el);
        }
        get $container() {
            return this.$el.parent();
        }
        get id() {
            return this.constructor.ID;
        }
        get name() {
            return t(`dashboard.tile.${this.id}`);
        }
        thumbnail() {
            return AGN.url(`/assets/core/images/dashboard/dashboard-tile-sprite.svg#${this.id}`);
        }
        allowed() {
            return AGN.Lib.Template.exists(this.templateName);
        }
        get $el() {
            if (!this._$el) {
                this._$el = AGN.Lib.Template.dom(this.templateName, this.templateOptions);
            }
            return this._$el;
        }
        get templateOptions() {
            return {
                tileName: this.name,
                tileSize: this.size.name,
                overlay: this.getOverlay()
            };
        }
        set $el($el) {
            this._$el = $el;
        }
        get position() {
            if (!this._position) {
                return {
                    rows: [],
                    cols: []
                };
            }
            return this._position;
        }
        set position(position) {
            this._position = position;
        }
        get beginCol() {
            return this.position.cols[0];
        }
        get beginRow() {
            return this.position.rows[0];
        }
        get endCol() {
            return this.position.cols[1];
        }
        get endRow() {
            return this.position.rows[1];
        }
        get isEmpty() {
            return this.id === AGN.Lib.Dashboard.EmptyTile.ID;
        }
        get isRegular() {
            return this.size === TileSize.REGULAR;
        }
        get isTall() {
            return this.size === TileSize.TALL;
        }
        get isXl() {
            return this.size === TileSize.X_LARGE;
        }
        get isWide() {
            return this.size === TileSize.WIDE;
        }
        get isXWide() {
            return this.size === TileSize.X_WIDE;
        }
        get templateName() {
            return `dashboard-tile-${this.id}`;
        }
        get shown() {
            return this._$el?.is(":visible");
        }
        toggleHighlight(isHovered) {
            this.$el.toggleClass("draggable-accept--hovered", isHovered);
        }
        getOverlay() {
            return AGN.Lib.Template.text("dashboard-tile-overlay");
        }
        static get($tile) {
            return $tile.data("tile");
        }
    }
    AGN.Lib.Dashboard.DraggableTile = DraggableTile;
})();

(() => {
    class BaseMailingStatisticsTile extends AGN.Lib.Dashboard.DraggableTile {
        constructor() {
            if (new.target === BaseMailingStatisticsTile) {
                throw new TypeError("Cannot construct Abstract BaseMailingStatisticsTile instances directly!");
            }
            super();
            if (this.needsRedrawOnMobile()) {
                this._isMobileView = false;
                this.#setupDisplayTypeChangeHandler();
            }
            this._chart = null;
            this._mailingId = 0;
            this._data = null;
            this._colors = AGN.Lib.Helpers.getStatColorsHexValues();
            this._cache = new AGN.Lib.InMemoryCache;
        }
        #setupDisplayTypeChangeHandler() {
            $(window).on("displayTypeChanged", (e, isMobileView) => {
                this._isMobileView = isMobileView;
                if (this._chart) {
                    this.updateChart(true);
                }
            });
        }
        displayIn($place) {
            super.displayIn($place);
            this.updateChartIfCanvasExists();
        }
        insertAfter(tile) {
            super.insertAfter(tile);
            this.updateChartIfCanvasExists();
        }
        insertBefore(tile) {
            super.insertBefore(tile);
            this.updateChartIfCanvasExists();
        }
        updateChartIfCanvasExists() {
            if (this.findCanvas$().exists()) {
                this.updateChart();
            }
        }
        async updateChart(forceUpdate = false) {
            const mailingIdBefore = this._mailingId;
            this._mailingId = this.$el.find("[data-statistics-mailing]").val();
            const mailingChanged = this._mailingId !== mailingIdBefore;
            if (!mailingChanged && !forceUpdate) {
                return;
            }
            if (mailingChanged) {
                this._data = await this.#fetchData();
            }
            this.drawChart();
        }
        #fetchData() {
            const mailingId = this._mailingId;
            const cachedResult = this._cache.get(mailingId);
            if (cachedResult) {
                return cachedResult;
            }
            const promise = new Promise((resolve, reject) => {
                $.ajax({
                    type: "GET",
                    url: this.getStatisticsUrl(),
                    data: {
                        mailingId: mailingId
                    },
                    success: data => resolve(data),
                    error: error => reject(error)
                });
            });
            this._cache.set(mailingId, promise);
            return promise;
        }
        getStatisticsUrl() {
            throw new Error("#getStatisticsUrl function not implemented for statistics tile!");
        }
        drawChart() {
            this._chart?.destroy();
            const ctx = this.findCanvas$()[0].getContext("2d");
            this._chart = new Chart(ctx, this.getChartOptions());
        }
        findCanvas$() {
            return this.$el.find("canvas");
        }
        getChartOptions() {
            throw new Error("Chart options not defined for statistics tile!");
        }
        needsRedrawOnMobile() {
            return false;
        }
    }
    AGN.Lib.Dashboard.BaseMailingStatisticsTile = BaseMailingStatisticsTile;
})();

(() => {
    class BaseMailingDeviceStatisticsTile extends AGN.Lib.Dashboard.BaseMailingStatisticsTile {
        constructor() {
            if (new.target === BaseMailingDeviceStatisticsTile) {
                throw new TypeError("Cannot construct Abstract BaseMailingDeviceStatisticsTile instances directly!");
            }
            super();
        }
        getDeviceTypesMap() {
            const DEVICE_TYPES = {
                PC: t("statistics.device.desktop"),
                TABLET: t("statistics.device.tablet"),
                MOBILE: t("statistics.device.mobile"),
                SMART_TV: t("statistics.device.smarttv"),
                MULTIPLE: t("statistics.device.mixed")
            };
            return Object.fromEntries(Object.entries(this._data.byDevice).map(([deviceClass, value]) => [ DEVICE_TYPES[deviceClass], value ]));
        }
        getChartOptions() {
            const deviceTypesMap = this.getDeviceTypesMap();
            return {
                type: "agnDoughnut",
                data: {
                    labels: Object.keys(deviceTypesMap),
                    datasets: [ {
                        data: Object.values(deviceTypesMap),
                        backgroundColor: this._colors,
                        borderWidth: 0
                    } ]
                }
            };
        }
        getTotalValue() {
            const values = Object.values(this._data.byDevice);
            return AGN.Lib.ChartUtils.getTotal(values);
        }
    }
    AGN.Lib.Dashboard.BaseMailingDeviceStatisticsTile = BaseMailingDeviceStatisticsTile;
})();

