(() => {
    const Popover = AGN.Lib.Popover;
    const Template = AGN.Lib.Template;
    const NO_PREVIEW_IMG = "/assets/core/images/facelift/no_preview.svg";
    const CONTENT_LOADER_PH = "---";
    const POPOVER_SHOW_DELAY = 500;
    class MailingPopover extends Popover {
        constructor(mailing, showLoader) {
            super();
            this.showLoader = showLoader;
            this.mailing = mailing;
            const thumbnail = AGN.url(this.mailingThumbnailSrc(mailing));
            const $content = this.content(this.showLoader ? this.loaderInfo : this.loadedInfo(mailing, thumbnail));
            this.popover = Popover.getOrCreate(this.mailing.$el, this.options($content));
            let lastMouseX = 0;
            let lastMouseY = 0;
            function generateGetBoundingClientRect(x = 0, y = 0) {
                return () => ({
                    width: 0,
                    height: 0,
                    top: y,
                    right: x,
                    bottom: y,
                    left: x
                });
            }
            const updatePosition = ({clientX: x, clientY: y}) => {
                lastMouseX = x;
                lastMouseY = y;
                if (this.popover?._popper?.state?.elements?.reference) {
                    this.popover._popper.state.elements.reference = virtualElement;
                }
                virtualElement.getBoundingClientRect = generateGetBoundingClientRect(x, y);
                this.popover?._popper?.update();
            };
            const virtualElement = {
                getBoundingClientRect: generateGetBoundingClientRect()
            };
            this.mailing.$el.off("mouseenter").on("mouseenter", e => {
                if (this.disabled) {
                    return;
                }
                const loadTimeout = setTimeout(() => {
                    if (this.showLoader) {
                        AGN.Lib.Loader.prevent();
                        $.get(AGN.url("/calendar/mailingsPopoverInfo.action"), {
                            mailingIds: this.mailing.id
                        }).done(popoverInfo => {
                            const thumbnail = AGN.url(this.mailingThumbnailSrc(popoverInfo[0]));
                            let img = new Image;
                            img.src = thumbnail;
                            img.onload = () => {
                                this.$loadedContent = this.content(this.loadedInfo(popoverInfo[0], thumbnail));
                                if (Popover.isShown(this.popover)) {
                                    $content.replaceWith(this.$loadedContent);
                                } else {
                                    this.popover.setContent({
                                        ".popover-body": this.$loadedContent
                                    });
                                }
                                this.showLoader = false;
                            };
                        });
                    }
                }, POPOVER_SHOW_DELAY / 2);
                const showTimeout = setTimeout(() => {
                    this.popover.show();
                    updatePosition({
                        clientX: lastMouseX,
                        clientY: lastMouseY
                    });
                }, POPOVER_SHOW_DELAY);
                this.mailing.$el.on("mousemove", updatePosition);
                this.mailing.$el.on("mouseleave", () => {
                    this.mailing.$el.off("mousemove");
                    this.popover.hide();
                    clearTimeout(loadTimeout);
                    clearTimeout(showTimeout);
                    if (this.$loadedContent?.length) {
                        this.popover.setContent({
                            ".popover-body": this.$loadedContent
                        });
                    }
                });
            });
        }
        loadedInfo(mailing, thumbnail) {
            return {
                ...mailing,
                isSent: this.mailing.isSent,
                thumbnailUrl: thumbnail,
                showLoader: false
            };
        }
        disable() {
            this.disabled = true;
        }
        enable() {
            this.disabled = false;
        }
        content(info) {
            const content = Template.dom("calendar-mailing-popover-content", info);
            AGN.runAll(content);
            return content;
        }
        get loaderInfo() {
            return {
                shortname: this.mailing.shortname,
                thumbnailUrl: AGN.url(NO_PREVIEW_IMG),
                subject: CONTENT_LOADER_PH,
                description: CONTENT_LOADER_PH,
                mailinglist: CONTENT_LOADER_PH,
                sendDate: CONTENT_LOADER_PH,
                sentCount: CONTENT_LOADER_PH,
                isSent: this.mailing.isSent,
                openers: CONTENT_LOADER_PH,
                clickers: CONTENT_LOADER_PH,
                showLoader: true
            };
        }
        options(content) {
            return {
                content: content,
                html: true,
                trigger: "manual",
                customClass: "dashboard-mailing-popover",
                animation: true,
                popperConfig: defaultBsPopperConfig => ({
                    ...defaultBsPopperConfig,
                    placement: "bottom-start",
                    modifiers: [ ...defaultBsPopperConfig.modifiers || [], {
                        name: "offset",
                        options: {
                            offset: ({placement: placement, reference: reference, popper: popper}) => [ "bottom-end", "top-end" ].includes(placement) ? [ -15, 15 ] : [ 15, 15 ]
                        }
                    }, {
                        name: "flip",
                        options: {
                            enabled: true,
                            fallbackPlacements: [ "bottom-end", "top-start", "top-end" ]
                        }
                    } ]
                })
            };
        }
        mailingThumbnailSrc(popoverInfo) {
            if (popoverInfo.post) {
                return "/assets/core/images/facelift/post_thumbnail.jpg";
            }
            if (popoverInfo.thumbnailComponentId) {
                return "/sc?compID=" + popoverInfo.thumbnailComponentId;
            }
            return NO_PREVIEW_IMG;
        }
    }
    AGN.Lib.Dashboard.MailingPopover = MailingPopover;
})(jQuery);

AGN.Lib.Controller.new("dashboard-grid", function() {
    const LEGACY_TILES = [ "xl-calendar" ];
    const Dashboard = AGN.Lib.Dashboard;
    const Modal = AGN.Lib.Modal;
    const Def = Dashboard.Def;
    const TileSize = Def.TileSize;
    const EmptyTile = Dashboard.EmptyTile;
    const DraggableTile = Dashboard.DraggableTile;
    const controller = this;
    let tiles;
    let placeholderTile;
    let grid;
    this.addDomInitializer("dashboard-grid", function() {
        tiles = initTiles().filter(tile => tile.allowed());
        const layout = JSON.parse(this.config.layout) || _.clone(Def.LAYOUT.DEFAULT);
        fixLegacyTiles(layout);
        drawTiles(schemaToTiles(layout.SCHEMA), layout.COLS_COUNT);
        infoIfDashboardEmpty();
        $(window).on("displayTypeChanged", (e, isMobileView) => {
            if (isMobileView) {
                toggleEditMode(false);
            }
        });
        toggleEditMode(false);
    });
    function initTiles() {
        return [ new Dashboard.MailingsTile(controller), new Dashboard.PlanningTile(controller), new Dashboard.StatisticsTile(controller), new Dashboard.ClickersTile(controller), new Dashboard.OpenersTile(controller), new Dashboard.WorkflowsTile(controller), new Dashboard.ImportExportTile(controller), new Dashboard.AddOnsTile(controller), new Dashboard.NewsTile(controller), new Dashboard.CalendarTile(controller), new Dashboard.AnalysisTile(controller) ];
    }
    function fixLegacyTiles(layout) {
        layout.SCHEMA.filter(tile => LEGACY_TILES.includes(tile.id)).map(tile => tile.position).forEach(pos => {
            pos.rows.forEach(row => {
                pos.cols.forEach(col => {
                    layout.SCHEMA.push({
                        id: Dashboard.EmptyTile.ID,
                        positions: {
                            rows: [ row ],
                            cols: [ col ]
                        }
                    });
                });
            });
        });
        layout.SCHEMA = layout.SCHEMA.filter(tile => !LEGACY_TILES.includes(tile.id));
    }
    function infoIfDashboardEmpty() {
        if (!grid.visibleTiles.length) {
            AGN.Lib.Messages.info("dashboard.empty");
        }
    }
    function getSizeByTileDescription(tileDescr, defaultVal) {
        const rowsOccupied = tileDescr.position?.rows?.length;
        const colsOccupied = tileDescr.position?.cols?.length;
        if (rowsOccupied === 2 && colsOccupied === 1) {
            return TileSize.TALL;
        }
        if (rowsOccupied === 1 && colsOccupied === 2) {
            return TileSize.WIDE;
        }
        if (rowsOccupied === 2 && colsOccupied === 3) {
            return TileSize.X_LARGE;
        }
        return defaultVal;
    }
    function schemaToTiles(schema) {
        return schema.map(tileDescr => {
            const tile = getTileById(tileDescr.id);
            tile.size = getSizeByTileDescription(tileDescr, tile.size);
            return tile;
        });
    }
    function drawTiles(tiles, colsCount) {
        grid = new Dashboard.DashboardGrid(2, colsCount, tiles);
    }
    this.addAction({
        click: "delete-tile"
    }, function() {
        const tileToDelete = DraggableTile.get(this.el.closest(".draggable-tile"));
        grid.replaceWithEmptyTile(tileToDelete);
    });
    this.addAction({
        click: "replace-tile"
    }, function() {
        placeholderTile = DraggableTile.get(this.el.closest(".draggable-tile"));
        Modal.fromTemplate("dashboard-tiles-selection-modal", {
            tiles: getUnusedTiles()
        });
    });
    this.addAction({
        click: "select-tile"
    }, function() {
        placeholderTile = DraggableTile.get(this.el.closest(".draggable-tile"));
        Modal.fromTemplate("dashboard-tiles-selection-modal", {
            tiles: getAllowedToAddTiles()
        });
    });
    function getAllowedToAddTiles() {
        return getUnusedTiles().map(tile => {
            tile.variants.forEach(variant => {
                const interferingTiles = grid.findInterferingTilesToReplace(placeholderTile, variant);
                variant.disabled = interferingTiles.some(tile => !tile.isEmpty);
            });
            return tile;
        });
    }
    function getUnusedTiles() {
        const displayedTiles = grid.visibleTiles.map(tile => tile.id);
        return tiles.filter(tile => !tile.isEmpty && !displayedTiles.includes(tile.id)).map(tile => {
            tile.variants.forEach(variant => variant.disabled = false);
            return tile;
        });
    }
    this.addAction({
        click: "add-tile"
    }, function() {
        const modal = Modal.getInstance(this.el);
        const tileToAdd = getTileById(this.el.data("tile-id"));
        tileToAdd.size = TileSize.from(this.el.data("type")) || TileSize.REGULAR;
        const interferingTiles = grid.findInterferingTilesToReplace(placeholderTile, tileToAdd.size).filter(tile => !tile.isEmpty);
        const callback = () => {
            grid.replaceTile(placeholderTile, tileToAdd);
            modal.hide();
        };
        if (interferingTiles.length > 1) {
            AGN.Lib.Confirm.from("dashboard-replace-tiles-question-modal", {
                tileNames: interferingTiles.map(tile => tile.name).join(", ")
            }).done(callback);
        } else {
            callback();
        }
    });
    this.addAction({
        change: "redraw-mailing-statistics"
    }, function() {
        const $tile = this.el.closest(".draggable-tile");
        const tile = DraggableTile.get($tile);
        tile.updateChart();
    });
    this.addAction({
        click: "open-mailing-statistics"
    }, function() {
        const mailingId = this.el.closest(".draggable-tile").find("[data-statistics-mailing]").val();
        AGN.Lib.Page.reload(AGN.url(`/statistics/mailing/${mailingId}/view.action`));
    });
    function getTileById(id) {
        return tiles[tiles.findIndex(tile => tile.id === id)] || new EmptyTile;
    }
    function closePopupWithEditLink($popup) {
        if (!$popup.length) {
            return;
        }
        $(":focus", $popup).blur();
        toastr.clear($popup);
    }
    this.addAction({
        click: "edit-dashboard"
    }, function() {
        toggleEditMode(true);
        const $infoPopup = this.el.closest(".popup");
        closePopupWithEditLink($infoPopup);
    });
    this.addAction({
        click: "stop-editing"
    }, function() {
        toggleEditMode(false);
        infoIfDashboardEmpty();
        saveTilesLayout();
    });
    function saveTilesLayout() {
        $.ajax({
            type: "POST",
            url: AGN.url("/dashboard/layout/save.action"),
            data: {
                layout: JSON.stringify(grid.schema)
            },
            async: false
        }).done(() => AGN.Lib.Messages.defaultSaved());
    }
    function toggleEditMode(on) {
        $("#dashboard-start-edit-btn").closest("li").toggle(!on);
        $("body").toggleClass("edit-mode", !!on);
        grid.swapper.toggle(on);
    }
    this.addAction({
        click: "select-layout"
    }, function() {
        Modal.fromTemplate("dashboard-layout-selection-modal");
    });
    function isGridLeftOver(tile, newColsCount) {
        switch (newColsCount) {
          case 3:
            return tile.position.cols.includes(3);

          case 2:
            return tile.position.cols.includes(2) || tile.position.cols.includes(3);

          default:
            return false;
        }
    }
    function getTilesForSmallerLayout(newColsCount) {
        grid.tiles.filter(tile => (tile.isXl || tile.isXWide) && isGridLeftOver(tile, newColsCount)).forEach(tile => grid.replaceWithEmptyTile(tile));
        const tiles = grid.tiles.map(tile => {
            if (tile.isWide && isGridLeftOver(tile, newColsCount)) {
                const emptyTile = new EmptyTile;
                emptyTile.position = {
                    cols: [ tile.beginCol ],
                    rows: [ tile.beginRow ]
                };
                return emptyTile;
            }
            return tile;
        });
        return tiles.filter(tile => !isGridLeftOver(tile, newColsCount));
    }
    function insertEmptyColumn(tiles, col) {
        for (let i = 0; i < grid.rows; i++) {
            const emptyTile = new EmptyTile;
            emptyTile.position = {
                rows: [ i ],
                cols: [ col ]
            };
            tiles.push(emptyTile);
        }
    }
    function getTilesForBiggerLayout(newColsCount) {
        const displayedTiles = grid.tiles;
        for (let i = 0; i < newColsCount - grid.cols; i++) {
            insertEmptyColumn(displayedTiles, grid.cols + i);
        }
        return displayedTiles;
    }
    function getTilesForChangedLayout(newColsCount) {
        if (newColsCount < grid.cols) {
            return getTilesForSmallerLayout(newColsCount);
        }
        return getTilesForBiggerLayout(newColsCount);
    }
    this.addAction({
        click: "change-layout"
    }, function() {
        const newColsCount = this.el.data("cols-count");
        if (newColsCount === grid.cols) {
            return;
        }
        const newTiles = getTilesForChangedLayout(newColsCount);
        drawTiles(newTiles, newColsCount);
    });
});

