(function() {
    const Def = AGN.Lib.WM.Definitions;
    class FieldRulesTable extends AGN.Lib.InputTable {
        constructor($container, data = [], readonly, profileFieldsTypes) {
            $container.empty();
            const tableRows = data.map(row => ({
                ...row,
                chainOperator: row.chainOperator === parseInt(Def.constants.chainOperatorOr)
            }));
            super($container, tableRows, readonly);
            this.profileFieldsTypes = profileFieldsTypes;
            this.#hideFirstChainOperatorSwitch();
            this.updateOperatorsAvailability();
        }
        get $form() {
            return this.$container.closest("form");
        }
        get $profileFieldSelect() {
            return this.$form.find('[name="profileField"]');
        }
        get currentProfileField() {
            return this.$profileFieldSelect.val();
        }
        get currentProfileFieldIsGender() {
            return this.currentProfileField?.toLowerCase() === Def.GENDER_PROFILE_FIELD;
        }
        addActions() {
            super.addActions();
            this.addAction({
                click: "[data-add-row]"
            }, () => this.onRowAddedManually());
            this.addAction({
                click: "[data-delete-row]"
            }, () => this.onRowsChangedManually());
        }
        addRow(rowData) {
            const self = this;
            super.addRow(rowData);
            this.$container.find('tr:last [data-name="primaryOperator"]').on("change", function() {
                self.updateValueInput($(this));
            });
        }
        renderTable(data) {
            super.renderTable(data);
            this.$container.find('[data-name="primaryOperator"]').toArray().filter(operator => $(operator).val() === Def.constants.operatorIs).forEach(operator => $(operator).data("previous-value", Def.constants.operatorIs));
            if (this.currentProfileFieldIsGender) {
                this.$profileFieldSelect.data("previous-value", Def.GENDER_PROFILE_FIELD);
            }
            this.removeLastRow();
        }
        onRowAddedManually() {
            this.updateOperatorsAvailability();
            this.onRowsChangedManually();
        }
        onRowsChangedManually() {
            this.#hideFirstChainOperatorSwitch();
            this.$container.trigger("change");
        }
        #hideFirstChainOperatorSwitch() {
            this.$container.find('[data-name="chainOperator"]:first').closest(".switch").prop("checked", false).closest("td").hide();
            this.$container.find('[data-name="chainOperator"]:not(:first)').closest(".switch").show();
        }
        collect() {
            const rules = super.collect();
            rules.forEach(rule => {
                rule.chainOperator = parseInt(rule.chainOperator ? Def.constants.chainOperatorOr : Def.constants.chainOperatorAnd);
                rule.parenthesisOpened = parseInt(rule.parenthesisOpened);
                rule.parenthesisClosed = parseInt(rule.parenthesisClosed);
                rule.primaryOperator = parseInt(rule.primaryOperator);
            });
            return rules;
        }
        get rowTemplate() {
            const options = this.$primaryOperatorOptions();
            const valueElement = this.ruleValueInput();
            return `\n          <tr>\n              <td style="max-width: 70px">\n                  <label class="switch">\n                      <input type="checkbox" data-name="chainOperator" value="true" {{- chainOperator ? 'checked' : ''}} ${this.readonlyAttr}>\n                      <span>AND</span>\n                      <span class="flex-center flex-grow-1">OR</span>\n                  </label>\n              </td>\n              <td style="max-width: 45px">\n                  <select data-name="parenthesisOpened" class="form-control rule-field" ${this.readonlyAttr}>\n                      <option value="0" {{- parenthesisOpened === 0 ? 'selected' : ''}}>&nbsp</option>\n                      <option value="1" {{- parenthesisOpened === 1 ? 'selected' : ''}}>(</option>\n                  </select>\n              </td>\n              <td>\n                  <select data-name="primaryOperator" class="form-control" data-action="start-rule-operator-change" ${this.readonlyAttr} data-select-options="dropdownAutoWidth: true">\n                      ${options}\n                  </select>\n              </td>\n              <td>\n                  ${valueElement}\n              </td>            \n              <td style="max-width: 45px">\n                  <select data-name="parenthesisClosed" class="form-control rule-field" ${this.readonlyAttr}>\n                      <option value="0" {{- parenthesisClosed === 0 ? 'selected' : ''}}>&nbsp</option>\n                      <option value="1" {{- parenthesisClosed === 1 ? 'selected' : ''}}>)</option>\n                  </select>\n              </td>                        \n          </tr>`;
        }
        emptyRuleValueInput() {
            return `<input type="text" data-name="primaryValue" value="" class="form-control rule-field" ${this.readonlyAttr}/>`;
        }
        ruleValueInput() {
            return `\n        {{ if (${this.currentProfileField === Def.GENDER_PROFILE_FIELD}) { }}\n            ${this.genderSelect(true)}\n        {{ } else if (primaryOperator == ${Def.constants.operatorIs}) { }}\n            ${this.operatorIsSelect(true)}\n        {{ } else { }}\n            ${this.emptyRuleValueInput().replace('value=""', 'value="{{- primaryValue }}"')}\n        {{ } }}`;
        }
        $primaryOperatorOptions() {
            let html = "";
            Def.constants.operators.forEach(function(option) {
                let attributes = 'value="' + option.id + '"';
                let extras = option.data;
                if (extras) {
                    Object.keys(extras).forEach(function(k) {
                        attributes += " data-" + k + '="' + extras[k].replace('"', "&quot;") + '"';
                    });
                }
                html += `<option ${attributes} {{- primaryOperator === ${option.id} ? 'selected' : '' }}>${option.text.replace("<", "&lt;").replace(">", "&gt;")}</option>`;
            });
            return html;
        }
        genderSelect(preSelectedWithMustache) {
            const options = Object.entries(Def.constants.genderOptions).map(([genderVal, genderStr]) => this.genderOption(genderVal, genderStr, preSelectedWithMustache)).join("");
            return `<select data-name="primaryValue" class="form-control">${options}</select>`;
        }
        genderOption(genderVal, genderStr, preSelectedWithMustache) {
            const attrs = preSelectedWithMustache ? `{{- primaryValue == ${genderVal} ? "selected" : "" }}` : "";
            return `<option value="${genderVal}" ${attrs}>${genderStr}</option>`;
        }
        operatorIsSelect(preSelectedWithMustache) {
            const select = `\n        <select data-name="primaryValue" class="form-control">\n            <option value="NULL">NULL</option>\n            <option value="NOT_NULL">NOT NULL</option>\n        </select>`;
            if (preSelectedWithMustache) {
                return select.replace('value="NULL"', 'value="NULL" {{- primaryValue === "NULL" ? "selected" : "" }}').replace('value="NOT_NULL"', 'value="NOT_NULL" {{- primaryValue === "NOT_NULL" ? "selected" : "" }}');
            }
            return select;
        }
        updateOperatorsAvailability() {
            const $primaryOperatorSelect = this.$container.find('select[data-name="primaryOperator"]');
            _.forEach($primaryOperatorSelect.toArray(), operatorSelect => this.updateSelectOperatorsAvailability($(operatorSelect)));
            $primaryOperatorSelect.trigger("change.select2");
        }
        updateSelectOperatorsAvailability($operatorSelect) {
            const currentProfileField = this.currentProfileField;
            const fieldType = this.profileFieldsTypes[currentProfileField];
            const optionsToDisable = $operatorSelect.children("option").toArray().filter(option => this.isAllowedOperatorsOption(option, fieldType)).map(option => option.value);
            AGN.Lib.Select.get($operatorSelect).disableOptions(optionsToDisable, true);
        }
        isAllowedOperatorsOption(option, fieldType) {
            if (this.currentProfileFieldIsGender) {
                return option.text !== "=" && option.text !== "<>";
            }
            const types = $(option).data("types");
            if (types === "*" || !types) {
                return false;
            }
            return !types.split(/[\s,]+/).includes(fieldType);
        }
        updateValueInput($primaryOperator) {
            const $primaryValue = $primaryOperator.closest("tr").find('[data-name="primaryValue"]');
            if ($primaryOperator.val() === Def.constants.operatorIs) {
                const $operatorIsSelect = $(this.operatorIsSelect());
                $primaryValue.closest("td").html($operatorIsSelect);
                $primaryOperator.data("previous-value", Def.constants.operatorIs);
                this.#initSelect($operatorIsSelect);
            } else if ($primaryOperator.data("previous-value") === Def.constants.operatorIs) {
                $primaryValue.closest("td").html(this.emptyRuleValueInput());
                $primaryOperator.removeData("previous-value");
            }
        }
        onProfileFieldChanged() {
            this.updateOperatorsAvailability();
            if (this.currentProfileFieldIsGender) {
                this.changeValueInputsToGenderSelect();
                this.$profileFieldSelect.data("previous-value", Def.GENDER_PROFILE_FIELD);
            } else if (this.$profileFieldSelect.data("previous-value") === Def.GENDER_PROFILE_FIELD) {
                this.changeValueInputsToTextInput();
                this.$profileFieldSelect.removeData("previous-value");
            }
        }
        changeValueInputsToGenderSelect() {
            _.each(this.$container.find('[data-name="primaryValue"]'), primaryValue => {
                const $genderSelect = $(this.genderSelect());
                $(primaryValue).closest("td").html($genderSelect);
                this.#initSelect($genderSelect);
            });
        }
        changeValueInputsToTextInput() {
            _.each(this.$container.find('[data-name="primaryValue"]'), primaryValue => {
                $(primaryValue).closest("td").html(this.emptyRuleValueInput());
            });
        }
        #initSelect($select) {
            AGN.Lib.CoreInitializer.run("select", $select);
        }
    }
    AGN.Lib.WM.FieldRulesTable = FieldRulesTable;
})();

(function() {
    const EditorsHelper = AGN.Lib.WM.EditorsHelper;
    class NodeEditor {
        constructor() {
            if (this.constructor === NodeEditor) {
                throw new Error("Cannot instantiate abstract class");
            }
        }
        get saveOnOpen() {
            return false;
        }
        get $form() {
            return $(`form[name="${this.formName}"]`);
        }
        get form() {
            return AGN.Lib.Form.get(this.$form);
        }
        get formName() {
            throw new Error("formName() must be implemented");
        }
        $find(selector) {
            return $(`form[name="${this.formName}"] ${selector}`);
        }
        toggle(selector, show) {
            this.$find(selector).toggle(show);
        }
        hide(selector) {
            this.toggle(selector, false);
        }
        show(selector) {
            this.toggle(selector, true);
        }
        dateAsUTC(date) {
            return date ? new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate())) : null;
        }
        getForwardParams(elemSelector) {
            return {
                nodeId: EditorsHelper.curEditingNode.getId(),
                elementId: encodeURIComponent(elemSelector)
            };
        }
        getForwardParamsStr() {
            return Object.entries(this.getForwardParams()).map(([key, value]) => `${encodeURIComponent(key)}=${encodeURIComponent(value)}`).join(";");
        }
        isValid() {
            return this.form.validate();
        }
        save() {
            if (this.isValid()) {
                EditorsHelper.saveCurrentEditorWithUndo();
            }
        }
        alwaysReadonly(node) {
            return false;
        }
    }
    AGN.Lib.WM.NodeEditor = NodeEditor;
})();

(function() {
    const EditorsHelper = AGN.Lib.WM.EditorsHelper;
    const Messages = AGN.Lib.Messages;
    const Def = AGN.Lib.WM.Definitions;
    class RecipientTransferEditor extends AGN.Lib.WM.NodeEditor {
        constructor(conf) {
            super();
            this.conf = conf;
            this.safeToSave = true;
        }
        get formName() {
            throw new Error("formName() must be implemented");
        }
        get $idSelect() {
            return this.$find("select[name=importexportId]");
        }
        get selectedId() {
            return this.$idSelect.val();
        }
        get type() {
            throw new Error("type() must be implemented");
        }
        get $editor() {
            throw new Error("$editor() must be implemented");
        }
        fillEditor(node) {
            const data = node.getData();
            this.$form.submit(false);
            this.$form.get(0).reset();
            EditorsHelper.fillFormFromObject(this.formName, data, "");
            this.addLinks();
            if (this.conf.isDisabled === "true") {
                Messages.warn(this.missingPermissionMsgCode);
            }
            this.isValid();
        }
        get missingPermissionMsgCode() {
            throw new Error("missingPermissionMsgCode() must be implemented");
        }
        get dependencyType() {
            throw new Error("dependencyType() must be implemented");
        }
        get inUseMsgCode() {
            throw new Error("inUseMsgCode() must be implemented");
        }
        get notSelectedMsgCode() {
            throw new Error("notSelectedMsgCode() must be implemented");
        }
        isValidDependency() {
            let valid = false;
            $.ajax({
                url: AGN.url("/workflow/validateDependency.action"),
                async: false,
                data: {
                    workflowId: Def.workflowId || 0,
                    type: this.dependencyType,
                    entityId: this.selectedId
                }
            }).done(data => {
                if (data.valid === true) {
                    valid = true;
                } else {
                    Messages.warn(this.inUseMsgCode);
                }
            }).fail(() => {
                Messages.warn("Error");
            });
            return valid;
        }
        isValid() {
            return super.isValid() && this.isValidDependency();
        }
        save() {
            if (this.conf.isDisabled === "true") {
                return;
            }
            super.save();
        }
        onChange() {
            this.addLinks();
        }
        addLinks() {
            throw new Error("addLinks() must be implemented");
        }
        saveEditor() {
            return EditorsHelper.formToObject(this.formName);
        }
        isSetFilledAllowed() {
            const $option = this.$idSelect.find(":selected");
            return !(this.selectedId == 0 || $option.data("is-available") != true);
        }
    }
    AGN.Lib.WM.RecipientTransferEditor = RecipientTransferEditor;
})();

(() => {
    const MailingSelector = AGN.Lib.WM.MailingSelector;
    const FieldRulesTable = AGN.Lib.WM.FieldRulesTable;
    const EditorsHelper = AGN.Lib.WM.EditorsHelper;
    const DateTimeUtils = AGN.Lib.WM.DateTimeUtils;
    const Template = AGN.Lib.Template;
    const Messages = AGN.Lib.Messages;
    const Select = AGN.Lib.Select;
    const Def = AGN.Lib.WM.Definitions;
    class StartStopNodeEditor extends AGN.Lib.WM.NodeEditor {
        constructor(editor, config, submitWorkflowForm) {
            super();
            this.editor = editor;
            this.config = config;
            this.submitWorkflowForm = submitWorkflowForm;
            this.startMailingSelector = new MailingSelector(config.form, config.selectedName, config.noMailingOption);
            this.isStartEditor = false;
            this.timePattern = /^(\d{2}):(\d{2})$/;
        }
        get saveOnOpen() {
            return true;
        }
        get formName() {
            return "startForm";
        }
        get title() {
            return this.isStartEditor ? t("workflow.start.title") : t("workflow.stop.title");
        }
        get $endTypeSelect() {
            return this.$find('[name="endType"]');
        }
        get endTypeSelect() {
            return Select.get(this.$endTypeSelect);
        }
        get $rulesContainer() {
            return this.$find("#profileFieldRules");
        }
        get requiredMsg() {
            return t("fields.required.errors.missing");
        }
        getStartStopDate(data) {
            data = data || EditorsHelper.formToObject(this.formName);
            if (this.isStartEditor) {
                switch (data.startType) {
                  case Def.constants.startTypeDate:
                    return this.$find("#startDate").datepicker("getDate");

                  case Def.constants.startTypeEvent:
                    return this.$find("#executionDate").datepicker("getDate");
                }
            } else if (data.endType == Def.constants.endTypeDate) {
                return this.$find("#startDate").datepicker("getDate");
            }
            return null;
        }
        generateReminderComment() {
            const name = $('#workflowForm input[name="shortname"]').val();
            const dateString = DateTimeUtils.getDateStr(this.getStartStopDate(), window.adminDateFormat);
            return (this.isStartEditor ? t("workflow.start.reminder_text") : t("workflow.stop.reminder_text")).replace(/:campaignName/g, name).replace(/:startDate/g, dateString).replace(/:endDate/g, dateString);
        }
        fillEditor(node) {
            var data = node.getData();
            this.isStartEditor = node.getType() === "start";
            const showStartEventOption = this.isStartEditor && (node.data.startType === Def.constants.startTypeEvent || !this.editor.isAutoOptimizationWorkflow(node));
            this.updateEditorType(this.isStartEditor, showStartEventOption);
            this.$form.submit(false);
            this.$find("#remindCalendarDateTitle").text(t(this.isStartEditor ? "workflow.start.start_date" : "workflow.stop.end_date"));
            data.adminTimezone = this.config.adminTimezone;
            data.sendReminder = data.scheduleReminder;
            EditorsHelper.fillFormFromObject(this.formName, data, "");
            this.startMailingSelector.setMailingId(data.mailingId);
            this.startMailingSelector.cleanOptions();
            this.#updateMailingEditBtn(data.mailingId);
            const currentDate = new Date;
            this.$find("#startDate").datepicker("setDate", this.dateAsUTC(data.date ?? currentDate));
            this.$find("#executionDate").datepicker("setDate", this.dateAsUTC(data.date ?? currentDate));
            this.$find("#remindDate").datepicker("setDate", this.dateAsUTC(data.remindDate ?? currentDate));
            const timeData = data.date ? data : DateTimeUtils.getCurrentAdminTime();
            this.$find("#startTime").val(this.formatTime(timeData.hour, timeData.minute));
            this.$find("#remindTime").val(this.formatTime(timeData.remindHour, timeData.remindMinute));
            this.updateVisibility();
            if (data.startType == Def.constants.startTypeEvent && data.event == Def.constants.startEventReaction && data.reaction == Def.constants.reactionClickedLink && data.mailingId != 0 && data.mailingId != null) {
                this.onMailingSelectChange(data.mailingId, data.linkId);
            }
            if (!data.comment) {
                this.$find("#reminderComment").val(this.generateReminderComment());
            }
            Select.get($('#start-editor [name="userType"]')).selectOption(data.recipients != "" ? 2 : 1);
            this.$find('select[name="recipients"]').on("select2:selecting", e => {
                const email = $(e.target).find("option:last-child").val();
                if (AGN.Lib.Helpers.isValidEmail(email)) {
                    return true;
                }
                AGN.Lib.Messages.warn(t("error.workflow.cantAddInvalidEmailToTheList", email));
                e.preventDefault();
            });
            this.form.cleanFieldFeedback();
            const forceAutomaticEndType = !this.isStartEditor && this.editor.isAllLinkedFilledStartsHasDateType(node);
            if (forceAutomaticEndType) {
                this.endTypeSelect.selectOption(Def.constants.endTypeAutomatic);
            }
            this.endTypeSelect.setReadonly(forceAutomaticEndType);
            this.rulesTable = new FieldRulesTable(this.$rulesContainer, data.rules, EditorsHelper.isReadOnlyMode(), this.config.profileFields);
        }
        #updateMailingEditBtn(mailingId) {
            const $btn = $("#edit-start-editor-mailing-btn");
            $btn.toggleClass("hidden", !mailingId);
            if (mailingId) {
                $btn.attr("href", AGN.url(`/mailing/${mailingId}/settings.action`));
            }
        }
        editMailing() {
            const elementId = `form[name="${this.formName}"] select[name=mailingId]`;
            $("#forwardTargetItemId").val($(elementId).val());
            EditorsHelper.processForward(Def.constants.forwards.MAILING_EDIT.name, elementId, this.submitWorkflowForm);
        }
        saveEditor() {
            const data = EditorsHelper.formToObject(this.formName);
            data.date = this.getStartStopDate(data);
            if (data.date == null) {
                data.date = new Date;
                data.date.setHours(0);
                data.date.setMinutes(0);
                data.date.setSeconds(0);
                data.date.setMilliseconds(0);
            }
            var match;
            var startTime = this.$find("#startTime").val();
            if (match = this.timePattern.exec(startTime)) {
                data.hour = match[1];
                data.minute = match[2];
            } else {
                data.hour = 0;
                data.minute = 0;
            }
            data.scheduleReminder = data.sendReminder;
            var remindTime = this.$find("#remindTime").val();
            if (match = this.timePattern.exec(remindTime)) {
                data.remindHour = match[1];
                data.remindMinute = match[2];
            } else {
                data.remindHour = 0;
                data.remindMinute = 0;
            }
            if (this.$find('[name="remindSpecificDate"]').val() === "true") {
                data.remindDate = this.$find("#remindDate").datepicker("getDate");
            } else {
                data.remindDate = data.date;
                data.remindHour = 0;
                data.remindMinute = 0;
            }
            if (data.rules == undefined) {
                data.rules = [];
            }
            if (data.linkId == undefined || data.linkId == null) {
                data.linkId = 0;
            }
            if (data.dateFieldOperator != this.config.equelsOperatorCode) {
                data.dateFieldOperator = this.config.equelsOperatorCode;
            }
            if (data.userType == 2) {
                data.remindAdminId = 0;
                data.recipients = $.trim(data.recipients).toLowerCase().split(/[,;\s\n\r]+/).filter(address => !!address).join(", ");
            } else {
                data.recipients = "";
            }
            delete data.userType;
            data.rules = this.rulesTable.collect();
            return data;
        }
        validateEditorInternal(showErrors) {
            const self = this;
            let valid = true;
            const type = this.isStartEditor ? this.$find('select[name="startType"]').val() : this.$find('select[name="endType"]').val();
            if (this.isStartEditor && type === Def.constants.startTypeEvent) {
                validateStartEvent();
                validateStartDate();
            }
            if (this.isStartEditor && type === Def.constants.startTypeDate || !this.isStartEditor && type === Def.constants.endTypeDate) {
                validateStartDate();
            }
            if (valid && this.$find("#sendReminder").is(":checked")) {
                if (this.$find('[name="userType"]').val() == "2") {
                    validateReminderRecipients();
                }
            }
            if (valid) {
                this.form.cleanFieldFeedback();
            }
            return valid;
            function validateStartEvent() {
                var event = self.$find('select[name="event"]').val();
                switch (event) {
                  case Def.constants.startEventDate:
                    var executionDate = self.$find("#executionDate").datepicker("getDate");
                    if (executionDate) {
                        var startTime = self.$find("#startTime").val();
                        if (!self.timePattern.test(startTime)) {
                            valid = false;
                        }
                    } else {
                        valid = false;
                    }
                    var dateFieldValue = self.$find("#dateFieldValue");
                    if (!$.trim(dateFieldValue.val())) {
                        valid = false;
                        if (showErrors) {
                            Messages.warn("error.workflow.startDateOmitted");
                        }
                    }
                    const $dateProfileField = self.$find("#dateProfileField");
                    if (!$.trim($dateProfileField.val())) {
                        valid = false;
                        if (showErrors) {
                            self.form.showFieldError("dateProfileField", self.requiredMsg);
                        }
                    }
                    break;

                  case Def.constants.startEventReaction:
                    var reaction = self.$find('select[name="reaction"]').val();
                    switch (reaction) {
                      case Def.constants.reactionClickedLink:
                        const linkId = self.$find('select[name="linkId"]').val();
                        if (!linkId || parseInt(linkId, 10) <= 0) {
                            valid = false;
                            if (showErrors) {
                                Messages.warn("error.workflow.noLinkSelected");
                            }
                        }

                      case Def.constants.reactionOpened:
                      case Def.constants.reactionClicked:
                        const mailingId = self.$find('select[name="mailingId"]').val();
                        if (parseInt(mailingId, 10) <= 0) {
                            valid = false;
                            if (showErrors) {
                                Messages.warn("error.workflow.noMailing");
                            }
                        }
                        break;

                      case Def.constants.reactionChangeOfProfile:
                        if (typeof self.config.isBigData != "undefined" && self.config.isBigData == true) {
                            var profileField = self.$find('select[name="profileField"]').val();
                            if (!profileField) {
                                valid = false;
                            }
                        }
                        const $startProfileField = self.$find("#startProfileField");
                        if (!$.trim($startProfileField.val())) {
                            valid = false;
                            if (showErrors) {
                                self.form.showFieldError("profileField", self.requiredMsg);
                            }
                        }
                        break;

                      case Def.constants.reactionWaitingForConfirm:
                      case Def.constants.reactionOptIn:
                      case Def.constants.reactionOptOut:
                        break;

                      default:
                        valid = false;
                        break;
                    }
                    break;
                }
            }
            function validateStartDate() {
                var startDate = self.$find("#startDate").datepicker("getDate");
                if (startDate) {
                    var startTime = self.$find("#startTime").val();
                    if (!self.timePattern.test(startTime)) {
                        valid = false;
                    }
                } else {
                    valid = false;
                }
            }
            function validateReminderRecipients() {
                const emails = self.$find('select[name="recipients"]').val();
                if (emails.length) {
                    if (!AGN.Lib.Helpers.isValidEmails(emails)) {
                        valid = false;
                        if (showErrors) {
                            self.form.showFieldError("recipients", t("error.workflow.wrongEmail"));
                        }
                    }
                } else if (showErrors) {
                    valid = false;
                    Messages.warn("error.workflow.emptyRecipientList");
                }
            }
        }
        isValid() {
            return this.validateEditorInternal(true) && super.isValid();
        }
        isSetFilledAllowed() {
            return this.validateEditorInternal(false);
        }
        updateEditorType(isStartEditor, showStartEventOption) {
            const $type = $("#startStopType");
            $type.empty();
            if (isStartEditor) {
                $type.append(Template.text("start-types", {
                    showStartEventTab: showStartEventOption
                }));
                $("#eventReaction").html(t("workflow.start.reaction_based"));
                $("#eventDate").html(t("workflow.start.date_based"));
            } else {
                $type.append(Template.text("stop-types"));
                if (this.checkPresentNodeOfType([ Def.NODE_TYPE_ACTION_BASED_MAILING, Def.NODE_TYPE_DATE_BASED_MAILING ])) {
                    $("#endTypeAutomaticLabel").html(t("workflow.stop.open_end"));
                } else {
                    $("#endTypeAutomaticLabel").html(t("workflow.stop.automatic_end"));
                }
            }
        }
        onStartTypeChanged() {
            const $startIconTime = this.$find("#startIconTime");
            const value = this.isStartEditor ? this.$find('select[name="startType"]').val() : this.$find('select[name="endType"]').val();
            if (this.isStartEditor && value == Def.constants.startTypeDate || !this.isStartEditor && value == Def.constants.endTypeDate) {
                this.toggleFormat();
                this.hide("#startEventPanel");
                this.show("#startDatePanel");
                this.show("#startIconTime");
                this.$find("#startDatePanel .date-time-container").append($startIconTime);
                this.show("#startRemindAdmin");
            } else if (this.isStartEditor && value == Def.constants.startTypeEvent) {
                this.hide("#startDatePanel");
                this.$find("#executionDatePanel .date-time-container").append($startIconTime);
                this.show("#startEventPanel");
                this.show("#startIconTime");
                this.show("#startRemindAdmin");
                this.onStartEventChanged();
            } else if (this.isStartEditor && value == Def.constants.startTypeOpen || !this.isStartEditor && value == Def.constants.endTypeAutomatic) {
                this.hide("#startDatePanel");
                this.$find("#executionDatePanel .date-time-container").append($startIconTime);
                this.hide("#startEventPanel");
                this.hide("#startIconTime");
                this.hide("#startRemindAdmin");
            }
        }
        onStartEventChanged() {
            var event = $("#startEvent").val();
            if (event == Def.constants.startEventReaction) {
                this.toggleFormat();
                this.hide("#dateStartPanel");
                this.show("#reactionStartPanel");
                this.onExecutionChanged();
                this.onProfileFieldChanged();
            } else if (event == Def.constants.startEventDate) {
                this.toggleFormat();
                this.hide("#reactionStartPanel");
                this.show("#dateStartPanel");
                this.hide("#executionDateLabel");
                this.show("#firstExecutionDateLabel");
                $("#startIconDateFormat").insertAfter("#startIconDateFieldOperator");
                this.show("#startIconDateFormat");
            }
        }
        toggleFormat() {
            this.$find("input#startTime").inputmask(this.isDateBasedStart ? "h:00" : "h:s");
        }
        get isDateBasedStart() {
            return this.$find("#start-type").val() === Def.constants.startTypeEvent && this.$find("select#startEvent").val() === Def.constants.startEventDate;
        }
        onRuleModeChanged() {
            this.toggle("#profileFieldRules", $('select[name="useRules"]').val() !== "false");
        }
        onProfileFieldChanged() {
            this.updateDateFormatVisibility();
            this.rulesTable?.onProfileFieldChanged();
        }
        updateDateFormatVisibility() {
            const profileField = this.$find('select[name="profileField"]').val();
            const fieldType = this.config.profileFields[profileField];
            if (fieldType && fieldType.toLowerCase() == Def.FIELD_TYPE_DATE) {
                $("#startIconDateFormat").insertAfter("#reactionProfileField");
                this.show("#startIconDateFormat");
            } else {
                this.hide("#startIconDateFormat");
            }
        }
        onExecutionChanged() {
            const value = this.$find('[name="executeOnce"]').val();
            this.toggle("#executionDateLabel", value !== "false");
            this.toggle("#firstExecutionDateLabel", value === "false");
        }
        onReactionChanged() {
            const selectedReaction = this.$find("#startReaction").val();
            if (selectedReaction == Def.constants.reactionOpened || selectedReaction == Def.constants.reactionNotOpened || selectedReaction == Def.constants.reactionClicked || selectedReaction == Def.constants.reactionNotClicked || selectedReaction == Def.constants.reactionBought || selectedReaction == Def.constants.reactionNotBought || selectedReaction == Def.constants.reactionClickedLink) {
                this.hide("#reactionStartProfile");
                this.show("#reactionStartMailing");
            } else if (selectedReaction == Def.constants.reactionChangeOfProfile) {
                this.hide("#reactionStartMailing");
                this.show("#reactionStartProfile");
            } else {
                this.hide("#reactionStartMailing");
                this.hide("#reactionStartProfile");
            }
            this.toggle("#reactionStartMailingLink", selectedReaction === Def.constants.reactionClickedLink);
        }
        onReminderChanged() {
            if (this.$find('input[name="sendReminder"]').is(":checked")) {
                this.$find("#reminderComment").val(this.generateReminderComment());
                this.show("#reminderDetails");
            } else {
                this.hide("#reminderDetails");
            }
            return false;
        }
        onScheduleReminderDateChanged() {
            this.toggle("#dateTimePicker", this.$find('select[name="remindSpecificDate"]').val() === "true");
            return false;
        }
        onMailingSelectChange(value, selectedValue) {
            const $linkSelect = this.$find('select[name="linkId"]');
            const mailingId = parseInt(value, 10);
            if (mailingId > 0) {
                $linkSelect.attr("readonly", "readonly");
                $.ajax({
                    url: AGN.url(`/mailing/ajax/${mailingId}/links.action`),
                    success: function(data) {
                        $linkSelect.empty();
                        $linkSelect.append($("<option></option>", {
                            value: "",
                            text: Def.EMPTY_OPTION_PLACEHOLDER
                        }));
                        $.each(data, function(index, itemUrl) {
                            $linkSelect.append($("<option></option>", {
                                value: itemUrl.id,
                                text: itemUrl.url
                            }));
                        });
                        $linkSelect.removeAttr("readonly");
                        if (selectedValue != null && selectedValue != undefined) {
                            $linkSelect.val(selectedValue);
                            EditorsHelper.initSelectWithValueOrChooseFirst($linkSelect, selectedValue);
                        } else {
                            EditorsHelper.initSelectWithFirstValue($linkSelect);
                        }
                    }
                });
            } else {
                $linkSelect.empty();
            }
            this.#updateMailingEditBtn(mailingId);
        }
        updateVisibility() {
            this.onStartTypeChanged();
            this.onStartEventChanged();
            this.onReactionChanged();
            this.onRuleModeChanged();
            this.onExecutionChanged();
            this.onReminderChanged();
            this.onScheduleReminderDateChanged();
        }
        formatTime(hours, minutes) {
            var h = 0;
            var m = 0;
            hours = parseInt(hours, 10);
            if (hours >= 0) {
                h = hours;
            }
            minutes = parseInt(minutes, 10);
            if (minutes >= 0) {
                m = minutes;
            }
            return (h < 10 ? "0" + h : h) + ":" + (m < 10 ? "0" + m : m);
        }
        checkPresentNodeOfType(types) {
            return EditorsHelper.getNodesByTypes(types).length > 0;
        }
    }
    AGN.Lib.WM.StartStopNodeEditor = StartStopNodeEditor;
})();

