(() => {
    const Def = AGN.Lib.WM.Definitions;
    const EditorsHelper = AGN.Lib.WM.EditorsHelper;
    const NodeTitleHelper = AGN.Lib.WM.NodeTitleHelper;
    class ArchiveNodeEditor extends AGN.Lib.WM.NodeEditor {
        constructor(submitWorkflowForm) {
            super();
            this.safeToSave = true;
            this._submitWorkflowForm = submitWorkflowForm;
        }
        get formName() {
            return "archiveNodeForm";
        }
        get title() {
            return t("workflow.mailing.archive");
        }
        get archiveSelectSelector() {
            return `#${this.formName} #settings_general_campaign`;
        }
        get archiveSelect() {
            return AGN.Lib.Select.get(this.$archiveSelect);
        }
        get $archiveSelect() {
            return $(this.archiveSelectSelector);
        }
        createNewArchive() {
            const forwardParams = this.#getCreateArchiveForwardParams();
            AGN.Lib.Confirm.request($.get(AGN.url(Def.constants.forwards.ARCHIVE_CREATE.url), {
                workflowId: Def.workflowId,
                workflowForwardParams: forwardParams
            })).done(({archiveId: archiveId, archiveName: archiveName}) => {
                this.#addArchiveOption(archiveId, archiveName);
                this.archiveSelect.selectOption(archiveId);
                EditorsHelper.saveCurrentEditorWithUndo();
                if (Def.workflowId === 0) {
                    _.defer(() => {
                        this._submitWorkflowForm(false, {
                            forwardParams: forwardParams,
                            forwardTargetItemId: archiveId
                        });
                    });
                } else {
                    AGN.Lib.Messages.defaultSaved();
                }
            });
        }
        #getCreateArchiveForwardParams() {
            const params = {
                nodeId: EditorsHelper.curEditingNode.getId()
            };
            return Object.entries(params).map(([key, value]) => `${encodeURIComponent(key)}=${encodeURIComponent(value)}`).join(";");
        }
        #addArchiveOption(id, name) {
            this.archiveSelect.addOption(id, name);
            NodeTitleHelper.addArchiveName(id, name);
        }
        fillEditor(node) {
            const data = node.getData();
            this.$form.submit(false);
            this.$form.get(0).reset();
            EditorsHelper.fillFormFromObject(this.formName, data, "");
            this.isValid();
        }
        saveEditor() {
            return EditorsHelper.formToObject(this.formName);
        }
    }
    AGN.Lib.WM.ArchiveNodeEditor = ArchiveNodeEditor;
})();

(function() {
    const EditorsHelper = AGN.Lib.WM.EditorsHelper;
    const Snippets = AGN.Lib.WM.Snippets;
    class SplitNodeEditor extends AGN.Lib.WM.NodeEditor {
        constructor(editor) {
            super();
            this.editor = editor;
            this.safeToSave = true;
        }
        get formName() {
            return "splitNodeForm";
        }
        get title() {
            return t("split.mailing");
        }
        fillEditor(node) {
            const data = node.getData();
            this.$form.submit(false);
            this.$form.get(0).reset();
            EditorsHelper.fillFormFromObject(this.formName, data, "");
            this.isValid();
        }
        saveEditor() {
            const formData = EditorsHelper.formToObject(this.formName);
            const splitIcon = EditorsHelper.curEditingNode;
            const oldSplitPortions = SplitNodeEditor.getSplitPortions(splitIcon.data.splitType);
            const newSplitPortions = SplitNodeEditor.getSplitPortions(formData.splitType);
            if (oldSplitPortions.length === newSplitPortions.length) {
                this.#updateParameterValues(splitIcon, newSplitPortions);
            } else {
                this.#updateSplitType(splitIcon, formData.splitType);
            }
            return formData;
        }
        #updateSplitType(splitIcon, splitType) {
            const splitIconPosition = {
                x: splitIcon.x,
                y: splitIcon.y
            };
            const splitIconIncomingNodes = EditorsHelper.getNodesByIncomingConnections(splitIcon);
            this.editor.deleteNode(splitIcon);
            Snippets.createSplitSample(splitType, this.editor.gridBackgroundShown, (nodes, connections) => {
                const splitNode = nodes.filter(node => node.isSplitNode)[0];
                const splitIconConnections = splitIconIncomingNodes.map(source => ({
                    source: source,
                    target: splitNode
                }));
                this.editor.newSnippet(nodes, [ ...connections, ...splitIconConnections ], splitIconPosition);
            });
        }
        #updateParameterValues(splitIcon, newSplitPortions) {
            this.editor.getSplitParameterNodes(splitIcon).forEach((parameterIcon, i) => this.editor._setParameterNodesValue([ parameterIcon ], newSplitPortions[i]));
        }
        static getSplitPortions(splitType) {
            return splitType.match(/.{1,2}/g).map(val => parseInt(val, 10));
        }
    }
    AGN.Lib.WM.SplitNodeEditor = SplitNodeEditor;
})();

(() => {
    const Def = AGN.Lib.WM.Definitions;
    const EditorsHelper = AGN.Lib.WM.EditorsHelper;
    class MailingNodeEditor extends AGN.Lib.WM.NodeEditor {
        constructor(mailingEditorBase) {
            super();
            this.safeToSave = true;
            this.mailingEditorBase = mailingEditorBase;
        }
        get formName() {
            return "mailingForm";
        }
        get title() {
            return t("workflow.defaults.mailing");
        }
        get $editor() {
            return $("#mailing-editor");
        }
        fillEditor(node) {
            this.$form.submit(false);
            this.$form.get(0).reset();
            EditorsHelper.fillFormFromObject(this.formName, node.getData(), "");
            this.mailingEditorBase.fillEditorBase(node);
        }
        createNewMailing() {
            this.mailingEditorBase.createNewMailing((mailingId, mailingName) => {
                this.mailingEditorBase.node.setFilled(true);
                const mailingSelect = this.mailingEditorBase.mailingSelect();
                mailingSelect.addOption(mailingId, mailingName);
                mailingSelect.selectOption(mailingId);
                this.mailingEditorBase.setSelectMailingOptions(mailingId);
            });
        }
        editMailing() {
            this.mailingEditorBase.editMailing(Def.constants.forwards.MAILING_EDIT.name);
        }
        saveEditor() {
            this.mailingEditorBase.setNodeFields();
            return EditorsHelper.formToObject(this.formName);
        }
        saveWithCheckStatus() {
            const isNotSent = this.mailingEditorBase.showSecurityQuestion();
            if (isNotSent) {
                EditorsHelper.saveCurrentEditorWithUndo(this.mailingEditorBase);
            }
        }
        copyMailing() {
            this.mailingEditorBase.copyMailing(Def.constants.forwards.MAILING_COPY.name);
        }
        save() {
            this.mailingEditorBase.validateEditor(() => this.saveWithCheckStatus());
        }
    }
    AGN.Lib.WM.MailingNodeEditor = MailingNodeEditor;
})();

