AGN.Lib.Controller.newExtended("grid-building-block-defaults", "building-block-view", function() {
    const Helpers = AGN.Lib.Helpers;
    const Confirm = AGN.Lib.Confirm;
    const Form = AGN.Lib.Form;
    let config;
    this.addDomInitializer("grid-building-block-defaults", function() {
        config = this.config;
        $("img[id^=preview]").each(function() {
            const $img = $(this);
            const src = $img.attr("src");
            if (src) {
                const newSrc = resolveAgnImageTags(src);
                if (newSrc !== src) {
                    $img.attr("src", $.trim(newSrc));
                }
            }
            $img.parent().removeClass("hidden");
        });
        controlCheckPhChildrenVisibility();
    });
    this.addAction({
        click: "chooseImage"
    }, function() {
        const phId = getPlaceholderId(this.el);
        if (phId > 0) {
            if (checkHasFileSelected(phId)) {
                $(`#file-${phId}`).trigger("click");
            } else {
                showMediapoolDialog(phId);
            }
        }
    });
    this.addAction({
        change: "chooseImageFile"
    }, function() {
        const phId = getPlaceholderId(this.el);
        if (phId > 0) {
            chooseImageFile(this.el, phId);
            updateDependentImageAltPhs(phId, "");
            updateDependentImageSourcePhs(phId, "");
        }
    });
    this.addAction({
        click: "deleteImage"
    }, function() {
        const phId = getPlaceholderId(this.el);
        if (phId > 0) {
            deleteImage(phId);
        }
    });
    this.addAction({
        click: "showMediapoolDialog"
    }, function() {
        const phId = getPlaceholderId(this.el);
        if (phId > 0) {
            showMediapoolDialog(phId);
        }
    });
    this.addAction({
        click: "chooseImageLink"
    }, function() {
        const phId = getPlaceholderId(this.el);
        if (phId > 0) {
            $(`#content-${phId}`).trigger("focus");
        }
    });
    this.addAction({
        change: "previewImageLink",
        keyup: "previewImageLink",
        mouseup: "previewImageLink"
    }, function() {
        const phId = getPlaceholderId(this.el);
        if (phId > 0) {
            updateImageLinkPreview(phId, $.trim(this.el.val()));
        }
    });
    this.addAction({
        click: "save"
    }, function() {
        ajaxImagesSave().done(() => Form.get($("#default-content-tile")).submit());
    });
    function resolveAgnImageTags(html) {
        return Helpers.replaceAgnTags(html, (tag, tagHtml) => {
            if (tag.name === "agnIMAGE" && tag.attributes["name"]) {
                if (!tag.attributes["source"] || tag.attributes["source"] === "mediapool" || tag.attributes["source"] === "mediapoolbg") {
                    return AGN.url(`/mediapool/${encodeURIComponent(tag.attributes["name"])}/raw.action`);
                }
            }
            return tagHtml;
        });
    }
    function controlCheckPhChildrenVisibility() {
        config.placeholders.filter(ph => ph.placeholderType === config.CHECK_PLACEHOLDER_TYPE).forEach(checkPh => {
            const $childrenContainer = $(`\n            <div id="${checkPh.placeholderId}-children" class="bordered-box-sm" data-show-by-checkbox="#content-${checkPh.placeholderId}">\n                <div class="row g-2"></div>\n            </div>\n        `);
            $childrenContainer.insertAfter($(`#content-${checkPh.placeholderId}`).parent());
            checkPh.options.split(",").forEach(phChildId => {
                $childrenContainer.find("> .row").append($(`.ph-${phChildId}`));
            });
        });
        AGN.Lib.CoreInitializer.run("checkbox-hider", $("#default-content-tile"));
    }
    function getPlaceholderId($element) {
        const $ph = $element.closest("[data-ph-id]");
        return $ph.exists() ? parseInt($ph.data("ph-id")) : 0;
    }
    function checkHasFileSelected(phId) {
        const $file = $(`#file-${phId}`);
        return $file.exists() ? !!$file.val() : false;
    }
    function showMediapoolDialog(phId) {
        Confirm.request(AGN.url("/mediapool/image/pick.action")).done(image => {
            $(`#content-${phId}`).val(image.id);
            Helpers.clearFormField($(`#file-${phId}`));
            updateImagePreview(phId, image.src, image.fileName, image.title);
            updateDependentImageAltPhs(phId, image.altText);
            updateDependentImageSourcePhs(phId, image.source);
        });
    }
    function chooseImageFile($file, phId) {
        const files = $file.prop("files");
        const $content = $(`#content-${phId}`);
        const $categoryBlock = $(`#image-category-${phId}`).parent();
        if (files?.length) {
            const file = files[0];
            if (file.type === "image" || file.type.match("image/.*")) {
                const reader = new FileReader;
                reader.onload = e => {
                    $categoryBlock.removeClass("hidden");
                    updateImagePreview(phId, e.target.result, file.name, file.name);
                };
                reader.readAsDataURL(file);
            } else {
                $categoryBlock.addClass("hidden");
                Helpers.clearFormField($file);
                updateImagePreview(phId);
            }
        } else {
            $categoryBlock.addClass("hidden");
            updateImagePreview(phId);
        }
        $content.val("");
    }
    function updateImagePreview(phId, src, name, title) {
        const $img = $(`#preview-${phId}`);
        const $name = $(`#image-name-${phId}`);
        if ($img.attr("src") !== src) {
            $img.attr("src", src || config.noPreviewImageLink);
        }
        $img.attr("title", title || "");
        $name.text(name || "");
    }
    const updateImageLinkPreview = _.throttle((phId, src) => {
        const $img = $(`#preview-${phId}`);
        if ($img.attr("src") !== src) {
            if (src) {
                $img.attr("src", $.trim(resolveAgnImageTags(src)));
            } else {
                $img.attr("src", src || config.noPreviewImageLink);
            }
        }
    }, 300);
    function deleteImage(phId) {
        Helpers.clearFormField($(`#file-${phId}`));
        $(`#image-name-${phId}`).text("");
        $(`#content-${phId}`).val("");
        $(`#preview-${phId}`).attr("src", config.noPreviewImageLink);
        updateDependentImageAltPhs(phId, "");
        updateDependentImageSourcePhs(phId, "");
    }
    function updateDependentImageAltPhs(phId, value) {
        findDependentPhs(phId, config.IMAGE_ALT_PLACEHOLDER_TYPE).forEach(altPh => $(`.ph-${altPh.placeholderId} input`).val(value));
    }
    function updateDependentImageSourcePhs(phId, value) {
        findDependentPhs(phId, config.IMAGE_SOURCE_PLACEHOLDER_TYPE).forEach(srcPh => $(`.ph-${srcPh.placeholderId} input`).val(value));
    }
    function findDependentPhs(phId, type) {
        const ph = config.placeholders.find(_ph => _ph.placeholderId === phId);
        return config.placeholders.filter(_ph => _ph.placeholderType === type && _ph.placeholderName === ph.placeholderName);
    }
    function ajaxImagesSave() {
        const deferred = $.Deferred();
        const entries = [];
        const form = Form.get($("#default-content-tile"));
        let valid = true;
        form.get$().find("input[type=file]").each(function() {
            const $file = $(this);
            const phId = getPlaceholderId($file);
            const $category = $(`#image-category-${phId}`);
            const files = $file.prop("files");
            if (files?.length) {
                const categoryId = $category.val();
                if (categoryId > 0) {
                    entries.push({
                        placeholderId: phId,
                        image: files[0],
                        categoryId: categoryId
                    });
                    form.cleanFieldFeedback($category);
                } else {
                    valid = false;
                    form.showFieldError$($category, t("error.grid.noCategorySelected"));
                }
            } else {
                form.cleanFieldFeedback($category);
            }
        });
        if (valid) {
            if (entries.length) {
                const data = new FormData;
                entries.forEach((e, index) => {
                    data.append(`uploads[${index}].file`, e.image);
                    data.append(`uploads[${index}].fileName`, e.image.name);
                    data.append(`uploads[${index}].title`, e.image.name);
                    data.append(`uploads[${index}].categoryId`, e.categoryId);
                });
                $.ajax(AGN.url("/mediapool/upload.action?asJson=true"), {
                    type: "POST",
                    dataType: "json",
                    enctype: "multipart/form-data",
                    processData: false,
                    contentType: false,
                    data: data
                }).done(resp => {
                    if (resp.success === true) {
                        entries.forEach(entry => {
                            const imageId = resp.data[entry.image.name] || 0;
                            const placeholderId = entry.placeholderId;
                            $(`#content-${placeholderId}`).val(imageId);
                            Helpers.clearFormField($(`#file-${placeholderId}`));
                        });
                        deferred.resolve();
                    } else {
                        AGN.Lib.JsonMessages(resp.popups);
                        deferred.reject();
                    }
                }).fail(() => deferred.reject());
            } else {
                deferred.resolve();
            }
        } else {
            deferred.reject();
        }
        return deferred.promise();
    }
});

AGN.Lib.Controller.new("building-block-view", function() {
    const Template = AGN.Lib.Template;
    const Form = AGN.Lib.Form;
    this.addDomInitializer("building-block-view", function() {
        const table = $('[data-action="load-refTable-cols"]').val();
        loadReferenceTablePlaceholders(table);
    });
    this.addAction({
        change: "load-refTable-cols"
    }, function() {
        Form.get(this.el).validate();
        loadReferenceTablePlaceholders(this.el.val());
    });
    function loadReferenceTablePlaceholders(table) {
        if (!table) {
            return;
        }
        $.get(AGN.url(`/administration/table/${table}/columns.action`)).done(columns => $("#ref-table-placeholders").empty().append(columns.map(column => getRefTablePlaceholderRow(column))));
    }
    function getRefTablePlaceholderRow(column) {
        const $row = Template.dom("ref-table-placeholder", {
            column: column
        });
        [ "LABEL", "TEXT", "LINK", "IMAGE" ].forEach(type => $row.append(Template.dom("ref-table-placeholder-copy-btn", {
            column: column,
            type: type
        })));
        $row.find("[data-copyable]").on({
            mouseenter: function() {
                updatePlaceholderText($(this), column);
            }
        });
        return $row;
    }
    function updatePlaceholderText($btn, column) {
        const $input = $(`#ref-col-${column}-ph`);
        let updated = $input.val().replace(/type="[^"]*"/, 'type="' + $btn.data("ph-type") + '"');
        $input.val(updated);
    }
    this.addAction({
        click: "activate"
    }, function() {
        changeActivation(true, this.el);
    });
    this.addAction({
        click: "deactivate"
    }, function() {
        changeActivation(false, this.el);
    });
    function changeActivation(activate, $el) {
        const $toggles = $("[data-building-block-activeness-toggle]");
        $toggles.addClass("disabled");
        $.post($el.data("url")).done(resp => {
            if (resp.success) {
                $el.toggleClass("hidden", true);
                $toggles.not($el).toggleClass("hidden", false);
                updateIndicators(activate);
                $("#building-block-delete-option").toggleClass("hidden", activate);
            }
            AGN.Lib.JsonMessages(resp.popups);
            $toggles.removeClass("disabled");
        });
    }
    function updateIndicators(activate) {
        const $indicators = $("[data-building-block-activeness-indicator]");
        $indicators.addClass("hidden");
        $indicators.not($(`[data-building-block-activeness-indicator="${!activate}"]`)).removeClass("hidden");
    }
});

