AGN.Lib.Controller.new("grid-edit", function() {
    const Template = AGN.Lib.Template;
    let config;
    let form;
    this.addDomInitializer("grid-edit", function() {
        config = this.config;
        form = AGN.Lib.Form.get($("#gridForm"));
        updateViews();
    });
    this.addAction({
        submission: "createTemplate"
    }, function() {
        $("#templateCreationForm").submit();
    });
    this.addAction({
        submission: "saveGrid"
    }, function() {
        form.submit();
    });
    this.addAction({
        change: "updateColnum"
    }, function() {
        validateRequiredNumber(this.el, 1, config.maxColumnsCount);
        $getInput("columnWidth").val(calculateColumnWidth());
        updateViews();
    });
    this.addAction({
        change: "updateTemplateWidth"
    }, function() {
        validateRequiredNumber(this.el, 50, 2e3);
        $getInput("columnWidth").val(calculateColumnWidth());
        updateViews();
    });
    this.addAction({
        change: "updateColumnWidth"
    }, function() {
        validateRequiredNumber(this.el, 10, 2e3);
        $getInput("templateWidth").val(calculateTemplateWidth());
        updateViews();
    });
    this.addAction({
        change: "updateGutterWidth"
    }, function() {
        validateRequiredNumber(this.el, 0, 500);
        $getInput("columnWidth").val(calculateColumnWidth());
        updateViews();
    });
    this.addAction({
        click: "enableEditing"
    }, function() {
        $(this.el).prop("disabled", true);
        $getInput("gridName").prop("disabled", false);
        if (!config.isGridInUse) {
            $.each([ "columnNum", "columnWidth", "gutter", "templateWidth" ], (index, name) => {
                $getInput(name).prop("disabled", false);
            });
        }
        $("#createTemplateButton").addClass("hidden");
        $("#saveAndCreateTemplateButton").removeClass("hidden");
        form.get$().attr("data-action", "saveGrid");
    });
    function validateRequiredNumber(el, min, max) {
        const val = parseInt(el.val());
        if (val != el.val() || val < min) {
            el.val(min);
        }
        if (val > max) {
            el.val(max);
        }
    }
    function updateViews() {
        const columnWidth = getColumnWidth();
        const columnsCount = getColumnsCount();
        const gutter = getGutterWidth();
        const $preview = $("#grid-preview-block");
        $preview.html(Template.text("lb-grid-columns-preview", {
            columnsCount: columnsCount,
            columnWidth: columnWidth,
            gutter: gutter
        }));
        for (let i = 0; i < columnsCount; i++) {
            const firstBlockWidth = i + 1;
            $preview.append(Template.text("lb-grid-row-preview", {
                columnsCount: columnsCount,
                firstBlockWidth: firstBlockWidth,
                columnWidth: columnWidth,
                gutter: gutter,
                percent: Math.floor(firstBlockWidth * 100 / columnsCount)
            }));
        }
    }
    function calculateColumnWidth() {
        return Math.floor(getTemplateWidth() / getColumnsCount() - getGutterWidth());
    }
    function calculateTemplateWidth() {
        return Math.ceil((getColumnWidth() + getGutterWidth()) * getColumnsCount());
    }
    function getColumnsCount() {
        return getIntInputValue("columnNum");
    }
    function getColumnWidth() {
        return getIntInputValue("columnWidth");
    }
    function getGutterWidth() {
        return getIntInputValue("gutter");
    }
    function getTemplateWidth() {
        return getIntInputValue("templateWidth");
    }
    function getIntInputValue(name) {
        return parseInt($getInput(name).val());
    }
    function $getInput(name) {
        return form.get$().find(`[name='${name}']`);
    }
});

