AGN.Lib.Controller.newExtended("grid-template-css", "grid-template-base", function() {
    let previewWidths = [];
    let previewMediaQueries = [];
    let $previewSize;
    let previewForm;
    this.addDomInitializer("grid-template-css", function() {
        previewWidths = this.config.previewWidths;
        previewMediaQueries = this.config.previewMediaQueries;
        previewForm = AGN.Lib.Form.get($("#layoutPreviewForm"));
        $previewSize = $('[name="previewSize"]');
        AGN.Lib.Storage.restoreChosenFields($previewSize);
        refreshPreview();
    });
    this.addAction({
        change: "update-css-preview",
        click: "refresh-preview"
    }, function() {
        AGN.Lib.Storage.saveChosenFields($previewSize);
        previewForm.setValue("css", $("#cssContents").val());
        refreshPreview();
    });
    function refreshPreview() {
        const previewSize = parseInt($previewSize.val());
        updateIframe$(previewSize);
        setPreviewSizeToForm(previewSize);
        previewForm.submit();
    }
    function updateIframe$(previewSize) {
        const $iframe = AGN.Lib.Template.dom("template-css-iframe", {
            previewWidth: previewWidths[previewSize],
            mediaQuery: previewMediaQueries[previewSize]
        });
        $previewSize.closest(".tile").find(".tile-body").html($iframe);
        AGN.Lib.CoreInitializer.run("iframe");
    }
    function setPreviewSizeToForm(previewSize) {
        if (previewForm.getValue("previewSize") === undefined) {
            previewForm.setValueOnce("previewSize", previewSize);
        } else {
            previewForm.setValue("previewSize", previewSize);
        }
    }
});

AGN.Lib.Controller.newExtended("grid-template-settings", "grid-template-base", function() {
    const Messages = AGN.Lib.Messages;
    let lastSelectedTargetsIds = [];
    let mailinglists = [];
    this.addDomInitializer("grid-template-settings", function() {
        lastSelectedTargetsIds = $("#targetGroupSelect").val() || [];
        displayTargetModeToggle(lastSelectedTargetsIds.length > 1);
        mailinglists = this.config.mailinglists;
    });
    this.addAction({
        submission: "save"
    }, function() {
        const form = AGN.Lib.Form.get(this.el);
        setParamsToForm(form);
        form.submit();
    });
    function setParamsToForm(form) {
        const $mailingParamsTable = $("#mailingParamsTable");
        if (!$mailingParamsTable.exists()) {
            return;
        }
        _.each($mailingParamsTable.data("table").collect(), (param, index) => {
            form.setValueOnce(`settings.parameters[${index}].name`, param.name);
            form.setValueOnce(`settings.parameters[${index}].value`, param.value);
            form.setValueOnce(`settings.parameters[${index}].description`, param.description);
        });
    }
    this.addAction({
        change: "selectTargetGroups"
    }, function() {
        const newTargetIds = this.el.val() || [];
        if (newTargetIds.length > 1 && lastSelectedTargetsIds.length <= 1) {
            $("#recipientHasToBeInAllTargets").prop("checked", true);
        }
        displayTargetModeToggle(newTargetIds.length > 1);
        lastSelectedTargetsIds = newTargetIds;
    });
    function displayTargetModeToggle(show) {
        const $targetModeBox = $("#target-mode-box");
        $targetModeBox.toggle(show);
        $("#regular-targets-box").toggleClass("border rounded p-2", show && $targetModeBox.is(":visible"));
    }
    function updateSenderAndReplyToFields(mailinglistId) {
        const mailinglist = mailinglists.find(data => data.id === +mailinglistId);
        if (!mailinglist) {
            return;
        }
        const changedLabels = [ {
            value: mailinglist.senderEmail,
            $field: $("#sender-email")
        }, {
            value: mailinglist.replyEmail,
            $field: $("#reply-email")
        }, {
            value: mailinglist.senderName,
            $field: $("#sender-name")
        }, {
            value: mailinglist.replyToName,
            $field: $("#reply-name")
        } ].filter(({value: value, $field: $field}) => value && $field.val() !== value).map(({value: value, $field: $field}) => {
            $field.val(value).trigger("change");
            return $(`label[for="${$field.attr("id")}"]`).text().trim().replaceAll(/\s*\*/g, "");
        });
        if (changedLabels.length) {
            Messages.info("mailing.default.sender_and_reply_emails_changed");
        }
    }
    this.addAction({
        change: "select-mailinglist"
    }, function() {
        updateSenderAndReplyToFields(this.el.val());
    });
});

