AGN.Lib.Controller.new("mailing-bounce-stats", function() {
    const Table = AGN.Lib.Table;
    const ProcessingLoader = AGN.Lib.ProcessingLoader;
    const Form = AGN.Lib.Form;
    const Select = AGN.Lib.Select;
    const Template = AGN.Lib.Template;
    let data;
    let config;
    const toAgGridRows = data => {
        const targetIds = _.keys(data);
        const bounces = _.keys(data[targetIds[0]]);
        const rows = bounces.map(detail => {
            const row = {
                detail: detail
            };
            _.each(data, (targetMetrics, id) => {
                row[id] = targetMetrics[detail] || "";
            });
            return row;
        });
        return rows;
    };
    this.addDomInitializer("mailing-bounce-stats", function() {
        config = this.config;
        loadStatistic();
    });
    this.addAction({
        click: "reload-bounce-stats"
    }, loadStatistic);
    function loadStatistic() {
        const $container = Template.dom("bounce-stats-template", {});
        $("#overview-tile > .tile-body").empty().append($container);
        const form = Form.get($("#stat-form"));
        const loader = new ProcessingLoader($container, "#stat-form");
        loader.show();
        form.setActionOnce(AGN.url(`/statistics/mailing/${config.mailingId}/bounces.action`));
        form.submit().done(stats => {
            data = stats;
            renderChartsAndTables();
        }).always(() => loader.hide());
    }
    function renderChartsAndTables() {
        renderChart("softBounces");
        renderTable("softBounces");
        renderChart("hardBounces");
        renderTable("hardBounces");
        renderUndeliveredTable();
    }
    function renderTable(statName) {
        const rows = toAgGridRows(data[statName]);
        rows.at(-1).preventColor = true;
        new Table($(`#${statName}-table`), getTableColumnDefinitions(statName), rows, getDefaultTableOptions());
    }
    function renderUndeliveredTable() {
        if (!config.isMailtrackingActive) {
            return;
        }
        const row = Object.fromEntries(Object.entries(data["undelivered"]).map(([key, val]) => [ key + "", val || "" ]));
        row.detail = t("statistics.bounce.undelivered");
        new Table($(`#undelivered-table`), [ {
            headerName: t("statistics.default.softBounces"),
            field: "detail"
        }, ..._.toPairs(getSelectedTargets()).map(([id, name]) => ({
            headerName: name,
            field: id,
            sortable: true,
            cellRenderer: "MustacheTemplateCellRender",
            cellRendererParams: {
                templateName: "table-value-cell"
            }
        })) ], [ row ], getDefaultTableOptions());
    }
    function renderChart(statName) {
        const targetObj = data[statName][1];
        const chartData = _.omit(targetObj, _.last(_.keys(targetObj)));
        AGN.Lib.StatsChart.create("doughnut", $(`#${statName}-chart`), {
            labels: _.keys(chartData),
            datasets: [ {
                data: _.values(chartData).map(({value: value}) => value)
            } ]
        });
    }
    function getTableColumnDefinitions(statName) {
        return [ {
            headerName: t(`statistics.default.${statName}`),
            field: "detail",
            type: "colorBadge",
            sortable: true
        }, ..._.toPairs(getSelectedTargets()).map(([id, name]) => ({
            headerName: name,
            field: id,
            sortable: true,
            comparator: valueComparator,
            cellRenderer: "MustacheTemplateCellRender",
            cellRendererParams: {
                templateName: "table-value-cell"
            }
        })) ];
    }
    function getDefaultTableOptions() {
        return {
            pagination: false,
            showRecordsCount: "simple",
            domLayout: "autoHeight"
        };
    }
    function valueComparator(valueA, valueB) {
        const a = valueA && valueA.value != null ? Number(valueA.value) : 0;
        const b = valueB && valueB.value != null ? Number(valueB.value) : 0;
        return a - b;
    }
    function getSelectedTargets() {
        return {
            1: t("statistics.default.allRecipients"),
            ...Select.get($("#targetGroupSelect")).selectedValues()
        };
    }
});

AGN.Lib.Controller.new("mailing-end-device-stat", function() {
    const Template = AGN.Lib.Template;
    let config;
    let $container;
    let selectedTargets;
    const deviceClasses = {
        desktop: t("statistics.device.desktop"),
        mobile: t("statistics.device.mobile"),
        tablet: t("statistics.device.tablet"),
        smartTv: t("statistics.device.smarttv")
    };
    const metrics = {
        openings: t("statistics.default.openings"),
        clicks: t("statistics.default.clicks")
    };
    const tableOptions = {
        pagination: false,
        domLayout: "autoHeight",
        showRecordsCount: "simple"
    };
    const colorsMap = new Map;
    this.addDomInitializer("mailing-end-device-stat", function() {
        config = this.config;
        $container = this.el;
        selectedTargets = getSelectedTargets();
        fetchData().done(resp => {
            render(resp);
            $("#stat-loader").addClass("hidden");
            $container.removeClass("invisible");
        });
    });
    function getSelectedTargets() {
        const targetGroupsMap = new Map(config.targetGroups.map(target => [ target.id, target ]));
        const result = config.selectedTargets.map(id => targetGroupsMap.get(parseInt(id)));
        result.unshift(getAllRecipientsTargetGroup());
        return result;
    }
    function fetchData() {
        return $.get(AGN.url(`/statistics/mailing/${config.mailingId}/endDevice.action`), {
            targetGroups: config.selectedTargets
        });
    }
    function isEmptyResponse(resp) {
        return Object.keys(metrics).every(metricName => Object.values(resp[metricName]).every(arr => !arr.length));
    }
    function render(resp) {
        if (isEmptyResponse(resp)) {
            $container.append(Template.dom("no-results-found"));
            return;
        }
        initColorsMap(resp);
        Object.keys(metrics).forEach(metricName => renderMetric(resp, metricName));
    }
    function initColorsMap(resp) {
        colorsMap.clear();
        const statColors = AGN.Lib.Helpers.getStatColorsHexValues();
        let colorIndex = 0;
        Object.keys(metrics).forEach(metricName => {
            const deviceNames = new Set(Object.values(resp[metricName]).flatMap(d => d).map(d => d.deviceName));
            deviceNames.forEach(deviceName => {
                if (!colorsMap.has(deviceName)) {
                    colorsMap.set(deviceName, statColors[colorIndex % statColors.length]);
                    colorIndex++;
                }
            });
        });
    }
    function renderMetric(resp, metricName) {
        const $row = Template.dom("end-device-metric", {
            metricName: metricName,
            metricLabel: metrics[metricName]
        });
        $container.append($row);
        renderChart($(`#${metricName}-chart`), Object.values(resp[metricName]).flatMap(e => e));
        renderTables(resp, metricName);
    }
    function renderChart($chart, entries) {
        const data = prepareChartData(entries);
        if (!data.length) {
            $chart.closest(".tile").addClass("hidden");
            return;
        }
        new Chart($chart[0].getContext("2d"), {
            type: "agnDoughnut",
            data: {
                labels: data.map(d => d.deviceName),
                datasets: [ {
                    data: data.map(d => d.value),
                    rates: data.map(d => d.rate),
                    backgroundColor: data.map(d => colorsMap.get(d.deviceName)),
                    borderWidth: 0
                } ]
            }
        });
    }
    function prepareChartData(entries) {
        return entries.map(({deviceName: deviceName, allRecipients: allRecipients}) => ({
            deviceName: deviceName,
            value: allRecipients.value,
            rate: allRecipients.rate
        }));
    }
    function renderTables(resp, metricName) {
        Object.entries(deviceClasses).forEach(([deviceName, deviceClassLabel]) => {
            const rows = prepareTableRows(resp[metricName][deviceName]);
            renderTableData(rows, metricName, deviceClassLabel);
        });
    }
    function prepareTableRows(entries) {
        return entries.map(e => {
            const row = {
                deviceName: e.deviceName,
                allRecipients: e.allRecipients,
                colorHex: colorsMap.get(e.deviceName)
            };
            selectedTargets.forEach(tg => row[makeTargetGroupPropertyKey(tg.id)] = e.targetGroups[tg.id] ?? {
                value: 0,
                rate: 0
            });
            return row;
        });
    }
    function renderTableData(rows, metricName, deviceClassLabel) {
        if (!rows.length) {
            return;
        }
        const $table = Template.dom("metric-table-wrapper");
        $(`#${metricName}-table-container`).append($table);
        new AGN.Lib.Table($table, getTableColumnsDefinitions(metricName, deviceClassLabel), rows, tableOptions);
    }
    function getTableColumnsDefinitions(metricName, deviceClassName) {
        const columns = [ {
            headerName: `${t(`statistics.default.${metricName}`)} (${deviceClassName})`,
            cellRenderer: "MustacheTemplateCellRender",
            cellRendererParams: {
                templateName: "device-name-cell"
            },
            type: "textCaseInsensitiveColumn",
            field: "deviceName",
            sortable: false
        } ];
        selectedTargets.forEach(tg => columns.push(getTargetGroupColumnDefinition(tg)));
        return columns;
    }
    function getTargetGroupColumnDefinition(targetGroup) {
        return {
            headerName: targetGroup.targetName,
            cellRenderer: "MustacheTemplateCellRender",
            cellRendererParams: {
                templateName: "stat-metric-cell"
            },
            field: targetGroup.id == null ? "allRecipients" : makeTargetGroupPropertyKey(targetGroup.id),
            type: "textCaseInsensitiveColumn",
            sortable: false
        };
    }
    function getAllRecipientsTargetGroup() {
        return {
            id: null,
            targetName: t("statistics.default.allRecipients")
        };
    }
    function makeTargetGroupPropertyKey(targetId) {
        return `target${targetId}`;
    }
});

AGN.Lib.Controller.new("mailing-images", function() {
    const Modal = AGN.Lib.Modal;
    const Template = AGN.Lib.Template;
    const Form = AGN.Lib.Form;
    this.addAction({
        "upload:add": "image-upload"
    }, function() {
        const file = this.data.file;
        const index = this.data.index;
        let $modal = $("#components-upload-modal");
        if (!$modal.exists()) {
            $modal = Modal.fromTemplate("userform-images-upload-modal-template");
            $modal.on("modal:close", clearDropzone);
        }
        const $container = $modal.find("#components-uploads-container");
        const $item = Template.dom("mailing-upload-image", {
            index: index,
            fileName: file.name,
            previewUrl: detectPreviewUrl(file),
            isArchive: getFileExtension(file) === "zip"
        });
        $container.append($item);
        AGN.runAll($item);
    });
    function getFileExtension(file) {
        if (file.name && file.name.includes(".")) {
            return file.name.substring(file.name.lastIndexOf(".") + 1).toLowerCase();
        }
        return "";
    }
    function detectPreviewUrl(file) {
        if (/^image/.test(file.type)) {
            return URL.createObjectURL(file);
        }
        return "";
    }
    function clearDropzone() {
        $("#upload-files").val("");
        $("#dropzone").trigger("upload:reset");
    }
    this.addAction({
        click: "upload-images"
    }, function() {
        const form = Form.get(this.el);
        const $modal = Modal.getWrapper(this.el);
        form.get$().on("submitted", () => {
            if (document.contains($modal[0])) {
                $modal.css("opacity", 1);
            }
        });
        form.submit();
        $modal.css("opacity", 0);
    });
});

class MailingNumTrackingPointsStatBaseController extends AGN.Lib.Controller {
    constructor() {
        super();
        this._tableOptions = {
            pagination: false,
            domLayout: "autoHeight",
            showRecordsCount: "simple"
        };
        this._colors = AGN.Lib.Helpers.getStatColorsHexValues();
        const self = this;
        this.addDomInitializer(this.getInitializerName(), function() {
            self.$container = this.el;
            self.config = this.config;
            self.selectedTargetsMap = self.#getSelectedTargetsMap();
            self.#fetchData().done(resp => {
                self.render(resp);
                $("#stat-loader").addClass("hidden");
                self.$container.removeClass("invisible");
            });
        });
    }
    #fetchData() {
        return $.get(AGN.url(this.getDataUrl(this.config.mailingId)), {
            from: this.config.from,
            to: this.config.to,
            hourScale: this.config.isHourScale,
            targetGroups: this.config.selectedTargets
        });
    }
    getDataUrl(mailingId) {
        throw new Error("Data URL not defined!");
    }
    getInitializerName() {
        throw new Error("Initializer name not defined!");
    }
    render() {}
    getProgressChartOptions(buckets) {
        return {
            type: "bar",
            data: {
                datasets: this.prepareDataSetsForProgressChart(buckets)
            },
            options: {
                layout: {
                    padding: {
                        top: 20,
                        right: 0
                    }
                },
                scales: {
                    x: {
                        type: "time",
                        time: {
                            unit: this.config.isHourScale ? "hour" : "day",
                            displayFormats: {
                                day: this.config.isHourScale ? "" : window.adminDateFormat,
                                hour: this.config.isHourScale ? "HH:mm" : ""
                            },
                            tooltipFormat: window.adminDateFormat
                        },
                        ticks: {
                            maxRotation: 0
                        },
                        min: this.config.from,
                        max: this.config.to
                    },
                    y: {
                        display: false
                    }
                },
                plugins: {
                    datalabels: {
                        formatter: v => AGN.formatNumber(v.y)
                    },
                    legend: {
                        display: true,
                        position: "bottom"
                    }
                }
            }
        };
    }
    prepareDataSetsForProgressChart(buckets) {
        const datasets = [];
        const targetGroupIds = [ null, ...new Set(buckets.flatMap(b => Object.keys(b.targetGroups)).map(id => Number(id))) ];
        targetGroupIds.forEach((targetGroupId, idx) => {
            const dataPoints = buckets.map(b => {
                const groupData = this.isAllRecipientsTargetGroup(targetGroupId) ? b.allRecipients : b.targetGroups[targetGroupId];
                return {
                    x: b.timestamp,
                    y: groupData.sum
                };
            });
            datasets.push({
                label: this.selectedTargetsMap.get(targetGroupId).targetName,
                data: dataPoints,
                backgroundColor: this._colors[idx % this._colors.length],
                categoryPercentage: 1
            });
        });
        return datasets;
    }
    getKeyFiguresColumnDefinitions(title) {
        const columns = [ {
            headerName: title ?? t("statistics.default.keyFigures"),
            cellRenderer: "MustacheTemplateCellRender",
            cellRendererParams: {
                templateName: "key-figures-cell"
            },
            type: "textCaseInsensitiveColumn",
            field: "timestamp",
            sortable: false
        } ];
        this.selectedTargetsMap.values().forEach(tg => columns.push(this.getKeyFigureTargetGroupColumnDefinition(tg)));
        return columns;
    }
    getKeyFigureTargetGroupColumnDefinition(targetGroup) {
        return {
            headerName: targetGroup.targetName,
            cellRenderer: "MustacheTemplateCellRender",
            cellRendererParams: {
                templateName: "key-figures-tg-cell"
            },
            field: this.isAllRecipientsTargetGroup(targetGroup.id) ? "allRecipients" : this.makeTargetGroupPropertyKey(targetGroup.id),
            type: "textCaseInsensitiveColumn",
            sortable: false
        };
    }
    prepareKeyFiguresTableRows(buckets, currency = "") {
        const dateFormat = this.config.isHourScale ? window.adminDateTimeFormat : window.adminDateFormat;
        return buckets.map(b => {
            const row = {
                timestamp: AGN.Lib.DateFormat.format(new Date(b.timestamp), dateFormat),
                currency: currency,
                allRecipients: b.allRecipients
            };
            Object.entries(b.targetGroups).forEach(([tgId, data]) => row[this.makeTargetGroupPropertyKey(tgId)] = data);
            return row;
        });
    }
    isAllRecipientsTargetGroup(targetGroupId) {
        return this.getAllRecipientsTargetGroup().id === targetGroupId;
    }
    getAllRecipientsTargetGroup() {
        return {
            id: null,
            targetName: t("statistics.default.allRecipients")
        };
    }
    makeTargetGroupPropertyKey(targetId) {
        return `target${targetId}`;
    }
    #getSelectedTargetsMap() {
        const targetGroupsMap = new Map(this.config.targetGroups.map(t => [ t.id, t ]));
        const allRecipientsTg = this.getAllRecipientsTargetGroup();
        return new Map([ [ allRecipientsTg.id, allRecipientsTg ], ...this.config.selectedTargets.map(id => targetGroupsMap.get(+id)).map(t => [ t.id, t ]) ]);
    }
    get tableOptions() {
        return this._tableOptions;
    }
    get colors() {
        return this._colors;
    }
}

AGN.Lib.MailingNumTrackingPointsStatBaseController = MailingNumTrackingPointsStatBaseController;

(() => {
    const Template = AGN.Lib.Template;
    const Table = AGN.Lib.Table;
    class MailingTrackingPointsStatController extends AGN.Lib.MailingNumTrackingPointsStatBaseController {
        render(resp) {
            if (resp.trackingPoints.length) {
                resp.trackingPoints.forEach(tp => this.#renderTrackingPointStats(tp));
            } else {
                this.$container.append(Template.text("no-results-found"));
            }
        }
        #renderTrackingPointStats(data) {
            const $stat = Template.dom("num-tracking-point-stat", {
                shortname: data.trackingPointName
            });
            this.$container.append($stat);
            this.#renderProgressChart($stat.find("canvas"), data.buckets);
            this.#renderTotalTable($stat.find("[data-total-stat-table]"), data.trackingPointName, data.currency, data.totals);
            this.#renderKeyFiguresTable($stat.find("[data-key-figures-table]"), data.trackingPointName, data.currency, data.buckets);
        }
        #renderProgressChart($chart, buckets) {
            if (!buckets.length) {
                $chart.replaceWith(Template.dom("no-results-found"));
                return;
            }
            new Chart($chart[0].getContext("2d"), this.getProgressChartOptions(buckets));
        }
        #renderKeyFiguresTable($table, trackingPointName, currency, buckets) {
            const rows = this.prepareKeyFiguresTableRows(buckets, currency);
            new Table($table, this.getKeyFiguresColumnDefinitions(trackingPointName), rows, this.tableOptions);
        }
        #renderTotalTable($table, trackingPointName, currency, data) {
            const row = {
                currency: currency,
                allRecipients: data.allRecipients
            };
            Object.entries(data.targetGroups).forEach(([tgId, d]) => row[this.makeTargetGroupPropertyKey(tgId)] = d);
            new Table($table, this.getKeyFiguresColumnDefinitions(trackingPointName), [ row ], this.tableOptions);
        }
        getDataUrl(mailingId) {
            return `/statistics/mailing/${mailingId}/numTrackingPoints.action`;
        }
        getInitializerName() {
            return "numeric-tracking-points-stat-view";
        }
    }
    AGN.Lib.Controller.new("mailing-num-tracking-points-stat", MailingTrackingPointsStatController);
})();

AGN.Lib.Controller.new("mailing-overview", function() {
    const Form = AGN.Lib.Form;
    const DateFormat = AGN.Lib.DateFormat;
    const BADGES_FILTERS = [ {
        key: "isgrid",
        text: t("mailing.default.grid"),
        class: "mailing.status.emc"
    }, {
        key: "isCampaignManager",
        text: t("workflow.campaign"),
        class: "mailing.status.cm"
    } ];
    this.addDomInitializer("mailing-overview", function() {
        clearFormSubmitHandlers(Form.getWrapper(this.el));
        handleBadgesFiltersOptions(this.config.badgesFilters);
    });
    function handleBadgesFiltersOptions(selectedBadges) {
        if (!selectedBadges) {
            selectedBadges = [];
        }
        const $statusSelect = $("#status-filter");
        const statusSelect = AGN.Lib.Select.get($statusSelect);
        _.each(BADGES_FILTERS, badge => {
            $statusSelect.append(`<option value="${badge.key}" data-badge-class="${badge.class}">${badge.text}</option>`);
            if (selectedBadges.includes(badge.key)) {
                statusSelect.selectOption(badge.key);
            }
        });
        const form = Form.get($statusSelect);
        form.get$().on("form:submit", () => {
            let badgesAdded = 0;
            _.each(BADGES_FILTERS, badge => {
                if (statusSelect.isOptionSelected(badge.key)) {
                    form.setValueOnce(`filterBadges[${badgesAdded++}]`, badge.key);
                    statusSelect.$findOption(badge.key).attr("disabled", true);
                }
            });
        });
        form.get$().on("submitted", () => {
            BADGES_FILTERS.forEach(badge => {
                statusSelect.$findOption(badge.key).attr("disabled", false);
            });
        });
    }
    function clearFormSubmitHandlers($form) {
        $form.off("form:submit");
        $form.off("submitted");
    }
    this.addAction({
        "table-column-manager:add": "update-columns"
    }, function() {
        const form = Form.get(this.el);
        form.setValueOnce("selectedFields", this.data.columns);
        form.setValueOnce("inEditColumnsMode", true);
        form.submit();
    });
    this.addAction({
        "table-column-manager:apply": "update-columns"
    }, function() {
        const selectedFields = this.data.columns;
        $.ajax({
            type: "POST",
            url: AGN.url("/mailing/setSelectedFields.action"),
            traditional: true,
            data: {
                selectedFields: selectedFields
            }
        }).done(resp => {
            if (resp.success) {
                AGN.Lib.WebStorage.extend("mailing-overview", {
                    fields: selectedFields
                });
            }
            AGN.Lib.JsonMessages(resp.popups);
        });
    });
    this.addAction({
        click: "send-date-filter-period"
    }, function() {
        controlSendDatePeriodSelect(this.el);
        setSendDatesRange(getSendDateBeginVal(), getSendDateEndVal());
        toggleSendDateInputsReadonly($("input[name='sendDatePeriod']:checked").length > 0);
    });
    this.addAction({
        click: "reset-send-date-filter"
    }, function() {
        setSendDatesRange("", "");
        $('input[name="sendDatePeriod"]:checked').removeAttr("checked");
        toggleSendDateInputsReadonly(false);
    });
    function setSendDatesRange(startDate, endDate) {
        $("#filterSendDateBegin").val(startDate).trigger("change");
        $("#filterSendDateEnd").val(endDate).trigger("change");
    }
    function toggleSendDateInputsReadonly(readonly) {
        $("#filterSendDateBegin").get(0).toggleAttribute("readonly", readonly);
        $("#filterSendDateEnd").get(0).toggleAttribute("readonly", readonly);
    }
    function getSendDateBeginVal() {
        const period = $("input[name='sendDatePeriod']:checked").val();
        if (!period) {
            return "";
        }
        const date = new Date;
        date.setDate(date.getDate() - period);
        return DateFormat.format(date, window.adminDateFormat);
    }
    function getSendDateEndVal() {
        return $("input[name='sendDatePeriod']:checked").length ? DateFormat.format(new Date, window.adminDateFormat) : "";
    }
    function controlSendDatePeriodSelect($periodCheckbox) {
        if ($periodCheckbox.is(":checked")) {
            const group = `input:checkbox[name="${$periodCheckbox.attr("name")}"]`;
            $(group).prop("checked", false);
            $periodCheckbox.prop("checked", true);
        } else {
            $periodCheckbox.prop("checked", false);
        }
    }
});

AGN.Lib.Controller.new("mailing-params", function() {
    let $form = $("#mailingSettingsForm");
    let initParams;
    let $mailingParamsTable = $("#mailingParamsTable");
    this.addDomInitializer("mailing-params", function() {
        initParams = this.config.params;
        $form = $("#mailingSettingsForm");
        $form.dirty("setAsClean");
        $form.dirty("refreshEvents");
        $mailingParamsTable.on("input-table:row-removed", checkParamsDirtyState);
    });
    function checkParamsDirtyState() {
        if (isDirtyOnlyMailingParamsFields() && !isParamsChanged()) {
            $form.dirty("setAsClean");
        }
    }
    function isParamsChanged() {
        const cleanInitParams = initParams.map(function(param) {
            const cleanParam = _.omit(param, "mailingID", "mailingInfoID", "changeDate");
            Object.keys(cleanParam).forEach(function(key) {
                if (cleanParam[key] === null) {
                    cleanParam[key] = "";
                }
            });
            return cleanParam;
        });
        return JSON.stringify(cleanInitParams) !== JSON.stringify($mailingParamsTable.data("table").collect());
    }
    function isDirtyOnlyMailingParamsFields() {
        return $form.dirty("showDirtyFields").filter((_, e) => !$(e).closest("#mailingParamsTable").length).length === 0;
    }
});

AGN.Lib.Controller.new("mailing-preview", function() {
    const Form = AGN.Lib.Form;
    const Messages = AGN.Lib.Messages;
    const Helpers = AGN.Lib.Helpers;
    const Select = AGN.Lib.Select;
    let MAILING_ID;
    this.addDomInitializer("mailing-preview", function() {
        MAILING_ID = this.config.MAILING_ID;
        const form = Form.get(this.el);
        form.initFields();
        form.initValidator();
        controlTestRunVisibility();
        if (isMobileSizeChosen(this.config, form)) {
            loadIframeMediapoolImagesForMobile();
        }
    });
    function loadIframeMediapoolImagesForMobile() {
        $('[name="previewFrame"]').hide().on("load", addMobileParameterForMediapoolImagesSrc).show();
    }
    function addMobileParameterForMediapoolImagesSrc() {
        $(this.contentDocument || this.contentWindow.document).find("img").filter((i, img) => $(img).attr("src")?.includes("mediapool_element")).each(function() {
            const originalSrc = $(this).attr("src");
            $(this).attr("src", `${originalSrc}${originalSrc.includes("?") ? "&" : "?"}forMobile=true`);
        });
    }
    function isMobileSizeChosen(config, form) {
        return config.MOBILE_SIZES.includes(parseInt(form.getValue("size")));
    }
    this.addAction({
        change: "refresh-preview",
        click: "update-preview"
    }, function() {
        updatePreview();
    });
    this.addAction({
        change: "change-stored-header-data"
    }, function() {
        updatePreview();
    });
    this.addAction({
        change: "change-header-data"
    }, function() {
        updatePreview();
    });
    function updatePreview() {
        const form = Form.get($("#preview-form"));
        form.submit();
    }
    function controlTestRunVisibility() {
        controlTestRunContainerVisibility();
        controlAddToTestRunBtnVisibility();
    }
    this.addAction({
        click: "change-preview-customer-options"
    }, function() {
        controlAddToTestRunBtnVisibility();
    });
    function controlTestRunContainerVisibility() {
        const $testRecipients = getTestRecipients$();
        if (!$testRecipients.exists()) {
            return;
        }
        const hidden = $testRecipients.val().length <= 0;
        $("#personalized-test-run-container").toggleClass("hidden", hidden);
    }
    function getTestRecipients$() {
        return $("#personalized-test-recipients");
    }
    function controlAddToTestRunBtnVisibility() {
        const isVisible = !isRecipientChosenByTargetGroup() && currentRecipientAlreadyChosenForTestRun();
        $('[data-action="add-to-personalized-test-run"]').toggle(!!isVisible);
    }
    function currentRecipientAlreadyChosenForTestRun() {
        const previewRecipientEmail = getEmailOfCurrentPreviewRecipient();
        return Select.get(getTestRecipients$()).getSelectedValue().indexOf(previewRecipientEmail) === -1;
    }
    function getEmailOfCurrentPreviewRecipient() {
        if (isRecipientChosenByInput()) {
            return $("#customerEmail").val();
        }
        return $('[name="customerATID"]').find(":selected").data("email");
    }
    function getCurrentMode() {
        return $('[name="modeType"]').val();
    }
    function isRecipientChosenByInput() {
        return getCurrentMode() === "MANUAL";
    }
    function isRecipientChosenByTargetGroup() {
        return getCurrentMode() === "TARGET_GROUP";
    }
    function validateEmailOfCurrentPreviewRecipient() {
        return new Promise(function(resolve, reject) {
            const email = getEmailOfCurrentPreviewRecipient();
            if (!Helpers.isValidEmail(email)) {
                Messages.alert("defaults.invalidEmail");
                return;
            }
            $.get(AGN.url(`/mailing/preview/${MAILING_ID}/isRecipient.action`), {
                email: email
            }).done(resp => {
                if (resp.success) {
                    resolve(email);
                } else {
                    AGN.Lib.JsonMessages(resp.popups, true);
                    reject();
                }
            });
        });
    }
    this.addAction({
        input: "change-personalized-test-recipients",
        change: "change-personalized-test-recipients"
    }, function() {
        controlTestRunVisibility();
    });
    this.addAction({
        click: "add-to-personalized-test-run"
    }, function() {
        validateEmailOfCurrentPreviewRecipient().then(email => {
            const $testRecipients = getTestRecipients$();
            const testRecipientsSelect = Select.get($testRecipients);
            if (!testRecipientsSelect.hasOption(email)) {
                testRecipientsSelect.addOption(email);
            }
            testRecipientsSelect.selectOptions(_.union($testRecipients.val(), [ email ]));
            controlTestRunVisibility();
        });
    });
    this.addAction({
        click: "personalized-test-run"
    }, function() {
        const testRecipients$ = getTestRecipients$();
        const recipientIds = testRecipients$.val();
        $.post(AGN.url(`/mailing/send/${MAILING_ID}/personalized-test.action`), {
            mailingTestRecipients: recipientIds
        }).done(resp => {
            if (resp && resp.success === true) {
                testRecipients$.val([]);
                AGN.Lib.CoreInitializer.run("select", testRecipients$);
                controlTestRunContainerVisibility();
            }
            AGN.Lib.JsonMessages(resp.popups, true);
        });
    });
    this.addAction({
        click: "download-attachment"
    }, function() {
        const $tempAnchor = $("<a>").attr("href", $("#attachments").val());
        $("body").append($tempAnchor);
        $tempAnchor[0].click();
        $tempAnchor.remove();
    });
    this.addAction({
        click: "calculateRecipients"
    }, function() {
        const targetGroupId = $("#target-groups").val();
        $.post(AGN.url(`/mailing/ajax/${MAILING_ID}/recipients/${targetGroupId}/count.action`)).done(({count: count}) => $("#number-of-recipients").val(count));
    });
});

AGN.Lib.Controller.new("mailing-priorities", function() {
    const Template = AGN.Lib.Template;
    const Helpers = AGN.Lib.Helpers;
    const DateFormat = AGN.Lib.DateFormat;
    const ENTRY_SELECTOR = ".mailing-priority";
    const ENTRIES_CONTAINER_SELECTOR = ".mailing-priority-container";
    let $orderedArea;
    let $unorderedArea;
    let $saveButton;
    let $priorityCount;
    let originPrioritizedIds;
    let originPriorityCount;
    let config;
    const initDomVariables = () => {
        $orderedArea = $("#ordered-area");
        $unorderedArea = $("#unordered-area");
        $priorityCount = $("#priorityCount");
        $saveButton = $("#save-btn");
    };
    function minDay() {
        return _.reduce(_.keys(config.mailingsMap), function(a, b) {
            return a < b ? a : b;
        });
    }
    const activateAvailableDates = () => {
        const $picker = $("#date-picker");
        const dates = _.keys(config.mailingsMap).sort();
        if (dates.length) {
            if (!$picker.datepicker("getDate")) {
                $picker.datepicker("setDate", DateFormat.parse(minDay()));
            }
        }
        $picker.trigger("change");
    };
    this.addDomInitializer("mailing-priorities", function() {
        config = this.config;
        initDomVariables();
        const $container = $(".tiles-container");
        $(ENTRIES_CONTAINER_SELECTOR).sortable({
            handle: ".mailing-priority__drag-btn",
            opacity: .4,
            connectWith: ENTRIES_CONTAINER_SELECTOR,
            items: ENTRY_SELECTOR,
            helper: "clone",
            containment: $container,
            appendTo: document.body,
            update: function() {
                if (this.id === $orderedArea.attr("id")) {
                    updatePriorityOrder();
                    checkOriginChanges();
                }
            },
            out: function() {
                highlightBackground($(this), false);
            },
            over: function(e, ui) {
                highlightBackground($(e.target), false);
                highlightBackground($(this), true);
            },
            start: function() {
                highlightBackground($(this), true);
            },
            stop: function() {
                highlightBackground($(this), false);
            }
        });
        activateAvailableDates();
    });
    this.addAction({
        change: "priorityCount"
    }, checkOriginChanges);
    this.addAction({
        input: "priorityCount"
    }, function() {
        const value = parseFloat(this.el.val());
        const newValue = !isNaN(value) && value >= 0 ? value : 0;
        this.el.val(newValue);
    });
    this.addAction({
        change: "change-date"
    }, function() {
        const date = this.el.datepicker("getDate");
        if (date) {
            select(arrayDateToStr([ date.getFullYear(), date.getMonth(), date.getDate() ]));
        } else {
            select();
        }
    });
    this.addAction({
        click: "save"
    }, function() {
        const form = AGN.Lib.Form.get(this.el);
        form.setValueOnce("prioritizedIds", collectPrioritizedIds());
        form.submit();
    });
    const highlightBackground = ($target, activate) => {
        $target.closest(ENTRIES_CONTAINER_SELECTOR).toggleClass("highlighted", activate);
    };
    function updatePriorityOrder() {
        let index = 1;
        let nextDateBasedIndex = 10;
        $orderedArea.children(ENTRY_SELECTOR).each(function() {
            const $e = $(this);
            let priority = 0;
            if ($e.data("type") == config.DATE_BASED_TYPE) {
                priority = nextDateBasedIndex;
                index = nextDateBasedIndex;
                nextDateBasedIndex += 10;
            } else {
                priority = index;
                if (index > nextDateBasedIndex) {
                    nextDateBasedIndex = Math.round(index / 10) * 10;
                }
            }
            index++;
            $e.find(".mailing-priority__order").text(`${priority}.`);
        });
    }
    function select(day) {
        const entries = collectMailingEntries(day);
        $(ENTRY_SELECTOR).remove();
        moveToProperBox(entries);
        checkOriginChanges(true);
    }
    function collectMailingEntries(day) {
        let entries = (config.mailingsMap[day] || []).filter(e => e.mailingType !== config.DATE_BASED_TYPE || e.priority > 0);
        const excludeIds = entries.map(e => e.id);
        const dateBasedMailingsWithoutPriority = getAllDateBasedMailingsWithoutPriority(excludeIds);
        return _.union(entries, dateBasedMailingsWithoutPriority, "id").sort((a, b) => a.priority > b.priority ? 1 : -1);
    }
    const getAllDateBasedMailingsWithoutPriority = excludeIds => {
        const dateBasedMailings = [];
        const exclude = _.clone(excludeIds);
        _.keys(config.mailingsMap).forEach(date => {
            config.mailingsMap[date].forEach(entry => {
                if (entry.mailingType == config.DATE_BASED_TYPE && !exclude.includes(entry.id)) {
                    exclude.push(_.clone(entry).id);
                    dateBasedMailings.push(entry);
                }
            });
        });
        return dateBasedMailings;
    };
    function moveToProperBox(entries) {
        if (entries && entries.length) {
            entries.forEach(function(e) {
                if (e.thumbnailId) {
                    e.thumbnailUrl = config.thumbnailLinkPattern.replace("__thumbnailId__", e.thumbnailId);
                } else {
                    e.thumbnailUrl = config.noPreviewUrl;
                }
                const $priorityEntry = Template.dom("draggable-mailing-priority-entry", e);
                if (e.priority) {
                    $orderedArea.append($priorityEntry);
                } else {
                    $unorderedArea.append($priorityEntry);
                }
                AGN.runAll($priorityEntry);
            });
        }
    }
    function arrayDateToStr(date) {
        return `${Helpers.pad(date[0], 4)}-${Helpers.pad(parseInt(date[1]) + 1, 2)}-${Helpers.pad(date[2], 2)}`;
    }
    function checkOriginChanges(reset) {
        const newPrioritizedIds = collectPrioritizedIds(";");
        const newPriorityCount = $priorityCount.val();
        if (originPrioritizedIds == null && originPriorityCount == null || reset) {
            originPrioritizedIds = newPrioritizedIds;
            originPriorityCount = newPriorityCount;
            if (newPriorityCount > 0) {
                $saveButton.prop("disabled", true);
            } else {
                const count = countPrioritizedTemplates();
                $priorityCount.val(count);
                $saveButton.prop("disabled", !count);
            }
        } else {
            $saveButton.prop("disabled", newPrioritizedIds == originPrioritizedIds && newPriorityCount == originPriorityCount);
        }
    }
    function collectPrioritizedIds(separator) {
        const ids = [];
        $orderedArea.children(ENTRY_SELECTOR).each(function() {
            const id = $(this).data("id");
            if (id > 0) {
                ids.push(id);
            }
        });
        return separator ? ids.join(separator) : ids;
    }
    function countPrioritizedTemplates() {
        return $orderedArea.children(ENTRY_SELECTOR).filter(function() {
            return $(this).data("id") > 0;
        }).length;
    }
});

AGN.Lib.Controller.new("mailing-recipients", function() {
    const Form = AGN.Lib.Form;
    this.addAction({
        "table-column-manager:add": "update-columns"
    }, function() {
        const form = Form.get(this.el);
        form.setValueOnce("selectedFields", this.data.columns);
        form.setValueOnce("inEditColumnsMode", true);
        form.submit();
    });
    this.addAction({
        "table-column-manager:apply": "update-columns"
    }, function() {
        const selectedFields = this.data.columns;
        $.ajax({
            type: "POST",
            url: AGN.url("/mailing/recipients/setSelectedFields.action"),
            traditional: true,
            data: {
                selectedFields: selectedFields
            }
        }).done(resp => {
            if (resp.success) {
                AGN.Lib.WebStorage.extend("mailing-recipient-overview", {
                    fields: selectedFields
                });
            }
            AGN.Lib.JsonMessages(resp.popups);
        });
    });
});

AGN.Lib.Controller.new("reference-content-settings", function() {
    let $container;
    let isAvailable = false;
    let isEnabled = false;
    let initialItems = [];
    let $form;
    function selectKeyColumn() {
        const $select = $("#referenceTableSelect");
        const $option = $select.children("option:selected");
        $("#keyColumnText").val($option.exists() ? $option.data("key-column") : "");
    }
    function createItem(index, value) {
        return AGN.Lib.Template.dom("mailing-reference-content-item", {
            name: getAddonText(index),
            value: value,
            disabled: !isEnabled
        });
    }
    function getAddonText(index) {
        return "Item" + index;
    }
    function addItem(value) {
        const $item = createItem(getRows$().length + 1, value);
        $container.append($item);
    }
    function renderItems(items) {
        if (!isEnabled) {
            addItem("");
            return;
        }
        _.each(items, value => addItem(value));
    }
    function getRows$() {
        return $("#reference-content-items .row");
    }
    this.addDomInitializer("reference-content-settings", function() {
        $container = $("#reference-content-items");
        $form = $("#mailingSettingsForm");
        selectKeyColumn();
        isAvailable = this.config.isAvailable;
        isEnabled = this.config.isEnabled;
        renderItems(this.config.items);
        initialItems = getRows$();
        controlSelectDisplaying();
        $form.dirty("setAsClean");
        $form.dirty("refreshEvents");
    });
    function controlSelectDisplaying() {
        $("#referenceContentEnabled").on("change", function() {
            $("#referenceTableSelect").prop("disabled", !$(this).prop("checked"));
        });
    }
    this.addAction({
        change: "select-reference-table"
    }, function() {
        selectKeyColumn();
    });
    this.addAction({
        click: "add-reference-content-item"
    }, function() {
        replaceNewButtonWithDeleteButton();
        addItem("");
        $form.dirty("setAsDirty");
    });
    function replaceNewButtonWithDeleteButton() {
        const newBtn = $container.find('[data-action="add-reference-content-item"]');
        newBtn.after(_.template(AGN.Opt.Templates["mailing-reference-content-delete-btn"])({
            disabled: !isEnabled
        }));
        newBtn.remove();
    }
    function isItemsChanged() {
        return initialItems.length !== getRows$().length || initialItems.some(value => !getRows$().includes(value));
    }
    function updateTextOfAddons() {
        getRows$().each((index, row) => {
            $(row).find(".input-group-text").text(getAddonText(index + 1));
        });
    }
    this.addAction({
        click: "delete-reference-content-item"
    }, function() {
        this.el.closest(".row").remove();
        updateTextOfAddons();
        if (!isItemsChanged()) {
            $form.dirty("setAsDirty");
        }
    });
});

(() => {
    const Table = AGN.Lib.Table;
    class MailingRevenueStatController extends AGN.Lib.MailingNumTrackingPointsStatBaseController {
        render(resp) {
            this.#renderProgressChart(resp.revenue);
            this.#renderDeviceTypeChart(resp.deviceTypes);
            this.#renderDeviceTypeTable(resp.deviceTypes);
            this.#renderConversionRatesTable(resp.conversions);
            this.#renderKeyFiguresTable(resp.revenue);
        }
        #renderProgressChart(buckets) {
            const $chart = $("#progress-chart");
            if (!buckets.length) {
                $chart.replaceWith(AGN.Lib.Template.dom("no-results-found"));
                return;
            }
            new Chart($chart[0].getContext("2d"), this.getProgressChartOptions(buckets));
        }
        #renderDeviceTypeChart(rows) {
            const $chart = $("#device-type-chart");
            if (rows.every(row => !row.value)) {
                $chart.closest(".tile").addClass("hidden");
                return;
            }
            new Chart($chart[0].getContext("2d"), {
                type: "agnDoughnut",
                data: {
                    labels: rows.map(r => r.deviceType),
                    datasets: [ {
                        data: rows.map(r => r.value),
                        backgroundColor: rows.map((r, idx) => this.colors[idx % this.colors.length]),
                        borderWidth: 0
                    } ]
                }
            });
        }
        #renderDeviceTypeTable(rows) {
            new Table($("#device-type-table"), $("#device-type-table-column-definitions").json(), rows, this.tableOptions);
        }
        #renderConversionRatesTable(rows) {
            new Table($("#conversion-rates-table"), $("#conversion-rates-table-column-definitions").json(), rows, this.tableOptions);
        }
        #renderKeyFiguresTable(buckets) {
            const rows = this.prepareKeyFiguresTableRows(buckets);
            new Table($("#key-figures-table"), this.getKeyFiguresColumnDefinitions(), rows, this.tableOptions);
        }
        getDataUrl(mailingId) {
            return `/statistics/mailing/${mailingId}/revenue.action`;
        }
        getInitializerName() {
            return "revenue-stat-view";
        }
    }
    AGN.Lib.Controller.new("mailing-revenue-stat", MailingRevenueStatController);
})();

AGN.Lib.Controller.new("mailing-send", function() {
    const Form = AGN.Lib.Form, Confirm = AGN.Lib.Confirm, Page = AGN.Lib.Page, Template = AGN.Lib.Template, ChartUtils = AGN.Lib.ChartUtils, Messages = AGN.Lib.Messages;
    const RECIPIENT_TEST_RUN_OPTION = "RECIPIENT";
    const TARGET_TEST_RUN_OPTION = "TARGET";
    const SEND_TO_SELF_TEST_RUN_OPTION = "SEND_TO_SELF";
    let $testRecipientsTable;
    let approvalOptions;
    let testSendConfig;
    let includeImagesInSize;
    const Helpers = {
        hideGreenMarks: function() {
            const $transmissionMark = $(".transmission-mark");
            $transmissionMark.parent().find("button").removeClass("hidden");
            $transmissionMark.remove();
        },
        updateWorkStatus: function(workStatus, tooltip) {
            const $statusIcon = Template.dom("mailing-workstatus-icon", {
                workStatus: workStatus,
                tooltip: tooltip
            });
            $("#workstatus-icon").replaceWith($statusIcon);
            AGN.Lib.CoreInitializer.run("tooltip", $statusIcon);
        }
    };
    this.addDomInitializer("test-mailing", function() {
        $testRecipientsTable = $("#test-recipients-table");
        drawTestRecipientsTable(this.config.testRecipients);
        approvalOptions = JSON.parse(this.config ? this.config.approvalOptions : "[]");
        testSendConfig = this.config;
        controlTestRunOptionsDisplaying();
        $("#get-approval-switch").on("change", controlTestRunOptionsDisplaying);
        controlTestRunRecipientsDisplaying();
        $("#test-run-options").on("change", function() {
            controlTestRunRecipientsDisplaying();
        });
    });
    function controlTestRunOptionsDisplaying() {
        const filterOptions = $("#get-approval-switch").prop("checked");
        const showOnlyMailinglistApproval = isMailinglistEmailsUsedForApproval();
        $("#mailinglist-approval-emails").toggle(showOnlyMailinglistApproval);
        $("#save-as-target-switch, #test-recipients-table, #test-run-options, #testRunOptionSelect").parent().toggle(!showOnlyMailinglistApproval);
        const $optionsSelect = $("#test-run-options");
        $optionsSelect.find("option:not([value='" + approvalOptions.join("']):not([value='") + "']").attr("disabled", filterOptions);
        if (filterOptions && !approvalOptions.includes($optionsSelect.val())) {
            $optionsSelect.val($optionsSelect.find("option:not(:disabled):first").val()).trigger("change");
        }
    }
    function isMailinglistEmailsUsedForApproval() {
        const $approvalSwitch = $("#get-approval-switch");
        return $approvalSwitch.is(":visible") && $approvalSwitch.prop("checked") && testSendConfig.mailinglistApprovalEmails.length > 0;
    }
    function controlTestRunRecipientsDisplaying() {
        const $testRunDropdown = $("#test-run-options");
        if (!$testRunDropdown.exists()) {
            return;
        }
        const isSingleRecipientOption = $testRunDropdown.val() == RECIPIENT_TEST_RUN_OPTION;
        const isTargetIdRunOption = $testRunDropdown.val() == TARGET_TEST_RUN_OPTION;
        const isSendToSelfRunOption = $testRunDropdown.val() == SEND_TO_SELF_TEST_RUN_OPTION;
        const newTargetElementsHidden = !isSingleRecipientOption || !$("#save-target-toggle").prop("checked");
        $testRecipientsTable.parent().toggleClass("hidden", !isSingleRecipientOption);
        $("#adminSendButton").parent().toggleClass("hidden", isSingleRecipientOption || isTargetIdRunOption || isSendToSelfRunOption);
        $("#testTargetSaveButton").parent().toggleClass("hidden", newTargetElementsHidden);
        $("#test-run-target-name-input").toggleClass("hidden", newTargetElementsHidden);
        $("#testRunOptionSelect").prop("disabled", !isTargetIdRunOption);
        $testRecipientsTable.find("input").prop("disabled", !isSingleRecipientOption);
    }
    this.addDomInitializer("send-mailing", function() {
        config = this.config;
        includeImagesInSize = $("#includeImagesInSize").is(":checked");
        const decimalSeparator = window.adminLocale === "en-US" ? "," : ".";
        _.each($(".commaSplitInput"), e => {
            const $e = $(e);
            const separatedText = $e.val().replace(/\B(?=(\d{3})+(?!\d))/g, decimalSeparator);
            $e.val(separatedText);
        });
        clearMaxRecipientsValueIfZero();
        updateDeliverySize();
        displayRecipientsCount();
        if (config.approximateMaxDeliverySize > config.errorSizeThreshold) {
            Messages.warnText(Template.text("delivery-size-error-msg"));
        }
    });
    this.addAction({
        click: "check-links"
    }, function() {
        $.post(AGN.url(`/mailing/${config.mailingId}/trackablelink/check.action`)).done(resp => AGN.Lib.RenderMessages($(resp)));
    });
    this.addAction({
        change: "update-mailing-size"
    }, function() {
        includeImagesInSize = this.el.is(":checked");
        updateDeliverySize();
    });
    this.addAction({
        click: "send-world"
    }, function() {
        if (config.approximateMaxDeliverySize > config.errorSizeThreshold) {
            Messages.alertText(Template.text("delivery-size-error-msg"));
            return;
        }
        const formSubmissionCallback = () => {
            const form = Form.get(this.el);
            form.setActionOnce(AGN.url("/mailing/send/confirm-send-world.action"));
            form.submit("confirm").done(resp => {
                Confirm.create(resp).done(resp => form.updateHtml(resp));
            });
        };
        if (config.approximateMaxDeliverySize > config.warningSizeThreshold) {
            Confirm.from("warning-mailing-size-modal").done(formSubmissionCallback);
            return;
        }
        formSubmissionCallback();
    });
    function updateDeliverySize() {
        const sizes = getMailingSize();
        const colors = getMailingSizeColors(sizes);
        drawSizeTable(colors, sizes);
        drawDeliverySizeChart(colors, sizes);
    }
    function drawSizeTable(colors, sizes) {
        const $table = $("#mailing-size-table");
        if (!$table.exists()) {
            return;
        }
        const tableConfig = $("#mailing-size-table-cfg").json();
        $table.get(0).style.setProperty("--attachments-color", colors.attachments);
        $table.get(0).style.setProperty("--other-html-color", colors.otherHtml);
        const table = AGN.Lib.Table.get($table);
        const tableData = [ {
            attachmentsSize: sizes.attachments,
            otherHtmlSize: sizes.otherHtml
        } ];
        if (table) {
            table.setData(tableData);
        } else {
            new AGN.Lib.Table($table, tableConfig.columns, tableData, tableConfig.options);
        }
    }
    function drawDeliverySizeChart(colors, sizes) {
        const $chart = $("#delivery-size-chart");
        if (!$chart.exists()) {
            return;
        }
        const chartInstance = Object.values(Chart.instances).find(chart => chart.canvas === $chart[0]);
        if (chartInstance && !config.isOfflineHtmlFormat) {
            return;
        }
        chartInstance?.destroy();
        const barThickness = $chart.outerHeight();
        new Chart($chart[0].getContext("2d"), {
            type: "bar",
            data: {
                labels: [ "" ],
                datasets: [ {
                    label: t("mailing.default.attachments"),
                    data: [ sizes.attachments ],
                    backgroundColor: colors.attachments,
                    barThickness: barThickness
                }, {
                    label: t("mailing.default.otherHtml"),
                    data: [ sizes.otherHtml ],
                    backgroundColor: colors.otherHtml,
                    barThickness: barThickness
                } ]
            },
            options: {
                indexAxis: "y",
                layout: {
                    padding: 0
                },
                scales: {
                    x: {
                        display: false,
                        stacked: true,
                        max: Math.max(sizes.attachments + sizes.otherHtml, config.errorSizeThreshold)
                    },
                    y: {
                        stacked: true,
                        display: false
                    }
                },
                plugins: {
                    datalabels: {
                        display: false
                    },
                    tooltip: {
                        callbacks: {
                            title(items) {
                                return items[0].dataset.label;
                            },
                            label(context) {
                                const sizeKb = context.raw / 1024;
                                return `${AGN.formatNumber(sizeKb)} kB`;
                            }
                        }
                    }
                }
            }
        });
    }
    const getMailingSizeColors = sizes => {
        const totalSize = sizes.attachments + sizes.otherHtml;
        if (totalSize >= config.errorSizeThreshold) {
            return {
                attachments: ChartUtils.getLightRedColor(),
                otherHtml: ChartUtils.getDarkRedColor()
            };
        }
        if (totalSize >= config.warningSizeThreshold) {
            return {
                attachments: ChartUtils.getDarkYellowColor(),
                otherHtml: ChartUtils.getDarkestYellowColor()
            };
        }
        return {
            attachments: ChartUtils.getGreenColor(),
            otherHtml: ChartUtils.getDarkGreenColor()
        };
    };
    const getMailingSize = () => {
        let otherHtmlSize;
        if (config.isOfflineHtmlFormat && includeImagesInSize) {
            otherHtmlSize = config.approximateMaxDeliverySize - config.attachmentsSize;
        } else {
            otherHtmlSize = config.contentSize;
        }
        return {
            attachments: config.attachmentsSize,
            otherHtml: otherHtmlSize
        };
    };
    function displayRecipientsCount() {
        const colors = {
            text: ChartUtils.getLightBlueColor(),
            html: ChartUtils.getBlueColor(),
            offlineHtml: ChartUtils.getDarkBlueColor(),
            mediaTypes: {
                2: ChartUtils.getCyanColor(),
                4: ChartUtils.getDarkestBlueColor(),
                5: ChartUtils.getDarkestCyanColor()
            }
        };
        assignColorsToRecipientsCountTable(colors);
        drawRecipientsCountChart(colors);
    }
    function assignColorsToRecipientsCountTable(colors) {
        const $table = $("#recipients-count-table");
        if (!$table.exists()) {
            return;
        }
        const el = $table.get(0);
        Object.entries(colors).forEach(([key, value]) => {
            if (typeof value === "object") {
                Object.entries(value).forEach(([subKey, subValue]) => {
                    el.style.setProperty(`--${key}${subKey}-count-color`, subValue);
                });
            } else {
                el.style.setProperty(`--${key}-count-color`, value);
            }
        });
    }
    function drawRecipientsCountChart(colors) {
        const $chart = $("#recipients-count-chart");
        if (!$chart.exists()) {
            return;
        }
        const barThickness = $chart.outerHeight();
        const chartConfig = {
            type: "bar",
            data: {
                labels: [ "" ],
                datasets: [ {
                    label: t("mailing.default.mailFormat.text"),
                    data: [ config.textEmailsCount ],
                    backgroundColor: colors.text,
                    barThickness: barThickness
                }, {
                    label: t("mailing.default.mailFormat.html"),
                    data: [ config.htmlEmailsCount ],
                    backgroundColor: colors.html,
                    barThickness: barThickness
                }, {
                    label: t("mailing.default.mailFormat.offlineHtml"),
                    data: [ config.offlineHtmlEmailsCount ],
                    backgroundColor: colors.offlineHtml,
                    barThickness: barThickness
                } ]
            },
            options: {
                indexAxis: "y",
                layout: {
                    padding: 0
                },
                scales: {
                    x: {
                        display: false,
                        stacked: true,
                        max: config.totalSendCount
                    },
                    y: {
                        stacked: true,
                        display: false
                    }
                },
                plugins: {
                    datalabels: {
                        display: false
                    },
                    tooltip: {
                        callbacks: {
                            title(items) {
                                return items[0].dataset.label;
                            }
                        }
                    }
                }
            }
        };
        Object.keys(config.mediaTypesRecipientsCountMap).filter(code => code > 0).forEach(code => {
            chartConfig.data.datasets.push({
                label: t(`mailing.default.mediaType.${code}`),
                data: [ config.mediaTypesRecipientsCountMap[code] ],
                backgroundColor: colors.mediaTypes[code],
                barThickness: barThickness
            });
        });
        new Chart($chart[0].getContext("2d"), chartConfig);
    }
    const drawTestRecipientsTable = function(recipients) {
        if (!recipients.length) {
            const $row = Template.dom("test-recipient-row", {
                value: "",
                newRow: true,
                sent: false
            });
            $testRecipientsTable.append($row);
            AGN.runAll($row);
            return;
        }
        for (let i = 0; i < recipients.length; i++) {
            const isLastRow = i === recipients.length - 1;
            const $row = Template.dom("test-recipient-row", {
                value: recipients[i],
                newRow: isLastRow,
                sent: true
            });
            $testRecipientsTable.append($row);
            AGN.runAll($row);
        }
    };
    this.addAction({
        change: "save-interval-settings"
    }, function() {
        const form = Form.get(this.el);
        form.setActionOnce(AGN.url("/mailing/send/interval.action"));
        form.submit();
    });
    this.addAction({
        click: "resume-sending"
    }, function() {
        const $el = this.el;
        const link = $el.data("link");
        $.post(link).done(resp => {
            Page.render(resp);
            $el.parent().remove();
        });
    });
    this.addDomInitializer("status-mail-recipients", function() {
        const recipients = this.config.recipients || "";
        const $container = $("#status-emails-block");
        recipients.split(" ").filter(email => email).forEach(email => $container.append(Template.text("status-mail-recipient-row", {
            email: email,
            newRow: false
        })));
        $container.append(Template.text("status-mail-recipient-row", {
            email: "",
            newRow: true
        }));
    });
    this.addAction({
        click: "status-mail-recipient-row-delete"
    }, function() {
        const $row = this.el.closest("[data-status-mail-recipient-row]");
        const mailingId = $row.data("mailing-id");
        $row.remove();
        saveStatusEmails(mailingId, collectStatusEmails());
    });
    this.addAction({
        click: "status-mail-recipient-row-add",
        enterdown: "status-mail-recipient-change"
    }, function() {
        this.event.preventDefault();
        const $row = this.el.closest("[data-status-mail-recipient-row]");
        const $emailInput = $row.find("input");
        const email = $emailInput.val();
        if (email) {
            saveStatusEmails($row.data("mailing-id"), collectStatusEmails(true), () => {
                $row.before(Template.text("status-mail-recipient-row", {
                    email: email,
                    newRow: false
                }));
                $emailInput.val("");
            });
        }
    });
    this.addAction({
        enterdown: "send-mailing"
    }, function() {
        this.event.preventDefault();
        $("#send-btn").trigger("click");
    });
    const collectStatusEmails = (includeNewRow = false) => {
        let $inputs = $("[data-status-mail-recipient-row]").find("input");
        if (!includeNewRow) {
            $inputs = $inputs.not(":last");
        }
        return $inputs.map(function() {
            return $(this).val().trim();
        }).get().join(" ");
    };
    const saveStatusEmails = (mailingId, emails, callback) => {
        $.post(AGN.url(`/mailing/send/${mailingId}/save-statusmail-recipients.action`), {
            emails: emails
        }).done(resp => {
            if (resp.success && callback) {
                callback();
            }
            AGN.Lib.JsonMessages(resp.popups);
        });
    };
    this.addDomInitializer("delivery-status-view", function() {
        if (!this.config.isTransmissionRunning) {
            Helpers.hideGreenMarks();
        }
        const workStatus = this.config.workStatus;
        const workStatusTooltip = this.config.workStatusTooltip;
        if (workStatus && workStatusTooltip) {
            Helpers.updateWorkStatus(workStatus, workStatusTooltip);
        }
        if (this.config.deliveryStat) {
            const config = _.extend(this.config.deliveryStat, this.config.deliveryStatExtraInfo);
            renderButtonsBasedOnDeliveryStatus(config);
        }
    });
    function renderButtonsBasedOnDeliveryStatus(config) {
        const $buttons = Template.dom("delivery-status-buttons", config);
        $(".delivery-status-action").remove();
        $(".header__actions").append($buttons);
    }
    this.addAction({
        click: "start-delivery"
    }, function() {
        if ($("#test-run-options").val() == RECIPIENT_TEST_RUN_OPTION && !isMailinglistEmailsUsedForApproval()) {
            const existsAnyEmailAddress = $('input[name="mailingTestRecipients"]').get().some(input => $(input).val().trim());
            if (!existsAnyEmailAddress) {
                Messages.alert("error.enterEmailAddresses");
                return;
            }
        }
        $("#adminSendButton").addClass("disabled");
        $("#testSendButton").addClass("disabled");
        const form = Form.get(this.el);
        form.setActionOnce(this.el.data("url"));
        form.submit();
    });
    this.addAction({
        click: "add-test-recipient",
        enterdown: "new-test-recipient"
    }, function() {
        this.event.preventDefault();
        const $currentRow = this.el.closest("[data-test-recipient-row]");
        const $currentInput = this.el.is("input") ? this.el : $currentRow.find("input");
        const $newRow = Template.dom("test-recipient-row", {
            value: $currentInput.val() || "",
            newRow: false,
            sent: false
        });
        $currentRow.before($newRow);
        $currentInput.val("");
        AGN.runAll($newRow);
        $currentInput.focus();
        changeSaveTestRunTargetBtnState(false);
    });
    this.addAction({
        click: "remove-test-recipient"
    }, function() {
        const $tr = this.el.closest("[data-test-recipient-row]");
        $tr.remove();
        changeSaveTestRunTargetBtnState(false);
    });
    this.addAction({
        input: "new-test-recipient"
    }, function() {
        changeSaveTestRunTargetBtnState(false);
    });
    this.addAction({
        input: "edit-test-recipient",
        enterdown: "edit-test-recipient"
    }, function() {
        this.event.preventDefault();
        changeSaveTestRunTargetBtnState(false);
    });
    this.addAction({
        input: "edit-test-run-target-name"
    }, function() {
        changeSaveTestRunTargetBtnState(false);
    });
    this.addAction({
        enterdown: "edit-test-run-target-name"
    }, function() {
        this.event.preventDefault();
    });
    function changeSaveTestRunTargetBtnState(saved) {
        const $testRunTargetBtn = $("#testTargetSaveButton");
        const $btnIcon = $testRunTargetBtn.find("i");
        if (saved) {
            $btnIcon.hide();
        }
        $testRunTargetBtn.toggleClass("btn-primary", !saved, 500);
        $testRunTargetBtn.toggleClass("btn-success", saved, 500);
        if (saved) {
            $testRunTargetBtn.css({
                cursor: "not-allowed",
                "pointer-events": "none"
            });
        } else {
            $testRunTargetBtn.css({
                cursor: "",
                "pointer-events": ""
            });
        }
        $btnIcon.toggleClass("icon-save", !saved);
        $btnIcon.toggleClass("icon-check", saved);
        $btnIcon.show(500);
    }
    this.addAction({
        click: "save-target-for-test-run"
    }, function() {
        if (!isValidTestTargetNameField()) {
            return;
        }
        saveTargetName();
    });
    function isValidTestTargetNameField() {
        const $targetName = $('input[name="targetName"]');
        const form = Form.get($targetName);
        const errors = AGN.Lib.Validator.get("length").errors($targetName, {
            min: 3,
            required: true
        });
        if (!errors.length) {
            form.cleanFieldFeedback();
            return true;
        }
        errors.forEach(error => form.showFieldError$($targetName, error.msg));
        return false;
    }
    function saveTargetName() {
        $.ajax({
            type: "POST",
            url: AGN.url(`/mailing/send/${config.mailingId}/test/saveTarget.action`),
            data: {
                mailingTestRecipients: collectTestRunEmails(),
                targetName: $('input[name="targetName"]').val().trim()
            }
        }).done(resp => {
            if (resp.success === true) {
                changeSaveTestRunTargetBtnState(true);
            }
        });
    }
    function collectTestRunEmails() {
        return $('input[name="mailingTestRecipients"]').map(function() {
            return this.value.trim();
        }).get().filter(email => email);
    }
    this.addAction({
        focusout: "max-recipients-change"
    }, function() {
        clearMaxRecipientsValueIfZero();
    });
    function clearMaxRecipientsValueIfZero() {
        const $maxRecipients = $("#maxRecipients");
        if ($maxRecipients.exists() && $maxRecipients.val() === "0") {
            $maxRecipients.val("");
        }
    }
    this.addAction({
        change: "prioritization-toggle"
    }, function() {
        toggleButton($(this.el), "isPrioritizationDisallowed");
    });
    this.addAction({
        change: "encrypted-send-toggle"
    }, function() {
        toggleButton($(this.el), "isEncryptedSend");
    });
    this.addAction({
        change: "sendStatusOnErrorOnly-toggle"
    }, function() {
        toggleButton($(this.el), "statusOnErrorEnabled");
    });
    function toggleButton($toggle, propertyName) {
        const isChecked = $toggle.prop("checked");
        $toggle.prop("disabled", true);
        const failed = () => {
            $toggle.prop("checked", !isChecked);
            Messages.defaultError();
        };
        const data = {};
        data[propertyName] = $toggle.is(":checked");
        $.ajax({
            type: "POST",
            url: $toggle.data("url"),
            data: data
        }).done(resp => {
            if (resp && resp.success) {
                Messages.defaultSaved();
            } else {
                failed();
            }
        }).fail(failed).always(() => $toggle.prop("disabled", false));
    }
});

AGN.Lib.Controller.new("mailing-separate-statistics", function() {
    this.addAction({
        "table-column-manager:add": "update-columns"
    }, function() {
        const form = AGN.Lib.Form.get(this.el);
        form.setValueOnce("additionalFields", this.data.columns);
        form.setValueOnce("inEditColumnsMode", true);
        form.submit();
    });
    this.addAction({
        "table-column-manager:apply": "update-columns"
    }, function() {
        const selectedFields = this.data.columns;
        $.ajax({
            type: "POST",
            url: AGN.url("/statistics/mailing/setSelectedFields.action"),
            traditional: true,
            data: {
                selectedFields: selectedFields
            }
        }).done(resp => {
            if (resp.success) {
                AGN.Lib.WebStorage.extend("mailing-separate-stats-overview", {
                    fields: selectedFields
                });
            }
            AGN.Lib.JsonMessages(resp.popups);
        });
    });
});

AGN.Lib.Controller.new("mailing-settings-base-view", function() {
    const Messaging = AGN.Lib.Messaging;
    const Messages = AGN.Lib.Messages;
    const Form = AGN.Lib.Form;
    let selectedRemovedMailinglistId;
    let mailinglists = [];
    Messaging.subscribe("mailing-settings:updateMailinglistForFollowUp", () => {
        setMailingListSelectByFollowUpMailing();
    });
    this.addDomInitializer("mailing-settings-base-view", function() {
        selectedRemovedMailinglistId = this.config.selectedRemovedMailinglistId;
        mailinglists = this.config.mailinglists;
        if (selectedRemovedMailinglistId) {
            showRemovedMailinglistError(this.el);
        }
        updateGenerateButton();
        if (this.config.isFollowUpMailing) {
            setMailingListSelectByFollowUpMailing();
        }
    });
    function showRemovedMailinglistError($el) {
        Form.get($el).showFieldError("mailinglistId", t("fields.mailinglist.errors.removed"), true);
    }
    this.addAction({
        change: "save-mailing-list-id"
    }, function() {
        const mailinglistId = this.el.select2("val");
        Messaging.send("mailing-settings:mailinglistChanged", mailinglistId);
        if (selectedRemovedMailinglistId) {
            AGN.Lib.Select.get(this.el).$findOption(selectedRemovedMailinglistId).remove();
            Form.get($(this.el)).cleanFieldError("mailinglistId");
            selectedRemovedMailinglistId = null;
        }
        updateSenderAndReplyToFields(mailinglistId);
    });
    function updateSenderAndReplyToFields(mailinglistId) {
        const mailinglist = mailinglists.find(data => data.id === +mailinglistId);
        if (!mailinglist) {
            return;
        }
        const changedLabels = [ {
            value: mailinglist.senderEmail,
            $field: $("#emailSenderMail")
        }, {
            value: mailinglist.replyEmail,
            $field: $("#emailReplyEmail")
        }, {
            value: mailinglist.senderName,
            $field: $("#emailSenderName")
        }, {
            value: mailinglist.replyToName,
            $field: $("#emailReplyName")
        } ].filter(({value: value, $field: $field}) => value && $field.val() !== value).map(({value: value, $field: $field}) => {
            $field.val(value).trigger("change");
            return $(`label[for="${$field.attr("id")}"]`).text().trim().replaceAll(/\s*\*/g, "");
        });
        if (changedLabels.length) {
            Messages.info("mailing.default.sender_and_reply_emails_changed");
        }
    }
    this.addAction({
        "change input": "change-mailing-base-info"
    }, function() {
        updateGenerateButton();
    });
    function updateGenerateButton() {
        const $generateBtn = $("#generateBtn");
        if (!$generateBtn.exists()) {
            return;
        }
        const isFormValid = Form.get($generateBtn).valid();
        $generateBtn.toggleClass("btn-grey-out", !isFormValid);
        AGN.Lib.Tooltip.toggleState($generateBtn, !isFormValid);
    }
    this.addAction({
        change: "set-parent-mail-mailinglist"
    }, function() {
        setMailingListSelectByFollowUpMailing();
    });
    function setMailingListSelectByFollowUpMailing() {
        const parentMailingId = $("#lightWeightMailingList").val();
        const selectedParentMailingMailingListId = $(`#parentmailing-${parentMailingId}-mailinglist`).attr("data-mailing-list-id");
        const mailingListSelect = AGN.Lib.Select.get($("#settingsGeneralMailingList"));
        mailingListSelect.selectOption(selectedParentMailingMailingListId);
        mailingListSelect.setReadonly(true);
    }
    this.addAction({
        click: "generate-mailing-for-workflow"
    }, function() {
        const form = Form.get(this.el);
        if (!form.validate()) {
            return;
        }
        form.jqxhr().done(resp => {
            if (resp.success) {
                Messaging.send("workflow:mailingCreated", resp.data);
                AGN.Lib.Modal.getInstance(this.el).hide();
            } else {
                AGN.Lib.JsonMessages(resp.popups, true);
            }
        });
    });
});

AGN.Lib.Controller.newExtended("mailing-settings-view", "mailing-settings-base-view", function() {
    const Form = AGN.Lib.Form;
    const Select = AGN.Lib.Select;
    const Modal = AGN.Lib.Modal;
    const Messages = AGN.Lib.Messages;
    const Template = AGN.Lib.Template;
    const Messaging = AGN.Lib.Messaging;
    const recipientsCountRelatedFields = [ "#settingsGeneralMailingList", "#settingsTargetgroupsListSplit", "#settingsTargetgroupsListSplitPart", "#lightWeightMailingList", "#assignTargetGroups", "#targetGroupIds", "#altgIds", "#followUpType", "#followup-exclude-proxy-openers" ];
    let config;
    let isChangeMailing = false;
    let lastSelectedTargetsIds = [];
    let mailingListSelect;
    let lastMailingListId = 0;
    let lastDataForCountingRecipients;
    let mediaTypePriorityChanged = false;
    let isStandaloneSmsMailing = false;
    let mailingType;
    let $form;
    Messaging.subscribe("mailing-settings:mailinglistChanged", mailinglistId => {
        if (!isFollowUpMailing()) {
            lastMailingListId = mailinglistId;
        }
    });
    this.addDomInitializer("mailing-settings-view", function() {
        config = this.config;
        addRecipientsCountListener();
        $form = $("#mailingSettingsForm");
        isStandaloneSmsMailing = config.isStandaloneSmsMailing;
        mailingType = config.mailingType;
        lastSelectedTargetsIds = $("#targetGroupIds").val() || [];
        displayTargetModeToggle(lastSelectedTargetsIds.length > 1);
        mailingListSelect = Select.get($("#settingsGeneralMailingList"));
        mailingListSelect.setReadonly(false);
        if (lastMailingListId > 0) {
            lastMailingListId = mailingListSelect.selectOption(lastMailingListId);
            mailingListSelect.$el.trigger("change");
        }
        drawMailingTypeSettings();
        updateGeneralMailingTypeView();
        configureFormChangesTracking();
        refreshTargetModeLabel();
        onMediatypesUpdate();
        initMediatypesSortable();
        lockSmsSwitchWhenRcsActive();
    });
    function initMediatypesSortable() {
        getMediatypes$().sortable({
            delay: 10,
            scroll: true,
            scrollSensitivity: 30,
            scrollSpeed: 5,
            handle: ".mediatype-order-handle",
            cursor: "move",
            items: ".mediatype-item",
            stop: () => _.each($(".mediatype-item .input-group span:first-child"), (el, i) => $(el).text(i + 1))
        });
    }
    function getMediatypes$() {
        return $("#mediatypes-list");
    }
    function addRecipientsCountListener() {
        $(recipientsCountRelatedFields.join(",")).on("change", function() {
            isChangeMailing = true;
            if (!lastDataForCountingRecipients) {
                return;
            }
            const actualDataForCountingRecipients = getDataForCountingRecipients();
            if (!_.isEqual(actualDataForCountingRecipients, lastDataForCountingRecipients)) {
                lastDataForCountingRecipients = null;
                setRecipientsCountValue("?");
            }
        });
    }
    function refreshTargetModeLabel() {
        const isTargetModeOR = getTargetModeVal() === config.TARGET_MODE_OR;
        $("#target-mode-description").text(t(`mailing.default.targetmode_${isTargetModeOR ? "or" : "and"}`));
    }
    function getTargetModeVal() {
        return $("[name='targetMode']:checked").val();
    }
    function isDirtyOnlyNonEditableFields() {
        const dirtyFields = $form.dirty("showDirtyFields");
        if (dirtyFields.length > 0) {
            const filtered = dirtyFields.filter(function(_, e) {
                const $el = $(e);
                return !($el.prop("readonly") === true || $el.is(":disabled") || $el.prop("type") === "hidden");
            });
            return filtered.length === 0;
        } else {
            return false;
        }
    }
    function configureFormChangesTracking() {
        $form.dirty("destroy");
        $form.dirty({
            preventLeaving: true,
            leavingMessage: t("grid.layout.leaveQuestion"),
            onDirty: function() {
                if (isDirtyOnlyNonEditableFields() && !mediaTypePriorityChanged) {
                    $form.dirty("setAsClean");
                }
            }
        });
        if (isDirtyOnlyNonEditableFields() && !mediaTypePriorityChanged) {
            $form.dirty("setAsClean");
        }
        mediaTypePriorityChanged = false;
    }
    window.onbeforeunload = function() {
        if (!$form.dirty("isDirty") === true) {
            AGN.Lib.Loader.show();
        }
    };
    function displayTargetModeToggle(show) {
        $("#target-mode-box").toggle(show);
        $("#regular-targets-box").toggleClass("border rounded p-2", show);
    }
    this.addAction({
        change: "selectTargetGroups"
    }, function() {
        const newTargetIds = this.el.val() || [];
        if (newTargetIds.length > 1 && lastSelectedTargetsIds.length <= 1) {
            $("#target-mode-and-btn").prop("checked", true);
        }
        displayTargetModeToggle(newTargetIds.length > 1);
        lastSelectedTargetsIds = newTargetIds;
    });
    function getFieldsData(selectors) {
        const data = {};
        selectors.forEach(selector => {
            const $input = $(selector);
            const hiddenByOtherSettings = $input.closest(".hidden", $input.closest(".mailing-settings-tab")[0]).length > 0;
            if ($input.exists() && !hiddenByOtherSettings && !$input.prop("disabled")) {
                const name = $input.prop("name");
                if (name) {
                    data[name] = data[name] = $input.is(":checkbox") ? $input.prop("checked") : $input.val();
                }
            }
        });
        return data;
    }
    this.addAction({
        click: "calculateRecipients"
    }, function() {
        if (config) {
            lastDataForCountingRecipients = getDataForCountingRecipients();
            $.ajax({
                type: "POST",
                url: AGN.url("/mailing/ajax/" + config.mailingId + "/calculateRecipients.action"),
                traditional: true,
                data: lastDataForCountingRecipients
            }).always(function(resp) {
                if (resp && resp.success === true) {
                    setRecipientsCountValue(resp.count);
                } else {
                    setRecipientsCountValue("?");
                    Messages.defaultError();
                }
            });
        }
    });
    function getDataForCountingRecipients() {
        return $.extend(getFieldsData(recipientsCountRelatedFields), {
            changeMailing: isChangeMailing,
            targetMode: getTargetModeVal(),
            isWmSplit: config.wmSplit
        });
    }
    function setRecipientsCountValue(value) {
        $("#number-of-recipients").val(value);
    }
    this.addAction({
        change: "change-general-mailing-type"
    }, function() {
        mailingType = this.el.val();
        mailingListSelect.setReadonly(false);
        if (lastMailingListId > 0) {
            mailingListSelect.selectOption(lastMailingListId);
        }
        updateGeneralMailingTypeView();
    });
    this.addAction({
        change: "change-target-mode"
    }, refreshTargetModeLabel);
    function isFollowUpMailing() {
        return config.FOLLOWUP_MAILING_TYPE == mailingType;
    }
    function isActionBasedMailing() {
        return config.ACTIONBASED_MAILING_TYPE == mailingType;
    }
    function isDateBasedMailing() {
        return config.DATEBASED_MAILING_TYPE == mailingType;
    }
    function drawMailingTypeSettings() {
        const $settings = $("#mailing-type-settings-block");
        $settings.html(Template.text("mailing-type-settings", {
            mailingType: mailingType,
            isStandaloneSmsMailing: isStandaloneSmsMailing
        }));
        AGN.runAll($settings);
    }
    function updateGeneralMailingTypeView() {
        let showFollowUpControls = false;
        if (config.followUpAllowed) {
            if (isFollowUpMailing()) {
                Messaging.send("mailing-settings:updateMailinglistForFollowUp");
                showFollowUpControls = true;
            }
            toggle(showFollowUpControls, "#followUpControls");
            $("#followUpControls").all(":input").each((i, el) => $(el).prop("disabled", !showFollowUpControls));
        }
        const showBccRecipients = isDateBasedMailing();
        toggle(showBccRecipients, "#mailing-bcc-recipients");
        $("#mailing-bcc-recipients").prop("disabled", !showBccRecipients);
        const showTargetGroups = isActionBasedMailing() ? config.campaignEnableTargetGroups : true;
        toggle(showTargetGroups, "#regular-targets-box, #calculate-recipients-box");
    }
    function toggle(show, selector) {
        const $container = $(selector);
        if ($container) {
            if (show) {
                $container.removeClass("hidden");
                $container.show();
            } else {
                $container.addClass("hidden");
                $container.hide();
            }
        }
    }
    this.addAction({
        change: "change-mediatype"
    }, function() {
        const $el = $(this.el);
        const $switches = $("#email-mediatype-switch, #sms-mediatype-switch, #rcs-mediatype-switch");
        const activeMediatypes = $switches.filter(":checked").map((_, el) => $(el).closest(".mediatype-item").data("mediatype")).get();
        const active = isMediatypeListElemActive($el);
        redrawMediatypeCheckboxes($el, active);
        $("#edit-frame-content-btn").toggle($switches.is(":checked"));
        if ($el.data("mediatype") === "rcs") {
            syncSmsSwitchWithRcs(active);
        }
        const isStandaloneSmsMailingBefore = isStandaloneSmsMailing;
        isStandaloneSmsMailing = activeMediatypes.length === 1 && activeMediatypes.includes("sms");
        if (isStandaloneSmsMailingBefore !== isStandaloneSmsMailing) {
            drawMailingTypeSettings();
        }
    });
    function lockSmsSwitchWhenRcsActive() {
        if ($("#rcs-mediatype-switch").is(":checked")) {
            syncSmsSwitchWithRcs(true);
        }
    }
    function syncSmsSwitchWithRcs(active) {
        const $smsSwitch = $("#sms-mediatype-switch");
        $smsSwitch.prop("readonly", active);
        if (active && !$smsSwitch.is(":checked")) {
            $smsSwitch.prop("checked", true).trigger("change");
        }
    }
    function isMediatypeListElemActive($el) {
        return $el.find("input:checkbox:first").is(":checked");
    }
    function prioritizeMediatypeCheckboxes() {
        const checkboxesContainer = getMediatypes$();
        const checkboxes = getSortedMediatypeCheckboxes();
        checkboxesContainer.empty();
        checkboxes.forEach(function(item) {
            checkboxesContainer.append(item);
        });
    }
    function getSortedMediatypeCheckboxes() {
        return $("#mediatypes-list li").toArray().sort(function(a, b) {
            const $a = $(a);
            const $b = $(b);
            if (!isMediatypeListElemActive($a) && isMediatypeListElemActive($b)) return 1;
            if (isMediatypeListElemActive($a) && !isMediatypeListElemActive($b)) return -1;
            return $a.data("priority") - $b.data("priority");
        });
    }
    function redrawMediatypeCheckboxes($el, active) {
        prioritizeMediatypeCheckboxes();
        displayArrows($el, active);
    }
    function displayArrows($el, active) {
        if (active) {
            $el.find(".form-switch").after(getMediatypeControlArrows());
        } else {
            $el.find(".list-group-item-controls").remove();
        }
        onMediatypesUpdate();
    }
    function hideFirstAndLastMediatypeControlArrows() {
        const $list = getMediatypes$();
        $list.find("a").css("opacity", "1");
        $list.find(".icon-angle-up:first, .icon-angle-down:last").css("opacity", "0");
    }
    function onMediatypesUpdate() {
        hideFirstAndLastMediatypeControlArrows();
        toggleMediatypeOrderDragButtons();
        updateMediatypeSequenceLabels();
        Form.get(getMediatypes$()).initFields();
    }
    function toggleMediatypeOrderDragButtons() {
        const show = getMediatypes$().find(".form-check-input").toArray().every(mt => mt.checked);
        getMediatypes$().find(".mediatype-order-handle").toggle(show);
    }
    function getMediatypeControlArrows() {
        return `\n          <div class='list-group-item-controls'>\n              <a href='#' class='icon icon-angle-down fs-2' data-action='prioritise-mediatype-down'></a>\n              <a href='#' class='icon icon-angle-up fs-2' data-action='prioritise-mediatype-up'></a>\n          </div>`;
    }
    this.addAction({
        click: "prioritise-mediatype-up"
    }, function() {
        prioritiseMediatypes($(this.el).closest("li"), true);
    });
    this.addAction({
        click: "prioritise-mediatype-down"
    }, function() {
        prioritiseMediatypes($(this.el).closest("li"), false);
    });
    function isMediatypeCanBeMoved($el, up) {
        return up && $el.prev().length || !up && $el.next().length && isMediatypeListElemActive($el.next());
    }
    function prioritiseMediatypes($el, up) {
        mediaTypePriorityChanged = true;
        if (isMediatypeCanBeMoved($el, up)) {
            if (up) {
                $el.prev().before($el);
            } else {
                $el.next().after($el);
            }
            $form.dirty("setAsDirty");
            onMediatypesUpdate();
        }
    }
    function updateMediatypeSequenceLabels() {
        _.each($(".mediatype-item .input-group span:first-child"), (el, i) => $(el).text(i + 1));
    }
    this.addAction({
        submission: "save"
    }, saveMailing);
    function saveMailing() {
        const form = Form.get($form);
        setMediatypesPrioritiesToForm(form);
        setParamsToForm(form);
        form.submit();
    }
    function setMediatypesPrioritiesToForm(form) {
        _.each($("#mediatypes-list li"), function(el, i) {
            form.setValueOnce($(el).data("mediatype") + "Mediatype.priority", i);
        });
    }
    function setParamsToForm(form) {
        const $mailingParamsTable = $("#mailingParamsTable");
        if (!$mailingParamsTable.exists()) {
            return;
        }
        _.each($mailingParamsTable.data("table").collect(), function(param, index) {
            form.setValueOnce("params[" + index + "].name", param.name);
            form.setValueOnce("params[" + index + "].value", param.value);
            form.setValueOnce("params[" + index + "].description", param.description);
        });
    }
    this.addAction({
        click: "edit-content-modal"
    }, function() {
        const showText = $("#email-mediatype-switch").prop("checked") || config.isMailingGrid;
        const showHtml = showText && !$("#emailMailFormat").val() == 0 && !config.isMailingGrid;
        const showSms = $("#sms-mediatype-switch").prop("checked");
        const showRcs = $("#rcs-mediatype-switch").prop("checked");
        AGN.Lib.Modal.fromTemplate("modal-editor", {
            showText: showText,
            showHtml: showHtml,
            showSms: showSms,
            showRcs: showRcs
        });
    });
    this.addAction({
        click: "save-content"
    }, function() {
        let $contentForm = $("#content-form");
        if (!Form.get($contentForm).validate()) {
            return;
        }
        Modal.getInstance($contentForm).hide();
        saveMailing();
    });
    this.addAction({
        "editor:change": "validate-on-change"
    }, function() {
        Form.get(this.el).validateField(this.el);
    });
});

AGN.Lib.Controller.new("mailing-simple-tracking-points-stat", function() {
    const Template = AGN.Lib.Template;
    const BAR_HEIGHT_PX = 15;
    const SINGLE_TARGET_BAR_HEIGHT_PX = 25;
    const CATEGORY_PERCENTAGE = .8;
    const BAR_PERCENTAGE = .8;
    const CHART_PADDING_PX = 16;
    let config;
    let $container;
    let selectedTargets;
    const metrics = {
        net: t("statistics.trackingPoint.netRequests"),
        gross: t("statistics.trackingPoint.grossRequests")
    };
    const tableOptions = {
        pagination: false,
        domLayout: "autoHeight",
        showRecordsCount: "simple"
    };
    this.addDomInitializer("simple-tracking-points-stat-view", function() {
        config = this.config;
        $container = this.el;
        selectedTargets = getSelectedTargets();
        assignColors();
        fetchData().done(resp => {
            render(resp.trackingPoints);
            $("#stat-loader").addClass("hidden");
            $container.removeClass("invisible");
        });
    });
    function getSelectedTargets() {
        const targetGroupsMap = new Map(config.targetGroups.map(target => [ target.id, target ]));
        const result = config.selectedTargets.map(id => targetGroupsMap.get(parseInt(id)));
        result.unshift(getAllRecipientsTargetGroup());
        return result;
    }
    function assignColors() {
        const colors = AGN.Lib.Helpers.getStatColorsHexValues();
        selectedTargets.forEach((tg, idx) => tg.color = colors[idx % colors.length]);
    }
    function fetchData() {
        return $.get(AGN.url(`/statistics/mailing/${config.mailingId}/simpleTrackingPoints.action`), {
            targetGroups: config.selectedTargets
        });
    }
    function render(trackingPoints) {
        Object.entries(metrics).forEach(([metricName, metricLabel]) => {
            const $row = Template.dom("tracking-point-metric-row", {
                metricName: metricName,
                metricLabel: metricLabel,
                chartHeight: `${getChartHeightInPx(trackingPoints)}px`
            });
            $container.append($row);
            renderMetric(trackingPoints, metricName, $row);
        });
    }
    function getBarHeightPx() {
        return selectedTargets.length === 1 ? SINGLE_TARGET_BAR_HEIGHT_PX : BAR_HEIGHT_PX;
    }
    function getChartHeightInPx(trackingPoints) {
        const axisLength = trackingPoints.length * selectedTargets.length * getBarHeightPx() / (CATEGORY_PERCENTAGE * BAR_PERCENTAGE);
        return Math.ceil(axisLength) + CHART_PADDING_PX;
    }
    function renderMetric(trackingPoints, metricName, $row) {
        const $metric = $row.find(`[data-stat-metric="${metricName}"]`);
        renderChart(trackingPoints, metricName, $metric.find("canvas"));
        renderTable(trackingPoints, metricName, $metric.find(".table-wrapper"));
    }
    function renderChart(trackingPoints, metricName, $canvas) {
        new Chart($canvas[0].getContext("2d"), {
            type: "bar",
            data: {
                labels: trackingPoints.map(tp => tp.trackingPointName),
                datasets: prepareChartDatasets(trackingPoints, metricName)
            },
            options: {
                indexAxis: "y",
                scales: {
                    x: {
                        display: false
                    }
                },
                plugins: {
                    datalabels: {
                        display: false
                    }
                }
            }
        });
    }
    function prepareChartDatasets(trackingPoints, metricName) {
        return selectedTargets.map(tg => ({
            label: tg.targetName,
            data: trackingPoints.map(tp => resolveMetricValue(tp, tg, metricName)),
            backgroundColor: tg.color,
            categoryPercentage: CATEGORY_PERCENTAGE,
            barPercentage: BAR_PERCENTAGE,
            minBarLength: 2
        }));
    }
    function renderTable(trackingPoints, metricName, $tableWrapper) {
        const rows = prepareTableRows(trackingPoints, metricName);
        new AGN.Lib.Table($tableWrapper, getTableColumnsDefinitions(trackingPoints, metricName), rows, tableOptions);
    }
    function prepareTableRows(trackingPoints, metricName) {
        return selectedTargets.map(tg => {
            const row = {
                targetGroup: tg.targetName,
                color: tg.color
            };
            trackingPoints.forEach(tp => row[makeTrackingPointPropertyKey(tp.id)] = resolveMetricValue(tp, tg, metricName));
            return row;
        });
    }
    function resolveMetricValue(trackingPoint, targetGroup, metricName) {
        const entry = trackingPoint.metrics[metricName].find(item => item.targetGroupId === targetGroup.id);
        return entry?.value ?? 0;
    }
    function getTableColumnsDefinitions(trackingPoints, metricName) {
        const columns = [ {
            headerName: metrics[metricName],
            cellRenderer: "MustacheTemplateCellRender",
            cellRendererParams: {
                templateName: "tracking-point-tg-cell"
            },
            type: "textCaseInsensitiveColumn",
            field: "targetGroup",
            sortable: false
        } ];
        trackingPoints.forEach(tp => columns.push(getTrackingPointColumnDefinition(tp)));
        return columns;
    }
    function getTrackingPointColumnDefinition(trackingPoint) {
        return {
            headerName: trackingPoint.trackingPointName,
            cellRenderer: "MustacheTemplateCellRender",
            cellRendererParams: {
                templateName: "statistics-number-cell"
            },
            field: makeTrackingPointPropertyKey(trackingPoint.id),
            type: "textCaseInsensitiveColumn",
            sortable: false
        };
    }
    function getAllRecipientsTargetGroup() {
        return {
            id: null,
            targetName: t("statistics.default.allRecipients")
        };
    }
    function makeTrackingPointPropertyKey(trackingPointId) {
        return `trackingPoint${trackingPointId}`;
    }
});

