AGN.Lib.Controller.new("mailing-trackable-links", function() {
    const self = this;
    const Form = AGN.Lib.Form;
    let scrollToElemId;
    let KEEP_UNCHANGED;
    let SAVE_ALL_URL;
    this.addDomInitializer("mailing-trackable-links", function() {
        KEEP_UNCHANGED = this.config.KEEP_UNCHANGED;
        SAVE_ALL_URL = this.config.SAVE_ALL_URL;
        if (this.config.scrollToLinkId) {
            scrollTo($(`#link-${this.config.scrollToLinkId}`));
        }
    });
    AGN.Lib.Action.new({
        change: "[id^=link-], #tile-trackableLinkEditAll"
    }, function() {
        scrollToElemId = this.el.attr("id");
    });
    this.addAction({
        click: "save-bulk-actions"
    }, function() {
        const form = Form.get($("#trackableLinksForm"));
        const bulkActionsFormData = $("#bulkActionsForm").serializeFormDataObject();
        form._data = {};
        $.each(bulkActionsFormData, function(k, v) {
            form.setValue(k, v);
        });
        form.setValue("modifyAllLinksExtensions", false);
        setExtensionsToForm(AGN.Lib.InputTable.get("#bulkActionExtensions").collect(), form);
        form.setActionOnce(SAVE_ALL_URL);
        form.submit();
        AGN.Lib.Modal.getWrapper(this.el).modal("hide");
    });
    this.addAction({
        submission: "save-all"
    }, function() {
        this.event.preventDefault();
        const form = Form.get($("#trackableLinksForm"));
        form._data = {};
        form.setValue("modifyBulkLinksExtensions", false);
        keepBulkSettingsUnchanged(form);
        setExtensionsToForm(AGN.Lib.InputTable.get("#link-common-extensions").collect(), form);
        form.setActionOnce(SAVE_ALL_URL);
        form.submit();
    });
    this.addAction({
        scrollTo: "scroll-to"
    }, function() {
        if (scrollToElemId) {
            scrollTo($(this.el).find("#" + scrollToElemId));
        }
    });
    function scrollTo($target) {
        if ($target && $target.length > 0) {
            const $scrollContainer = $target.closest(".table-wrapper__body");
            if ($scrollContainer.exists()) {
                const highestOffsetTop = $scrollContainer.find(":first-child").offset().top;
                const targetOffsetTop = $target.offset().top;
                $scrollContainer.scrollTop(0);
                $scrollContainer.scrollTop(targetOffsetTop - highestOffsetTop);
            }
        }
    }
    this.addAction({
        click: "save-individual"
    }, function() {
        this.event.preventDefault();
        const form = Form.get($("#trackableLinkForm"));
        const extensions = AGN.Lib.InputTable.get("#individual-extensions").collect();
        setExtensionsToForm(extensions, form);
        form.submit();
    });
    this.addAction({
        change: "link-details-trackable"
    }, function() {
        self.runInitializer("trackableAction");
    });
    this.addInitializer("trackableAction", function() {
        const $trigger = $('[data-action="link-details-trackable"] :selected');
        const $linkAction = $("#linkAction");
        $linkAction.prop("disabled", $linkAction.prop("disabled") || $trigger.val() == 0);
    });
    function setExtensionsToForm(extensions, form) {
        _.each(extensions, function(extension, index) {
            form.setValue("extensions[" + index + "].name", extension.name);
            form.setValue("extensions[" + index + "].value", extension.value);
        });
    }
    function keepBulkSettingsUnchanged(form) {
        form.setValue("bulkUsage", KEEP_UNCHANGED);
        form.setValue("bulkAction", KEEP_UNCHANGED);
        form.setValue("bulkDeepTracking", KEEP_UNCHANGED);
        form.setValue("bulkStatic", KEEP_UNCHANGED);
    }
});

AGN.Lib.Controller.new("uploads-overview", function() {
    const Form = AGN.Lib.Form;
    function putFileProbesToForm(files) {
        const formData = new FormData;
        $.each(files, function(i, file) {
            const probe = new File([ file.slice(0, 10240) ], file.name, {
                type: file.type
            });
            formData.append("probes", probe);
        });
        return formData;
    }
    this.addAction({
        "upload:dropped": "show-upload-form-modal"
    }, function() {
        const files = this.data;
        $.post({
            url: AGN.url("/upload/new.action"),
            data: putFileProbesToForm(files),
            processData: false,
            contentType: false
        }).done(resp => {
            AGN.Lib.Page.render(resp);
            if ($(resp).all(".modal").exists()) {
                $(".modal").on("modal:close", clearDropzone);
                addFilesInfoToModal(files);
            } else {
                clearDropzone();
            }
        });
    });
    function addFilesInfoToModal(files) {
        if (files.length > 1) {
            addFilesTableToModal(files);
            return;
        }
        $("#file-names").append(files[0].name);
    }
    function clearDropzone() {
        $("#files").val("");
        AGN.Lib.Upload.get($("#dropzone")).reset();
    }
    this.addAction({
        click: "save-file"
    }, function() {
        const form = Form.get(this.el);
        const jqxhr = form.submit();
        if (jqxhr) {
            jqxhr.done(resp => {
                AGN.Lib.Modal.getWrapper(form.get$()).modal("hide");
                AGN.Lib.JsonMessages(resp.popups);
            });
            $(".modal").hide();
        }
    });
    function getFilesTableColumnDefs() {
        return [ {
            field: "name",
            headerName: t("defaults.name"),
            filter: false,
            suppressMovable: true,
            cellRenderer: "NotEscapedStringCellRenderer"
        }, {
            field: "size",
            headerName: t("defaults.size"),
            filter: false,
            suppressMovable: true,
            width: 50,
            cellRenderer: "NotEscapedStringCellRenderer"
        } ];
    }
    function getFilesDataForTable(files) {
        return files.map(({name: name, size: size}) => ({
            name: name,
            size: AGN.Lib.Helpers.formatBytes(size)
        }));
    }
    function addFilesTableToModal(files) {
        const table = new AGN.Lib.Table(AGN.Lib.Template.dom("js-table-wrapper"), getFilesTableColumnDefs(), getFilesDataForTable(files), {
            pagination: false
        });
        const $tableWrapper = $('<div class="col-12">').append(table.$el);
        table.$el.css({
            "--ag-rows-count": files.length,
            "max-height": "235px"
        });
        $getUploadForm().find(".row:first").prepend($tableWrapper);
    }
    this.addAction({
        "table-column-manager:add": "update-columns"
    }, function() {
        const form = AGN.Lib.Form.get(this.el);
        form.setValueOnce("additionalColumnNames", this.data.columns);
        form.setValueOnce("inEditColumnsMode", true);
        form.submit();
    });
    this.addAction({
        "table-column-manager:apply": "update-columns"
    }, function() {
        const additionalColumnNames = this.data.columns;
        $.ajax({
            type: "POST",
            url: AGN.url("/upload/list/setSelectedFields.action"),
            traditional: true,
            data: {
                additionalColumnNames: additionalColumnNames
            }
        }).done(resp => {
            if (resp.success) {
                AGN.Lib.WebStorage.extend("upload-overview", {
                    fields: additionalColumnNames
                });
            }
            AGN.Lib.JsonMessages(resp.popups);
        });
    });
    function $getUploadForm() {
        return $("#upload-form");
    }
});

AGN.Lib.Controller.new("user-and-groups-permissions", function() {
    let permissions;
    this.addDomInitializer("user-and-groups-permissions", function() {
        permissions = collectPermissions(this.config);
        switchCategory(+getVisibleCategory$().first().attr("id").match(/\d+/)[0]);
        updatePermissionsCounter();
    });
    function collectPermissions(config) {
        if (config.isSoapUser) {
            return collectSoapUserPermissions(config);
        }
        return collectAdminOrRestUserPermissions(config);
    }
    function collectSoapUserPermissions(config) {
        const permissions = config.permissions.map(permission => ({
            ...permission,
            name: permission.endpointName
        }));
        return [ ...permissions, ...config.permissionGroups ];
    }
    function collectAdminOrRestUserPermissions(config) {
        return config.permissionCategories.map(function(category) {
            return category.subCategories;
        }).flatMap(function(subcategories) {
            return Object.values(subcategories);
        }).flatMap(function(subcategory) {
            return subcategory.permissions;
        });
    }
    function getCategoryPermissions$(categoryIndex) {
        return $(`#${categoryIndex}-category-permissions`).find(".permission:not(.hidden)");
    }
    function getCategoriesButtons$() {
        return $(".permission-categories__btn");
    }
    function updatePermissionsCounter() {
        _.each(getCategoriesButtons$(), function(button) {
            const $button = $(button);
            const categoryIndex = $button.data("category-index");
            const $categoryPermissions = getCategoryPermissions$(categoryIndex);
            const categoryPermissionsCount = $categoryPermissions.length;
            const activePermissionsCount = $categoryPermissions.find('[role="switch"]:checked').length;
            $(`label[for="${categoryIndex}-category-btn"] .permissions-counter`).text(`(${activePermissionsCount}/${categoryPermissionsCount})`);
            $button.toggleClass("disabled", categoryPermissionsCount <= 0);
        });
    }
    function getVisibleCategory$() {
        return $('[id$="-category-permissions"]:visible');
    }
    function scrollPermissionsTop() {
        $(`[id$="-category-permissions"]:visible .tile-body`).scrollTop(0);
    }
    function switchCategory(categoryIndex) {
        showCategoryPermissions(categoryIndex);
        scrollPermissionsTop(categoryIndex);
        $('[id$="-category-btn"]').prop("checked", false);
        $(`#${categoryIndex}-category-btn`).prop("checked", true);
        triggerToggleAllUpdate();
    }
    function showCategoryPermissions(categoryIndex) {
        $('[id$="-category-permissions"]').hide();
        $(`#${categoryIndex}-category-permissions`).show();
        controlSubCategoriesDisplaying();
    }
    this.addAction({
        click: "change-category"
    }, function() {
        switchCategory(this.el.data("category-index"));
    });
    function showPermissionsByFilters() {
        permissions.filter(permission => shouldBeShownByFilters(permission)).map(permission => $('[id="' + permission.name + '"]').closest(".permission")).forEach(permission => permission.removeClass("hidden"));
    }
    function switchToFirstActiveCategory() {
        const $enabledCategories = getCategoriesButtons$().not(".disabled");
        if (getVisiblePermissions$().length > 0 || $enabledCategories.length <= 0) {
            return;
        }
        switchCategory(+$enabledCategories.first().data("category-index"));
    }
    this.addAction({
        click: "apply-filter",
        enterdown: "handle-filter-enterdown"
    }, function() {
        this.event.preventDefault();
        hideAllPermissions();
        showPermissionsByFilters();
        controlSubCategoriesDisplaying();
        updatePermissionsCounter();
        switchToFirstActiveCategory();
        scrollPermissionsTop();
        triggerToggleAllUpdate();
    });
    function allowedByTypeFilter(permission) {
        const types = $("#type-filter").val();
        if (!types?.length) {
            return true;
        }
        return types.some(filter => getPredicateByFilter(filter)(permission));
    }
    function allowedByNameFilter(permission) {
        const filterVal = $("#name-filter").val().trim().toLowerCase();
        const name = $(`#${permission.name.replaceAll(".", "\\.")}`).parent().find("label").text().toLowerCase().trim();
        return !filterVal || name.includes(filterVal);
    }
    function allowedByRightFilter(permission) {
        const filterVal = $("#right-filter").val()?.trim()?.toLowerCase();
        return !filterVal || permission.name.toLowerCase().includes(filterVal);
    }
    function shouldBeShownByFilters(permission) {
        return allowedByNameFilter(permission) && allowedByRightFilter(permission) && allowedByTypeFilter(permission);
    }
    function getPredicateByFilter(filter) {
        switch (filter) {
          case "granted":
            return function(permission) {
                return permission.granted;
            };

          case "grantedForUser":
            return function(permission) {
                return permission.granted && !permission.showInfoTooltip;
            };

          case "grantedByGroup":
            return function(permission) {
                return permission.showInfoTooltip;
            };

          case "grantable":
            return function(permission) {
                return !permission.granted && permission.changeable;
            };

          case "notGrantable":
            return function(permission) {
                return !permission.granted && !permission.changeable;
            };

          case "new":
            return function(permission) {
                return permission.recent;
            };

          default:
            return function() {
                return true;
            };
        }
    }
    function showAllSubCategories() {
        $(".permission_category-subcategory").show();
    }
    function getVisiblePermissions$() {
        return getVisibleCategory$().find(".permission:visible");
    }
    function controlNoResultsInfoDisplay() {
        const shown = getVisiblePermissions$().length <= 0;
        $(".no-results-found").toggle(shown);
    }
    function controlSubCategoriesDisplaying() {
        showAllSubCategories();
        $(".permission_category-subcategory").each(function() {
            return $(this).toggle($(this).find("li:visible").length > 0);
        });
        controlNoResultsInfoDisplay();
    }
    function hideAllPermissions() {
        $(".permission").addClass("hidden");
    }
    function triggerToggleAllUpdate() {
        getVisibleCategory$().find("[data-toggle-checkboxes]").trigger("update-toggle-all");
    }
});

